window.CATALOG = {"version":1,"updatedAt":"2026-11-09T08:26:54.531662+00:00","since":"2023-09-13","channel":"notdandeliongirl","topics":[{"id":"inventory","title":"Запасы, планирование","number":"01"},{"id":"price","title":"Цена, TCO","number":"02"},{"id":"negotiation","title":"Переговоры","number":"03"},{"id":"supplier","title":"Поставщики, SRM","number":"04"},{"id":"data","title":"Данные, НСИ","number":"05"},{"id":"ai","title":"ИИ, автоматизация","number":"06"},{"id":"function","title":"Закупочная функция","number":"07"},{"id":"finance","title":"Деньги, финансовый эффект","number":"08"}],"terms":[{"id":"moq","name":"MOQ","subtitle":"Минимальная партия заказа","description":"Минимальное количество товара, которое поставщик принимает в один заказ.","topics":["inventory","negotiation"],"patterns":["\\bmoq\\b","минимальн.{0,25}(парт|объем|объём)","минимум.{0,15}заказ"],"queries":["(больш|лишн|много|больше).{0,30}(парти|куп|заказ|нужн)","(требует|заставляет).{0,30}(брать|куп|больш)"],"related":["leadtime","working-capital","turnover"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"tco","name":"TCO, ССВ","subtitle":"Совокупная стоимость владения","description":"Все затраты на приобретение, использование, обслуживание и завершение использования товара или актива за выбранный период.","topics":["price"],"patterns":["\\btco\\b","тсо","ссв","стоимост.{0,15}владени"],"queries":["(дешев|низк.{0,8}цен).{0,40}(дорог|затрат|выгод)","полная стоимость"],"related":["deferral","price-change","working-capital"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"leadtime","name":"Lead time","subtitle":"Срок поставки","description":"Время от размещения заказа до получения поставки.","topics":["inventory"],"patterns":["lead.?time","лид.?тайм","срок.{0,12}постав"],"queries":["долго.{0,20}(вез|ждат|достав)","срок доставки"],"related":["safety-stock","moq","supplier-risk"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"safety-stock","name":"Страховой запас","subtitle":"Покрытие неопределённости","description":"Дополнительный запас для покрытия непредвиденных колебаний спроса или сроков поставки.","topics":["inventory"],"patterns":["страхов.{0,12}запас","safety.stock","буферн.{0,10}запас"],"queries":["сколько.{0,20}(держать|запаса)","не хват.{0,20}(сырья|материал)"],"related":["leadtime","turnover","working-capital"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"turnover","name":"Оборачиваемость","subtitle":"Движение запасов","description":"Число оборотов среднего запаса за период: расход за период, делённый на средний запас в сопоставимых единицах.","topics":["inventory"],"patterns":["оборачиваем","неликвид","залежал"],"queries":["(лишн|много).{0,20}(запас|склад)","склад.{0,20}(забит|переполнен)"],"related":["working-capital","safety-stock","moq"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"working-capital","name":"Оборотный капитал","subtitle":"Деньги в операционном цикле","description":"Оборотные активы за вычетом краткосрочных обязательств. Высвобождение оборотного капитала не равно росту прибыли.","topics":["finance"],"patterns":["оборотн.{0,12}(капитал|средств)","оборотк","working.capital","финансирован.{0,15}запас"],"queries":["деньги.{0,20}(запас|склад|заморож)","(высвобод|заморож).{0,20}(деньг|средств)"],"related":["deferral","turnover","factoring"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"deferral","name":"Отсрочка платежа","subtitle":"Условия оплаты","description":"Согласованный срок между поставкой или другим договорным событием и оплатой.","topics":["finance","negotiation"],"patterns":["отсроч","услови.{0,10}оплат","стоимост.{0,10}денег"],"queries":["платить позже","(нечем|нет денег).{0,20}(плат|поставщик)","по условиям"],"related":["factoring","tco","working-capital"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"factoring","name":"Факторинг","subtitle":"Финансирование расчётов","description":"Финансирование под уступку денежных требований к покупателю.","topics":["finance","negotiation"],"patterns":["факторинг"],"queries":[],"related":["deferral","working-capital"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"price-change","name":"Изменение цены","subtitle":"Индексация, правила пересмотра","description":"Изменение договорной цены по согласованным основаниям, формуле и процедуре.","topics":["price","negotiation"],"patterns":["(повыш|измен|рост|пересмотр|увелич).{0,22}цен","индексаци"],"queries":["поставщик.{0,35}(дороже|поднял|повыш)","цена.{0,15}(вырос|растет|растёт)","по цене"],"related":["tco","market","monopoly"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"monopoly","name":"Монополист","subtitle":"Переговоры при ограниченном выборе","description":"Единственный продавец на определённом рынке. Единственный одобренный поставщик компании не обязательно является монополистом.","topics":["negotiation","supplier"],"patterns":["монопол","единственн.{0,20}производител"],"queries":["нет.{0,15}альтернатив","некем заменить","нельзя сменить поставщика"],"related":["market","moq","supplier-risk"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"negotiation","name":"Переговоры","subtitle":"С поставщиками, по цене, по условиям","description":"Процесс согласования условий между сторонами с различающимися интересами.","topics":["negotiation"],"patterns":["переговор","\\bbatna\\b"],"queries":["как договориться","как торговаться"],"related":["monopoly","price-change","deferral","poker"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"poker","name":"Покер, переговоры","subtitle":"Переговорный тренажёр","description":"Использование покера как модели решений при неполной информации: оценка вероятностей, интересов участников и допустимого риска. Это аналогия для обсуждения переговоров, а не метод закупки.","topics":["negotiation"],"patterns":["покер"],"queries":[],"related":["negotiation","monopoly"],"definition_kind":"reference","definition_source":{"title":"Публикация Анны","url":"https://t.me/notdandeliongirl/33"}},{"id":"market","name":"Анализ рынка","subtitle":"Альтернативы, рыночные сигналы","description":"Изучение предложения, спроса, цен, конкуренции и тенденций для принятия закупочных решений.","topics":["supplier","price"],"patterns":["анализ.{0,12}рынк","рыночн.{0,15}аналит","рын.{0,15}поставщик"],"queries":["где найти поставщика","как сравнить предложения"],"related":["monopoly","price-change","supplier-risk"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"supplier-risk","name":"Риск поставщика","subtitle":"Устойчивость поставок","description":"Возможность того, что события у поставщика нарушат поставку, качество или согласованные условия.","topics":["supplier"],"patterns":["риск.{0,18}поставщик","скоринг","устойчив.{0,20}постав","срыв.{0,15}постав"],"queries":["(поставщик|поставки).{0,20}(сорв|ненадеж|ненадёж)","проверить поставщика"],"related":["market","srm","leadtime"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"srm","name":"SRM","subtitle":"Работа с поставщиками","description":"Системное управление отношениями с поставщиками: цели, взаимодействие, оценка результатов и развитие сотрудничества.","topics":["supplier"],"patterns":["\\bsrm\\b","отношени.{0,18}поставщик","управлени.{0,15}поставщик"],"queries":["с поставщиками"],"related":["supplier-risk","market","negotiation"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"mdm","name":"НСИ","subtitle":"Нормативно-справочная информация","description":"Нормативно-справочная информация: согласованные справочники материалов, поставщиков, единиц измерения и других объектов учёта. Управление мастер-данными поддерживает их качество, единообразие и актуальность.","topics":["data"],"patterns":["(?\u003c![а-я])нси(?![а-я])","справочник","мастер.данн","master.data"],"queries":["дубли материалов","бардак.{0,15}данн","одинаковые материалы"],"related":["analytics","automation","tco"],"definition_kind":"reference","definition_source":{"title":"IBM","url":"https://www.ibm.com/think/topics/master-data-management"}},{"id":"analytics","name":"Закупочный анализ","subtitle":"Drill-down, roll-up, spend","description":"Анализ закупочных затрат, цен, объёмов и поставщиков для выявления отклонений и возможностей улучшения.","topics":["data"],"patterns":["drill.down","roll.up","спенд","\\bspend\\b","закупочн.{0,12}анализ","дашборд"],"queries":["прозрачность данных","детализация закупок"],"related":["mdm","category","automation"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"ai","name":"ИИ в закупках","subtitle":"Применение, границы, эксперименты","description":"Применение моделей искусственного интеллекта к задачам закупок: обработке текста, классификации, прогнозам и поиску закономерностей. Вывод модели требует проверки по исходным данным.","topics":["ai"],"patterns":["(?\u003c![а-я])ии(?![а-я])","\\bai\\b","нейросет","chatgpt","deepseek","claude","llm"],"queries":["искусственный интеллект"],"related":["automation","mdm","supplier-risk"],"definition_kind":"reference","definition_source":{"title":"IBM","url":"https://www.ibm.com/think/topics/artificial-intelligence"}},{"id":"automation","name":"Автоматизация","subtitle":"Процессы, инструменты, данные","description":"Передача повторяемых операций программам по заданным правилам. Автоматизация может работать без искусственного интеллекта.","topics":["ai","data"],"patterns":["автоматиза","power.query","rpa"],"queries":["ручная работа","автоматизировать"],"related":["ai","mdm","analytics"],"definition_kind":"reference","definition_source":{"title":"IBM","url":"https://www.ibm.com/topics/automation"}},{"id":"category","name":"Категорийное управление","subtitle":"Стратегия закупочной категории","description":"Управление группой сходных закупок на основе общей стратегии, рынка и потребностей бизнеса.","topics":["function"],"patterns":["категорийн","стратеги.{0,18}категор","кралич"],"queries":["стратегия закупок"],"related":["market","analytics","srm"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"governance","name":"Закупочные правила","subtitle":"Процессы, ответственность, контроль","description":"Правила закупочных решений: полномочия, ответственность, согласования и контроль исполнения.","topics":["function"],"patterns":["регламент","закупочн.{0,12}функци","закупочн.{0,12}процесс","полномоч","kpi"],"queries":["как организовать закупки","кто отвечает"],"related":["category","automation","analytics"],"definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"}},{"id":"reorder-point","name":"Точка заказа","subtitle":"Reorder point, ROP","description":"Уровень запаса, при достижении которого размещают новый заказ с учётом потребления за срок поставки.","definition_kind":"reference","definition_source":{"title":"CIPS — словарь терминов","url":"https://1prd-dxp.cips.org/intelligence-hub/glossary-of-terms"},"topics":["inventory"],"patterns":["точк.{0,8}заказ","\\breorder point\\b","\\brop\\b"],"queries":["когда заказывать"],"related":["leadtime","safety-stock","moq"]}],"posts":[{"id":499,"date":"2026-11-02","title":"Эффект рогов, оценка сотрудников и поставщиков","summary":"Но контроль должен помогать снижать риски и оценивать изменения в работе, а не превращаться в бесконечную долбежку.","summaryKind":"summary","text":"#теория \nПродолжу про разные эффекты в применении к закупкам и жизни\n\nПредставьте двух закупщиков: Оба работают с поставщиками, размещают заказы, согласовывают условия и контролируют поставки.\n\nОдин из них однажды допустил серьезную ошибку. Руководитель вполне обоснованно усилил контроль его работы- теперь внимательнее смотрит документы, перепроверяет условия, чаще задает уточняющие вопросы. Второй пока поводов для беспокойства не давал, поэтому его работу проверяют значительно реже.\n\nПроходит несколько месяцев. У первого закупщика обнаружено 7 ошибок, у второго всего одна.\n\nКто работает лучше?\nНа первый взгляд ответ очевиден, но мы ведь не знаем, сколько операций проверили у каждого, насколько сложными были их задачи и сколько ошибок осталось незамеченными.\n\nВ психологии существует эффект рогов (Horn Effect), когда одна отрицательная характеристика человека начинает влиять на оценку остальных его качеств. А если вслед за этим мы начинаем проверять его чаще, результаты такого контроля могут лишь уменьшить укреплять первоначальное впечатление.\n\nВ этом примере ошибка может сформировать устойчивое представление о ненадежности сотрудника. При частых проверках мы потенциально обнаруживаем больше ошибок и постепенно начинаем воспринимать результаты собственного неравномерного контроля как объективное подтверждение того, что один сотрудник работает хуже другого.\n\nА теперь перевернем эту же ситуацию в сторону поставщиков - как часто мы начинаем задрачивать проверять одних поставщиков проверками со стороны СБ, ОТК, производства, если случилась проблема, и вполне лояльно относиться к тем, кто такую проблему не создавал? На основании чего мы вообще считаем, что контроль можно ослабить и одинаково ли оцениваем результаты. \n\nРазумеется, после серьезной ошибки усилить контроль вполне разумно. Но контроль должен помогать снижать риски и оценивать изменения в работе, а не превращаться в бесконечную долбежку. \n\nПрежде чем делать выводы о профессионализме сотрудников / «качестве» поставщиков, стоит посмотреть не только на количество найденных ошибок, но и на то, кого, как часто, по каким критериям мы проверяем, насколько наша действующая система контроля вообще раьотает и не нужно ли ее подкорректировать. \n\nИ вопрос в зал: если однажды ваш знакомый или коллега серьезно ошибся, что должно измениться, чтобы вы снова начали доверять ему как раньше?","terms":[],"topics":["function"],"url":"https://t.me/notdandeliongirl/499"},{"id":493,"date":"2026-10-28","title":"ИИ для стресс-теста передачи дел перед отпуском","summary":"Получаем не просто список переданных дел, а предварительную карту рисков и варианты их снижения. Окончательное решение, разумеется, остается за руководителем.","summaryKind":"summary","text":"Перед отпуском закупщик обычно старается закрыть максимум вопросов заранее: разместить заказы, согласовать условия, решить проблемы с поставщиками. Коллегам остается поддерживать текущую работу и реагировать на то, что невозможно предусмотреть.\n\nКазалось бы, все продумано. Есть список дел, назначен заместитель, руководитель согласовал передачу обязанностей.\n\nНо насколько устойчива эта схема, если что-то пойдёт не по плану?\n\nНовая история -  использовать ИИ не для составления очередного чек-листа, а для стресс-теста передачи дел перед отпуском: \n\nДля этого достаточно собрать обязанности сотрудников, перечень того, что планируется завершить до отпуска, оставшиеся задачи и предложенную схему замещения. Причем интересно сравнить, как ее видят сам сотрудник и руководитель.\n\nА дальше попросить ИИ проверить, где система может дать сбой.\n\nНе перегружаем ли мы одного заместителя, хотя часть функций могут поддерживать другие коллеги? Не остаются ли задачи без ответственного? Что произойдет, если во время отпуска возникнет нестандартная ситуация, требующая решения, на которое у заместителя нет полномочий?\n\nИ главное, что лучше сделать до отпуска, а где достаточно предусмотреть дополнительную подстраховку?\n\nПолучаем не просто список переданных дел, а предварительную карту рисков и варианты их снижения. Окончательное решение, разумеется, остается за руководителем.\n\nНо здесь появляется еще одна возможность - люблю, когда из одного винтика рождается система - а что, если применить тот же принцип не к одному сотруднику, а к графику отпусков всей компании?\n\nОтсюда уже вырисовывается простой MVP для HR и руководителей: загружаем график отпусков, сведения о функциях и замещениях, а система подсвечивает возможные риски, периоды уязвимости и варианты подстраховки (например, пересечения критически важных согласующих). \n\nИ это просто еще один способ увидеть то, что легко упустить при обычном согласовании отпусков.\nПримерную задачу для ИИ дать в комменте?","terms":["ai","governance"],"topics":["ai","function"],"url":"https://t.me/notdandeliongirl/493"},{"id":492,"date":"2026-10-26","title":"ИИ, моделирование графика отправления машин","summary":"Зато можем заранее согласовать с поставщиком время выхода транспорта, учитывая вероятный интервал прибытия и уже запланированные поставки.","summaryKind":"summary","text":"В моей жизни были случаи, когда поставщики находились на расстоянии от 200 до 1200 км, но однажды практически одновременно на склад прибыло 90 машин, отгруженных в разное время. У меня шла кровь из ушей от воя на болотах. \n\nСклад регулярно просил так не отгружать. А я отвечала, что при таких расстояниях невозможно предугадать, когда именно приедет транспорт (тем более, когда производство и продажи требуют сырье, а на складе ограниченное место). \n\nТеперь решила вернуться к этой задаче с помощью ИИ, причем намеренно исключила очевидное решение: систему бронирования окон разгрузки. Почитим: допустим, что её нет, а склад работает круглосуточно.\n\nЗадача для ИИ, очевидная: распределить   количество прибывающих машин для равномерного распределения нагрузки на склад с учетом видов груза и времени на разгрузку и расстановку. \nНеочевидная: рассчитать рекомендуемое время отправления машин со складов поставщиков, чтобы снизить вероятность их одновременного прибытия и расходы на простой транспорта.\n\nДля эксперимента взяла 20 условных рейсов по 7 направлениям, задала 2 поста разгрузки, продолжительность приемки и случайные отклонения времени в пути. Затем сравнила 2 сценария: поставщики отправляют машины без координации и поставщики заранее согласовывают с нами рассчитанное время выхода транспорта.\n\nВ условной модели после 1000 симуляций среднее ожидание разгрузки сократилось с 4,92 до 0,08 часа на машину.\n\nРазумеется, это результат моделирования, а не фактическая экономия на предприятии. Но он показывает, что можно попробовать управлять не последствиями одновременного прибытия машин, а условиями, при которых эта ситуация возникает.\n\nМы не можем точно предсказать время доставки за сотни километров. Зато можем заранее согласовать с поставщиком время выхода транспорта, учитывая вероятный интервал прибытия и уже запланированные поставки.\n\nИ здесь из стресс-теста появляется идея простого MVP.\n\nПоставщик указывает количество машин и желаемую дату отправления. Система знает расстояние до склада, учитывает текущий график других поставщиков и предлагает рекомендуемое время выезда.\n\nЭто не еще одна система бронирования окон разгрузки. Мы согласовываем отправление транспорта, чтобы снизить риск очередей и оплачиваемых простоев.\n\nИ для первой версии не нужны сложная TMS. Достаточно простого интерфейса, данных о рейсах и расчетного алгоритма, который можно проверить на исторических поставках.","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/492"},{"id":490,"date":"2026-10-21","title":"Стресс-тест цепочки поставок с ИИ","summary":"Конечно, повторюсь, это стресс-сценарий, а не прогноз обязательного дефицита.","summaryKind":"summary","text":"Продолжаю эксперименты с неочевидным использованием ИИ в закупках. На этот раз делаем стресс-тест цепочки поставок. В качестве примера - обычный кукурузный крахмал для приготовления клея в гофропроизводстве (привет, коллеги!)\n\nЗадача: найти реалистичный сценарий, при котором предприятие может потерять 20% и более необходимого объёма. Без аварий, остановки заводов и транспортных проблем. И главное, определить, по каким признакам можно заранее увидеть приближение проблемы.\n\nПроверяем с ИИ сочетание двух факторов:\n1. в первом полугодии 2026 года производство кукурузного крахмала в России выросло всего на 0,7%, а экспорт примерно на 72%.\n2. приближается предновогодний сезон, когда может увеличиться спрос со стороны пищевой промышленности.\n\nА теперь представим, что эти факторы совпали: Производители продолжают выпускать крахмал, но значительная часть объёмов уже распределена между покупателями. Свободного предложения становится меньше, а быстро переключиться на другого поставщика не получается. Скоринг поставщиков такую ситуацию может вообще не показать- ведь с самими поставщиками всё в порядке.\n\nКакие тогда сигналы стоит отслеживать?\n\nРост экспорта относительно производства, сезонное изменение спроса на нужный вид крахмала и сокращение доступных объёмов у альтернативных поставщиков. \nКаждый настраивает под себя: \n1. сначала определение стресс-факторов или самостоятельно или с ИИ (ваши экспертные знания рынка, оценка ИИ о влиянии макро, рыночных, отраслевых факторов), \n2. потом моделирование самого стресс-сценария (например, или период или цель - потеря объемов 10%- или падение или повышение цены)\n3. далее определение триггеров для дальнейшей поддержки и анализа (что вы выявили как наиболее влияющие на вас и что стоит отслеживать)\n\nЕсли несколько сигналов совпадают, есть смысл заранее подтвердить резервные объёмы, пересмотреть графики поставок и рассчитать дополнительный запас на период возможного дефицита.\n\nКонечно, повторюсь, это стресс-сценарий, а не прогноз обязательного дефицита. Но мы ищем  сочетания событий, которые обычно рассматриваем по отдельности. Да и мы не сферические кони в вакууме на рынке.\n\nКстати, в нашем инструменте HireBuyer.ru уже собрана MVP по категорийной ДНК, которая строит стратегию в динамике. Как отдельный инструмент мы развивать ее не будем, как архитектуру внедрения в enterprise-решения - да.","terms":["price-change","supplier-risk","ai","category"],"topics":["ai","function","negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/490"},{"id":488,"date":"2026-10-19","title":"ИИ для проверки устойчивости закупочного регламента","summary":"Цель этого упражнения простая - насколько существующие правила защищают бизнес и насколько устойчивы правила в случае атаки.","summaryKind":"summary","text":"Как мы обычно используем ИИ при работе с регламентами? - Просим составить документ, проверить на ошибки и противоречия, предложить улучшения, сделать приложения  с образцами документов и так далее. \n\nА что если перевернуть задачу? Не проверяй регламент, а найди способ его обойти так, чтобы формально всё было соблюдено.\n\nНапример, нужно закупить оборудование у конкретного поставщика, хотя предусмотрен конкурентный отбор.\n\nКто я, чтобы отказывать самой себе?  Взяла закупочный регламент одной бывшей компании и поставила ИИ такую задачу.\n\nЧто нашлось:\n\nРегламент допускает закупку у единственного поставщика при наличии технических ограничений. Нужны обоснование, подтверждение технического специалиста и согласования.\n\nНо вот вопрос: а кто проверяет, что технические ограничения действительно существуют, а не являются инструментом исключения конкуренции? Все документы могут быть оформлены правильно, согласования получены, но обоснованность  останется под вопросом. \n\nЭто пока вопрос к процедуре, а не доказанное нарушение. Но именно такие места и интересно проверять.\n\nВ чем разница в подходе: при обычной проверке ИИ ищет ошибки в регламенте. А здесь пытается получить нужный результат, используя сами правила. \nПричем такие возможности использования ИИ полезно применять не только в регламентах: не «поправь договор, найди ошибки», а «как с этим договором при претензии поставщик может избежать ответственности». Это один из вероятных примеров (а если вы поставите кодекс и код в режим goal/auto mode, они усрутся, но найдут варианты почти всегда 😉)\n\nЦель этого упражнения простая - насколько существующие правила защищают бизнес и насколько устойчивы правила в случае атаки.","terms":["ai","governance"],"topics":["ai","function"],"url":"https://t.me/notdandeliongirl/488"},{"id":483,"date":"2026-10-14","title":"Минимальная партия заказа: экономика обеих сторон","summary":"Главное, понимать экономику обеих сторон и не воспринимать минимальную партию исключительно как проблему, которую нужно устранить.","summaryKind":"summary","text":"#теория Продолжение темы с запасами (клянусь, пока это последнее🤣)\n\nМинимальная партия заказа (MOQ- minimum order quantity) часто воспринимается закупщиками как ограничение. Поставщик требует купить больше, чем нам сейчас нужно, а значит, придётся увеличивать запасы, занимать склад и отвлекать оборотные средства.\nЧасто это действительно невыгодно. Но далеко не всегда.\n\nMOQ может быть обусловлен вполне конкретной экономикой поставщика: переналадкой оборудования, минимальной партией сырья, производственными потерями или логистикой.\n\nА при работе с новым покупателем минимальный объём заказа может быть ещё и способом переложить на него часть затрат и рисков запуска сотрудничества. Поставщик хочет получить гарантию, что произведённая партия будет выкуплена, а не останется у него на складе.\n\nНо давайте попробуем подумать, а что MOQ может дать покупателю?\n\nНапример, мы хотим начать работать с поставщиком, у которого сильная рыночная позиция, а возможно, он вообще единственный производитель нужного нам материала.\n\nМы можем долго пытаться изменить его условия. А можем оценить экономику предложения и, если она приемлема, согласиться на первоначальный MOQ, чтобы начать сотрудничество.\n\nЭто не означает, что мы автоматически получим лучшие условия в будущем. Но у нас появится история заказов, а у поставщика возможность оценить нашу надёжность и перспективы сотрудничества.\n\nДальше уже можно работать с фактическим потреблением, лидтаймом, оборачиваемостью, стоимостью запаса и обсуждать варианты: производство одной партией с поэтапными отгрузками, резервирование объёма, согласованный график поставок или изменение MOQ при стабильном прогнозе.\n\nПоэтому держите список вопросов для принятия решения:\n\n1. Чем обусловлен MOQ и что изменится при другом объёме?\n2. Как он соотносится с нашим потреблением и сроками поставки?\n3. Сколько будет стоить дополнительный запас и компенсирует ли его цена?\n4. Можно ли разделить производственную партию и график отгрузок?\n5. Что мы можем предложить поставщику, чтобы со временем пересмотреть условия?\n\nИногда MOQ действительно создаёт лишние затраты. Иногда позволяет получить более выгодную цену. А иногда становится вполне осознанным условием входа к стратегически важному поставщику.\n\nГлавное, понимать экономику обеих сторон и не воспринимать минимальную партию исключительно как проблему, которую нужно устранить.","terms":["moq","leadtime","turnover","working-capital","monopoly"],"topics":["finance","inventory","negotiation","supplier"],"url":"https://t.me/notdandeliongirl/483"},{"id":482,"date":"2026-10-12","title":"Новая спецификация: себестоимость, запасы","summary":"Получается, что мы вполне могли улучшить себестоимость продукции и одновременно увеличить оборотный капитал, находящийся в запасах.","summaryKind":"summary","text":"#теория \nПродолжаем про запасы (вы же не думали, что мы закончили?😉)\nИногда небольшое изменение спецификации даёт существенный экономический эффект- все об этом знают и уже давно успешно этим оперируют: \nУменьшили плотность пленки- снизили расход сырья на единицу продукции. Изменили размер коробки на один миллиметр-сэкономили на материале. При больших объёмах даже такие изменения могут давать весьма заметные суммы.\n\nЗакупки показывают экономию, производство подтверждает снижение себестоимости. И всё действительно зашибись. Но что происходит с запасами после внедрения новой спецификации?\n\nДопустим, мы заменили один вид фильтра другим. Старую позицию перестали активно использовать, но остатки остались на складе. Новую уже закупаем и формируем под неё страховой запас.\n\nИли у нас появились 3 практически взаимозаменяемых материала от разных поставщиков. Для производства они могут выполнять одну функцию, но в учётной системе это три отдельных кода. У каждого своя история потребления, свой прогноз и, возможно, свой страховой запас. При этом реальная потребность производства не обязательно выросла.\n\nПолучается, что мы вполне могли улучшить себестоимость продукции и одновременно увеличить оборотный капитал, находящийся в запасах.\n\nПоэтому при вводе новой спецификации я бы задавала ещё несколько вопросов:\n\n1. Что произойдёт с остатками предыдущей позиции? Есть ли план их использования?\n2. Когда мы прекратим закупать старую спецификацию и нужно ли вообще выводить её из оборота?\n3. Какие материалы действительно взаимозаменяемы и при каких технологических условиях?\n4. Не создаём ли мы отдельные прогнозы и страховые запасы под позиции, которые фактически закрывают одну потребность?\n5. Сопоставляем ли мы полученную экономию с изменением запасов хотя бы по итогам нескольких месяцев?\n\nКонечно, разные спецификации и коды не всегда можно объединять. Иногда они нужны для контроля качества, прослеживаемости или выполнения требований клиентов. Но управлять их взаимозаменяемостью и жизненным циклом всё равно необходимо.\n\nА то с одной стороны оптимизировали закупочные цены, а с другой создали на складе зоопарк СКЮ. При этом вроде и можно объяснить, как появился новый обитатель, но вот почему вместе с ним еще и все его родственники уже нет))","terms":["safety-stock","working-capital"],"topics":["finance","inventory"],"url":"https://t.me/notdandeliongirl/482"},{"id":473,"date":"2026-10-07","title":"Запас для производства, финансирование запаса","summary":"Мое мнение -  разделяем две задачи: сколько запаса нужно бизнесу и сколько собственного капитала нужно закупкам, чтобы этот запас обеспечить.","summaryKind":"summary","text":"#теория #юзфултип \n60 дней запаса не обязательно должны быть куплены на ваши деньги и на этом мы остановились в прошлом посте. \n\nЗдесь тема запасов становится особенно интересной, когда к вам приходят финансы или генеральный с «Сушим склады» или «У нас бабок нет, а вы тут все закупаете».\n\nДопустим, после всех расчетов выяснилось, что запас по категории действительно должен составлять 30% оборота. Не исторически сложившиеся залежи, а нормальный рабочий запас, который нужен с учетом потребления, lead time и рисков поставки. Сократить его можно, но тогда вместе с обороткой мы высвободим еще и часть защиты производства.\n\nМожно попробовать не уменьшать сами 30%, а разделить их финансирование. Например, 10% купить и держать самим, 10% перевести в консигнацию на своем складе, еще 10% оставить резервом у поставщика. В другом случае часть этого объема может постоянно находиться в пути или на ответственном хранении. Конкретная конструкция зависит от категории, но смысл один: физическое покрытие остается 30%, а собственными деньгами мы финансируем уже не весь объем.\n\nИиии - появляется вполне предметный разговор с финансами. Не «я не могу снизить запасы, потому что производство встанет» и не «давайте отрежем Сусанину ноги 20% и посмотрим, что случится», а несколько вариантов одной и той же обеспеченности производства с разной нагрузкой на оборотный капитал.\nМое мнение -  разделяем две задачи: сколько запаса нужно бизнесу и сколько собственного капитала нужно закупкам, чтобы этот запас обеспечить. Второй показатель вполне можно снижать, не трогая первый.\n\nИ чтобы вам было удобнее - ловите простую модельку. Напоминаю, каждый настраивает ее под себя в части ключа, способов разделения запасов и прочей, прости господи, дичи. Но при любом раскладе у вас будет  файл, в котором можно играться с цифрами. \n\nИ помните, друзья, бесплатный сыр, как и красивое в мыслях решение по делению затрат иногда может быть только в мышеловке. Поэтому не забывайте спрашивать поставщика, а реально ли бесплатной будет ваша придумка😉","terms":["leadtime","working-capital"],"topics":["finance","inventory"],"url":"https://t.me/notdandeliongirl/473"},{"id":471,"date":"2026-10-05","title":"Когда говорят об управлении запасами, мы сразу же строим модель: среднее потребление, колебания спроса, lead time, уровень сервиса.","summary":"Когда говорят об управлении запасами, мы сразу же строим модель: среднее потребление, колебания спроса, lead time, уровень сервиса. Вообще базара нет.","summaryKind":"excerpt","text":"#теория \nКогда говорят об управлении запасами, мы сразу же строим модель: среднее потребление, колебания спроса, lead time, уровень сервиса.\n\nВообще базара нет. Все правильно . Но после расчетов, мне кажется,  полезным задать еще один вопрос: а вообще где запас должен находиться?\n\nСамый очевидный вариант- купить самим и положить на склад. Максимальный контроль, зато вместе с ним получаем замороженные деньги, складские расходы и риск неликвидов. А если спрос плавает, рассчитанный сегодня страховой запас через несколько месяцев может оказаться уже совсем не таким страховым. Думаю, все понимают, о чем я. \n\nНо это далеко не единственная конструкция.\n\n1. Можно договориться о резерве на складе поставщика. Например, поставщик постоянно держит под нас определенное количество дней потребления и восстанавливает запас после выборки. Тогда особенно важны срок восстановления, обязательства сторон, минимальная выборка и то, что происходит, если наш спрос резко вырос или упал.\n\n2. Можно сделать консигнационный запас уже на нашей площадке. Товар физически рядом с производством, но до момента выборки остается товаром поставщика. Здесь придется нормально договориться об учете, инвентаризации, сроках выборки и остатках, зато доступность товара и момент появления денег в нашей оборотке уже не совпадают.\n\n3. Есть более интересный вариант с ответственным хранением. Если у нас есть подходящая складская инфраструктура, почему обязательно хранить только собственный запас? Мы можем стать для поставщика локальным хабом: часть товара потребляем сами, а часть храним и отгружаем другим его клиентам. Тогда сверххранение и обработка могут оплачиваться поставщиком, наши складские затраты частично отбиваются, а у поставщика появляется запас ближе к клиентам. Это уже не уступка одной стороны другой, а отдельный совместный проект.\n\n4. И наконец, товар может находиться в пути. При длинном lead time это тоже часть системы покрытия потребности. Особенно если поставки идут регулярно и следующие партии уже движутся к нам (при условии перехода права собственности у нас на складе и отсрочке платежа после него). \n\nПолучается, что вопрос «сколько дней страхового запаса нам нужно?«- начало пути.\n\nСледующий: где эти дни должны физически находиться запасы  и насколько быстро каждый из этих запасов становится доступен производству?\n\nА дальше еще лучше - \n60 дней физического покрытия совершенно не обязательно означают 60 дней товара, который уже куплен на наши деньги.","terms":["leadtime","safety-stock","turnover","working-capital","deferral"],"topics":["finance","inventory","negotiation"],"url":"https://t.me/notdandeliongirl/471"},{"id":466,"date":"2026-09-30","title":"Вдогонку про смену менеджера.","summary":"Вдогонку про смену менеджера. А если поменять просят вашего?","summaryKind":"excerpt","text":"#теория \nВдогонку про смену менеджера. А если поменять просят вашего?\n\nВ прошлом посте я написала, что иногда имеет смысл попросить поставщика поменять менеджера. Но ситуация вполне может быть зеркальной: поставщик приходит к вам и говорит, что больше не хочет работать с конкретным закупщиком. Shit happens, жаловались и на меня. \n\nЗдесь для меня с самого начала важно разделить две вещи. Поставщик имеет полное право сказать, что во взаимодействии есть проблема. Но решать, кто у меня работает с поставщиками и как я управляю своей командой, будет все-таки не поставщик.\n\nПоэтому требование «поменяйте нам менеджера, иначе…» я бы точно не воспринимала как готовое управленческое решение. Но и автоматически вставать на сторону своего сотрудника только потому, что он свой, было бы довольно наивно. \n\n1. Сначала я хочу понять, что произошло.\n\nЧто именно поставщика не устраивает? Есть ли конкретные ситуации или только «с ним невозможно работать»? Нарушает ли закупщик договоренности и сроки? Дает ли обратную связь? Не меняет ли требования в процессе? Не требует ли от поставщика решить за два дня то, что сам согласовывал две недели? Корректно ли ведет переговоры? Не блокирует ли нормальную рабочую коммуникацию внутри компаний?\n\n2. Отдельно посмотрю, единичный это конфликт или история повторяется с другими поставщиками. Потому что одна жалоба может оказаться конфликтом интересов или попыткой продавить неудобного закупщика. Пять похожих жалоб от разных контрагентов уже дают совсем другой материал для диагностики.\n\n3. И только после этого можно решать, что делать. Возможно, закупщик действительно создает проблемы и с ним нужно работать. Возможно, конфликт возник из-за процесса или распределения полномочий. А возможно, менеджер просто хорошо делает свою работу, перестал пропускать необоснованные повышения цены или начал задавать поставщику вопросы, которые тому очень не нравятся.\n\nВыслушать поставщика нужно. Разобраться, что происходит, тоже нужно. Но если просьба превращается в требование с условиями и последствиями, для меня это уже шантаж.\n\nА на требования шантажиста нельзя соглашаться хотя бы по одной простой причине: если это сработало один раз, он попробует еще. Только в следующий раз требования, скорее всего, будут больше.","terms":["price-change","negotiation","governance"],"topics":["function","negotiation","price"],"url":"https://t.me/notdandeliongirl/466"},{"id":465,"date":"2026-09-28","title":"Неочевидный лайфхак: иногда для улучшения условий нужно поменять не поставщика, а менеджера.","summary":"Неочевидный лайфхак: иногда для улучшения условий нужно поменять не поставщика, а менеджера. Обычно, когда отношения с поставщиком перестают устраивать, мы начинаем обсуждать цену, сервис, сроки, искать альтернативы или готовить очередные переговоры.","summaryKind":"excerpt","text":"#теория \nНеочевидный лайфхак: иногда для улучшения условий нужно поменять не поставщика, а менеджера.\n\nОбычно, когда отношения с поставщиком перестают устраивать, мы начинаем обсуждать цену, сервис, сроки, искать альтернативы или готовить очередные переговоры.\n\nНо иногда проблема находится немного в другом месте: между двумя компаниями стоит конкретный менеджер, через которого проходит вообще всё взаимодействие.\n\nЯ несколько раз сталкивалась с ситуациями, когда проще было попросить поставщика заменить менеджера. Но для меня это не было вопросом  «не сошлись характерами». Причины должны быть вполне конкретными.\n\n1. Например, менеджер процессуально медленный. Любой вопрос - ожидаешь несколько дней, каждое решение приходится вытаскивать, договоренности постоянно зависают.\n\n2. В принципе менеджеру неинтересно развивать клиента. Он обслуживает текущий поток, но сам ничего не предлагает, не ищет вариантов, не возвращается с решениями.\n\n3. Менеджер полностью замыкает все на себе и при этом не дает выйти на следующий уровень. Любая попытка обсудить вопрос с коммерческим директором или руководителем заканчивается «я сам передам», после чего ничего особенно не происходит.\n\n4. Еще хуже, когда возникают реальные операционные проблемы: ошибки, срывы отгрузок, претензии. Вместо того чтобы решить причину или нормально эскалировать вопрос внутри своей компании, менеджер пытается закрыть сам факт эскалации. Главное, чтобы проблема не ушла выше.\n\n5. Ну и коммерческая часть. Если человек не готов обсуждать цену и условия, не понимает, из чего складывается его собственная цена, не может объяснить изменение и на любое предложение отвечает «у нас такие условия», переговоры довольно быстро заканчиваются.\n\nПри этом сам поставщик может меня полностью устраивать: продукт, качество, производство, потенциал для дальнейшей работы. Поэтому смена менеджера иногда дает неожиданный эффект. У другого человека оказываются другие полномочия, скорость реакции, связи внутри компании, и условия, которые месяцами не двигались, внезапно начинают обсуждаться.\n\nКстати, не забывайте, что ситуация вполне может быть зеркальной)) И поставщику иногда очень хочется поменять менеджера со стороны закупок. Но об этом в следующий раз.","terms":["negotiation","srm","governance"],"topics":["function","negotiation","supplier"],"url":"https://t.me/notdandeliongirl/465"},{"id":461,"date":"2026-09-25","title":"Как заранее прописывать правила повышения цены","summary":"Анна показывает, что проверку повышения цены можно частично заложить в договор заранее: срок уведомления, основания пересмотра, пороги и расчет поставщика.","summaryKind":"summary","text":"#теория \nЯ уже много писала о том, как проверять повышение цены: смотреть сырье, структуру себестоимости, рынок, спрос, мощности и остальные факторы.\n\nНо часть этой работы вообще можно сделать заранее, еще на этапе договора.\n\nПоставщик пишет 20 сентября: «С 1 октября повышаем цены на 12%». И следующие десять дней закупщик героически выясняет, откуда взялись 12%, спорит, собирает аналитику, а производство и продажи параллельно пытаются понять, что теперь делать со своими планами и ценами.\n\nНесколько вещей можно было определить заранее.\n\n1. За сколько поставщик должен предупредить о повышении.\nНе «заблаговременно», а 30, 60 или 90 дней. Причем срок лучше брать не с потолка, а сначала поговорить с производством, финансами и продажами.\n\nЕсли цены клиентам пересматриваются раз в квартал, а поставщик может изменить свою цену за десять дней, компания на какое-то время остается с новой себестоимостью и старой продажной ценой. Поэтому 90 дней здесь имеют вполне понятное экономическое объяснение.\n\n2. При каких условиях цена вообще может быть пересмотрена.\nФразы «изменение рыночной ситуации» я бы по возможности не оставляла.\n\nМожно заранее договориться, какие факторы являются основанием для пересмотра: изменение ключевого сырья, валюты, энергии, логистики или другого действительно существенного элемента себестоимости. Для некоторых категорий можно установить и порог: например, пересмотр начинается только при изменении согласованного фактора больше чем на 3%.\n\n3. Что поставщик должен показать.\nЕсли основание для повышения возникло, поставщик предоставляет расчет: какой фактор изменился, насколько, какую долю он занимает в цене и какой эффект это должно дать.\n\nЕсли сырье занимает 50% себестоимости и выросло на 6%, это еще не объясняет автоматическое повышение конечной цены на те же 6%.\n\n4. С какого момента действует новая цена и что происходит с уже размещенными заказами.\nЭто тоже лучше определить до первого конфликта: распространяется ли изменение на открытые заказы, сколько времени занимает рассмотрение обоснования и когда согласованная цена начинает действовать.\n\nПри этом универсальных «90 дней» здесь нет.\n\nЕсли вы покупаете продукт с очень волатильным сырьем, сильной сезонностью или дефицитом мощностей, поставщик может просто не согласиться гарантировать цену на квартал вперед. И иногда требовать этого бессмысленно.\n\nТогда можно договориться иначе. Например: в обычной ситуации уведомление за 90 дней, но если ключевой фактор цены изменился больше согласованного порога, поставщик получает право инициировать пересмотр за 30 дней, предоставив расчет.\n\nТо есть договориться можно не только о сроке, но и о триггере, доказательствах и процедуре изменения цены.\n\nЭто гораздо полезнее, чем потом каждый раз начинать переговоры сначала.","terms":["price-change","negotiation"],"topics":["negotiation","price"],"url":"https://t.me/notdandeliongirl/461"},{"id":446,"date":"2026-09-15","title":"Что делать с кассовым разрывом через закупки","summary":"Анна разбирает, что отсрочка платежа не является бесплатным кредитом от поставщика. При кассовом разрыве нужно считать варианты: отсрочка, отсрочка с повышением цены, факторинг и обратный факторинг.","summaryKind":"summary","text":"#теория \nКогда у компании начинает расти кассовый разрыв, первыми приходят куда? Дада, к закупкам. И обычно многие начинают с двух простых способов:\n\n1. просто не платить вовремя и потом с сладострастием мазохиста замиранием сердца ждать, что придет раньше: следующая машина с сырьем или досудебка.\n\n2. долдонить до усрачки: «Дайте нам отсрочку. Ну, дайте. Ну, еще 30 дней. Ну, очень надо».\n\nНо отсрочка не обязательно означает, что поставщик должен бесплатно кредитовать нас на весь срок.\n\nПоэтому вот несколько очевидных и не очень вариантов.\n\n1. Обычная отсрочка.\nСамый простой вариант: поставщик вместо 30 дней дает 60 или 90. Взамен он может попросить объем, более длинный контракт, прогноз потребности или что-нибудь еще ценное для него. Деньги не всегда единственная валюта переговоров.\n\n2. Отсрочка с увеличением цены.\nПоставщик готов ждать дольше, но фактически кредитует нас за деньги. Здесь важно посчитать, сколько именно они стоят. Если дополнительные 30 дней увеличивают цену на 2%, это примерно 24% годовых. Если собственное финансирование компании стоит дешевле, прекрасная отсрочка внезапно становится довольно дорогим кредитом (подниметесь по каналу выше, как раз недавно был пост о стоимости кредита)\n\n3. Факторинг.\nДопустим, по договору мы платим поставщику через 80 дней, а ему деньги нужны сейчас. Он передает право требования к нам факторинговой компании, которая выплачивает ему сумму раньше, а через 80 дней получает деньги с нас. Поставщик платит за такое финансирование комиссию, зато ему не приходится кредитовать покупателя из собственной оборотки.\n\n4. Обратный факторинг.\nЗдесь программу обычно организует покупатель вместе с банком или фактором. Поставщик отгрузил товар, мы подтвердили поставку, после чего он может получить деньги раньше, а мы рассчитываемся с финансовой организацией позже. Для небольшого поставщика такой вариант может быть интересен, потому что финансирование во многом опирается на надежность крупного покупателя.\n\n5. Деньги сейчас в обмен на условия потом.\nПокупатель может профинансировать поставщику закупку сырья, оборудование или расширение мощности. А взамен обсуждать цену, гарантированную мощность и более длинную отсрочку по будущим поставкам. Это уже инвестиционная история, поэтому считать нужно всю конструкцию, а не только дни отсрочки.\n\n6. Консигнация или запас за счет поставщика.\nМатериал уже лежит у нас и доступен производству, но остается собственностью поставщика до момента использования или другого согласованного события. Для покупателя это возможность иметь физический запас, не вынимая сразу деньги из оборота.\n\n7. Комбинация нескольких вариантов.\nВообще никто не сказал, что весь период должен финансировать кто-то один. Например, 80 дней закрываются факторинговой схемой поставщика, а еще 20 дней берет на себя покупатель. Или стоимость дополнительных дней стороны делят между собой. Для разных частей объема тоже можно установить разные условия.\n\nНо! Перед такими переговорами я бы сходила к финансам за цифрами: сколько сейчас стоят деньги компании и сколько оборотного капитала нам нужно высвободить.","terms":["working-capital","deferral","factoring","price-change","negotiation"],"topics":["finance","negotiation","price"],"url":"https://t.me/notdandeliongirl/446"},{"id":445,"date":"2026-09-13","title":"Drill-down и roll-up в закупочном анализе","summary":"Анна показывает, что закупочный анализ нельзя ограничивать проваливанием в SKU, поставщика и цену. Иногда причина находится выше: в продукте, заказе, клиенте или процессе, который создает потребность.","summaryKind":"summary","text":"#теория \nЗакупщики вообще любят делать drill-down анализ (от общего к частному). Видим проблему и начинаем проваливаться в данные: категория, SKU, поставщик, цена, объем, период. Не нашли ответ, значит, проваливаемся еще глубже.\n\nНо есть и обратное направление анализа- roll-up. Мы перестаем разбирать объект на части и поднимаемся от него к продукту, заказу, клиенту или процессу, который этот объект вообще породил.\n\nХороший пример - ABC/XYZ-анализ.\n\nКоротко: ABC показывает, какие позиции формируют основную часть затрат, XYZ показывает стабильность их потребления. В результате мы можем увидеть, например, довольно много дорогих AZ-позиций: денег в них много, потребление скачет.\nПост с инструментом  тут и на сайте Hirebuyer.ru\n\nИ да начнется drill-down: \nКакие именно позиции? Как часто покупаем? У каких поставщиков? Какие сроки поставки? Что происходит с запасами? Можно еще посчитать коэффициенты вариации по разным периодам, построить графики и получить прекрасный аналитический отчет.\n\nМожно до смерти задрачивать drill-down’ить данные и так и не найти причину. Потому что она находится не глубже, а выше. Например, если компания производит продукцию под клиентский заказ. \n\nЧто делать? \nДелать roll-up: материал → готовая продукция → заказ → клиент.\n\nОбнаруживаем, например, что большинство наших AZ-позиций связано с продукцией для нескольких крупных клиентов с нерегулярными заказами. Закупочная номенклатура ведет себя хаотично ровно потому, что хаотично ведет себя спрос, который ее создает.\n\nВот теперь можно решать, что с этим делать. Где действительно нужен запас, где можно изменить условия поставки, а где вопрос нужно возвращать в продажи и разбираться с прогнозом и клиентскими заказами.\n\nABC/XYZ при этом все посчитал правильно. Ошиблись мы в другом: решили, что если проблема видна в данных закупок, то и причина обязательно находится там же.\n\nПоэтому, когда очередной уровень детализации приносит вам еще больше данных, но не делает причину понятнее, я бы перестала копать, а лучше бы сделала roll-up, чтобы увидеть, что создало то, что вы так старательно анализируете.","terms":["leadtime","analytics"],"topics":["data","inventory"],"url":"https://t.me/notdandeliongirl/445"},{"id":444,"date":"2026-09-11","title":"Продолжим про эффекты в применении к закупкам Мы довольно много говорим о том, что хороший закупщик должен знать рынок, понимать свою категорию и накапливать опыт.","summary":"Продолжим про эффекты в применении к закупкам Мы довольно много говорим о том, что хороший закупщик должен знать рынок, понимать свою категорию и накапливать опыт. Это позволяет не начинать каждый раз с чистого листа и быстрее строить рабочие гипотезы: Осенью поставщики всегда повышали цены.","summaryKind":"excerpt","text":"#теория \nПродолжим про эффекты в применении к закупкам\n\nМы довольно много говорим о том, что хороший закупщик должен знать рынок, понимать свою категорию и накапливать опыт. Это позволяет не начинать каждый раз с чистого листа и быстрее строить рабочие гипотезы:\n\nОсенью поставщики всегда повышали цены. Китай всегда был дешевле. На падающем рынке цена не должна расти. Если мы консолидируем объем, поставщик даст нам дополнительные 7%.\n\nПоследнее, кстати, особенно удобно представить как вполне реальный проект. Мы посчитали эффект от консолидации, защитили перед руководством 7% экономии, записали их в KPI и пошли к поставщику. А он скидку не дает. Какой гондон Нехороший человек.\n\nПервой реакцией, скорее всего, будет не «возможно, наша гипотеза была неверной», а поиск подтверждений собственной правоты: мы показываем поставщику рост объема, считаем его загрузку, приносим бенчмарки, проводим еще три раунда переговоров. Потому что мы много раз получали скидку за объем и знаем, что это работает.\n\nЭто confirmation bias, ошибка подтверждения. Чем больше у нас опыта, тем больше готовых закономерностей хранится в голове.\n\nДопустим, в нашем примере мощности поставщика уже загружены. Дополнительный объем ему не особенно интересен. Или мы и так занимаем такую долю его продаж, что дальнейшая концентрация для него скорее риск. Возможно, 7% действительно можно получить, но уже у другого поставщика.\n\nИ здесь рядом с первой ловушкой появляется вторая, sunk cost, эффект невозвратных затрат.\n\nМы уже защитили эти 7%. Потратили два месяца. Провели переговоры. Пообещали экономию. Чем дальше зашли, тем неприятнее признать, что первоначальная гипотеза могла быть неверной. Поэтому возникает желание провести четвертый раунд, потом пятый и все-таки дожать именно этого поставщика.\n\nХотя в какой-то момент правильным решением может быть сменить поставщика, пересмотреть способ получения эффекта или вообще признать, что при текущем рынке этих 7% нет.\n\nПоэтому я бы периодически задавала себе два вопроса:\n\n1. Что должно произойти или выясниться, чтобы я признала свою первоначальную гипотезу неверной?\n\n2. Если забыть все время, деньги и собственную репутацию, которые я уже вложила в это решение, что выгоднее сделать сегодня: продолжать или остановиться и выбрать другой путь?\n\nОпыт помогает быстрее находить рабочую гипотезу, но не давайте ему возможность потом заставлять вас дорого доказывать, что она должна быть правильной.","terms":["price-change","negotiation","governance"],"topics":["function","negotiation","price"],"url":"https://t.me/notdandeliongirl/444"},{"id":438,"date":"2026-09-07","title":"Под какой процент поставщик кредитует компанию","summary":"Анна предлагает считать стоимость отсрочки через изменение цены при разных условиях оплаты. Так закупки и финансы начинают говорить на одном языке о цене денег.","summaryKind":"summary","text":"#теория \n\nА вы знаете, под какой процент вас кредитует поставщик?\n\nЕсть довольно простой прием для переговоров, которым почему-то не все пользуются. Спросите поставщика, как изменится цена, если изменить условия оплаты. Например, сейчас у вас 30 дней отсрочки. Спросите цену при 60 днях. А потом при оплате через 15 дней.\n\nСкорее всего, сначала услышите, что цена от этого не зависит. Я бы в таком случае предложила поставщику все-таки сходить к своим финансистам и вернуться с ответом. Или можно зайти с другой стороны: «Хорошо, я готов платить через 15 дней. Какую скидку вы мне дадите?»\n\nВ результате у вас может получиться, например:\n15 дней → 98 ₽\n30 дней → 100 ₽\n60 дней → 102 ₽\n\nТо есть  дополнительные 30 дней отсрочки поставщик продает вам за 2%.\n\nЗачем это считать? Чтобы понять, под какой процент поставщик фактически вас кредитует.\n\nГрубо это можно посчитать прямо в голове. 30 дней считаем месяцем:\n2% × 12 = примерно 24% годовых. \nЧуть точнее считаем через дни:\n2% × 365 / 30 = 24,3% годовых.\n\nДля переговоров этой точности вполне достаточно. А дальше я бы уже пошла к финансистам и спросила: сколько стоят деньги нашей компании?\n\nЕсли мы можем финансировать оборотный капитал условно под 15%, зачем покупать те же деньги у поставщика под 24,3%? Возможно, выгоднее согласиться на меньшую отсрочку, получить более низкую цену и финансироваться самим.\n\nЕсли наши деньги стоят 28%, ситуация обратная. Отсрочка поставщика под 24,3% оказывается дешевле, и тогда уже есть смысл оставить деньги в своем cash flow и заплатить ему чуть больше.\n\nВ итоге вопрос «30 или 60 дней отсрочки?» становится уже не только вопросом ТСО, но и позволяет вам говорить на одном языке с финансами, чтобы можно было выбирать, кому в этой сделке выгоднее быть банком.","terms":["tco","working-capital","deferral","price-change","negotiation"],"topics":["finance","negotiation","price"],"url":"https://t.me/notdandeliongirl/438"},{"id":437,"date":"2026-09-06","title":"Давеча мне пришла в голову мысль: если ИИ столько времени наблюдает, как я думаю и принимаю решения, почему бы не устроить мне performance review?","summary":"Давеча мне пришла в голову мысль: если ИИ столько времени наблюдает, как я думаю и принимаю решения, почему бы не устроить мне performance review? ИИ давно работает у меня спарринг-партнером.","summaryKind":"excerpt","text":"Давеча мне пришла в голову мысль: если ИИ столько времени наблюдает, как я думаю и принимаю решения, почему бы не устроить мне performance review?\n\nИИ давно работает у меня спарринг-партнером. Я с ним разбираю рабочие ситуации, строю модели, придумываю продукты, спорю, проверяю гипотезы. Иногда выясняется, что неправ он. Иногда, что я, иногда, что оба. В общем, материала накопилось достаточно, и я попросила посмотреть не на отдельные задачи, а на повторяющиеся паттерны моего мышления. Получилось местами неожиданно полезно.\n\nНапример, оказалось, что я довольно редко принимаю исходную постановку задачи как данность. Если бизнес говорит «надо сократить затраты на 10%», мне сначала интересно, откуда взялись именно 10% и почему сокращать решили именно здесь. Если нужно увеличить количество поставщиков, потому что «так надежнее», сначала хочется понять, какой конкретно риск мы этим собираемся снизить.\n\nТо есть прежде чем хорошо решить задачу, я имею плохую привычку проверить, не решаем ли мы совершенно случайно какую-нибудь фигню (правда, ИИ назвал это системным мышлением и независимостью суждения. Кто я такая, чтобы спорить с ним). \n\nСо слабостями получилось еще прикольнее: \nВыяснилось, например, что я не очень люблю неопределенность, происхождение которой не понимаю. Поэтому мой естественный способ с ней бороться - добыть еще информацию, проверить еще одну гипотезу, найти границу применимости модели. Но этот недуг мы в подвиг обратим (с), потому что обратная сторона ровно та же: если модель десять раз работала, а на одиннадцатый дала сбой, мне интереснее не выбросить исключение или модель, а понять, какое предположение перестало работать.\n\nПравда, руководителю иногда нужно вовремя прекратить это занятие и тут уже моя зона роста: понять, когда неопределенность еще нужно уменьшать, а когда пора зафиксировать остаточный риск и принять решение.\n\nВ общем, performance review мне понравился, но есть нюанс: такой результат можно получить на большом контексте задач и обсуждений, а не разовых «сравни договоры» или «какая машина лучше».  ИИ должен достаточно долго видеть не только \nчто вы у него спрашиваете, но и как вы думаете, то есть история принятия решений. И уже ее можно анализировать.\n\nЯ бы только еще обязательно просила приводить примеры под каждый вывод и искать контрпримеры. А то попросить ИИ рассказать, какой ты замечательный, можно значительно проще.\n\nПромпт, если хотите попробовать, в комментарии к посту","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/437"},{"id":430,"date":"2026-09-01","title":"По мотивам поста А что делать с тем, что в TCO нельзя нормально посчитать в деньгах?","summary":"По мотивам поста А что делать с тем, что в TCO нельзя нормально посчитать в деньгах? С ценой все относительно просто: поставщик А предлагает 100 рублей, поставщик Б 105.","summaryKind":"excerpt","text":"По мотивам поста\n\n#теория \nА что делать с тем, что в TCO нельзя нормально посчитать в деньгах?\n\nС ценой все относительно просто: поставщик А предлагает 100 рублей, поставщик Б 105. Добавили логистику, пошлины, стоимость финансирования из-за разной отсрочки, необходимый запас и получили уже не цену предложения, а более честную стоимость каждого варианта. Собственно, для этого TCO и нужен.\n\nНо лучшее, как обычно, впереди(с)\n\nДопустим, поставщик А по TCO все еще дешевле. Только производство у него находится в жопе мира, работает один станок, сроки поставки нестабильны, а за последний год он несколько раз срывал обязательства.\n\nВот это сколько рублей стоит?\n\nЕсли у нас достаточно данных, риск можно попробовать монетизировать. Например, оценить вероятность срыва, длительность возможного простоя, стоимость остановки производства, срочной доставки, переключения на альтернативного поставщика и получить ожидаемую стоимость риска. Но довольно часто нормальных данных для этого просто нет.\n\nИ здесь мне не очень нравится подход «раз нельзя посчитать в рублях, значит, оставляем за пределами TCO и выбираем самого дешевого». Потому что дешевый поставщик с вероятностью остановки производства явно не равен надежному поставщику с тем же TCO. Но и придумывать стоимость риска из воздуха, чтобы Excel наконец сошелся, тоже так себе идея.\n\nПоэтому я бы разделяла два слоя оценки:\n\nПервый слой - TCO: все, что мы можем достаточно обоснованно привести к деньгам. Цена, логистика, пошлины, финансирование, запас, эксплуатация и другие релевантные затраты.\n\nВторой слой - скоринг: то, что важно для решения, но пока плохо переводится в деньги. Надежность производства, география и сложность цепочки поставок, наличие альтернативных площадок, стабильность качества, история исполнения и другие риски. Здесь уже можно установить критерии, веса и шкалу оценки.\n\nНапример, TCO поставщика А = 100, поставщика Б = 105. Но после оценки рисков А получает 55 баллов из 100, а Б 90.\n\nА дальше вопрос уже не «кто дешевле?», а готовы ли мы купить эти дополнительные риски за экономию в 5 рублей?\n\nПричем веса здесь тоже нельзя раздавать по принципу «цена 50%, качество 20%, остальное как-нибудь поделим». Если критерий способен остановить производство, возможно, ему вообще нужен не вес, а порог: ниже определенного уровня поставщик просто не проходит дальше.\n\nПоэтому я бы не пыталась любой ценой запихнуть весь мир в TCO.\n\nЧто можно обоснованно посчитать в деньгах, считаем. Что нельзя, но оно способно изменить решение, оцениваем отдельно. А критические риски иногда вообще лучше не усреднять никакими весами.","terms":["tco","leadtime","working-capital","deferral","price-change","supplier-risk"],"topics":["finance","inventory","negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/430"},{"id":429,"date":"2026-08-31","title":"Сколько вообще нужно знать, чтобы принять решение?","summary":"Сколько вообще нужно знать, чтобы принять решение?","summaryKind":"excerpt","text":"Сколько вообще нужно знать, чтобы принять решение?\n\nЯ много пишу о том, что закупщику нужно понимать рынок: из чего состоит продукт, что влияет на его себестоимость, кто формирует основной спрос, где находятся производители, как связаны между собой сырье, мощности, логистика и цена (писала тут и тут)\n\nНо, читая обсуждения некоторых своих кейсов в LinkedIn и охреневая, подумала, что здесь довольно легко впасть в другую крайность: собирать информацию просто потому, что ее можно собрать, особенно при подготовке категорийной стратегии:\n\nМожно бесконечно изучать производителей, технологии, отрасли потребления, географию, индексы, мощности и логистические маршруты. А с ИИ вообще красота: попросил исследовать вопрос и через 5 минут получил еще двадцать направлений, куда неплохо было бы закопаться.\n\nТолько перед очередным заходом я бы сначала спросила себя:\n\n1. Как эта информация может повлиять на мое решение?\n2. При каком ответе я действительно сделаю что-то по-другому?\n3. Насколько велик фактор, который я исследую?\n4. Что я потеряю, если вообще им пренебрегу?\n\nНапример, если выяснится, что определенное сырье составляет 60% себестоимости продукта, а не предполагаемые 20%, это может изменить и переговорную позицию, и подход к индексации. Значит, стоит разбираться.\n\nЕсли один производитель контролирует значимую часть доступных мощностей, это уже влияет на риски и sourcing strategy. Тоже стоит.\n\nА если выяснится, что где-то в условной жопе мира этот материал использует еще одна отрасль, на которую приходится 0,2% мирового потребления, что я сделаю с этой информацией? Скорее всего, ничего.\n\nЕсли сбор урожая ведется определенным трактором и в нем есть какой-то подшипник под санкциями - будет ли это существенным фактом? Мы так трактор разберем по винтикам и все равно решение не поменяем. \n\nВ статистике есть погрешность, которой при определенных условиях мы спокойно пренебрегаем. Примерно так же стоит относиться и к части информации при принятии решений. Тем более сейчас, когда ИИ позволяет накопать ее практически бесконечно.\n\nПоэтому мой критерий довольно простой: если любой ответ на мой вопрос оставляет решение тем же самым, возможно, этот вопрос вообще не стоило исследовать или задавать. А для принятия быстрых решений умение отбрасывать ненужные детали вообще полезный навык. \nТренируется просто:\nПеред анализом сначала сформулируйте, какое решение вам вообще нужно принять и какие 3–5 факторов для него действительно существенны. Все остальное пока отложите. Не навсегда, а до момента, когда оно понадобится.\n\nА для каждого нового факта или вопроса можно использовать два фильтра: «Мне это вообще нужно для решения прямо сейчас?» и «Если ответ окажется другим, мое решение изменится?»\n\nЕсли нет и нет, скорее всего, это деталь, которой сейчас можно пренебречь.","terms":["price-change","negotiation","ai","category"],"topics":["ai","function","negotiation","price"],"url":"https://t.me/notdandeliongirl/429"},{"id":428,"date":"2026-08-28","title":"Пятница, поэтому сегодня немного о ментальном здоровье закупщика.","summary":"Пятница, поэтому сегодня немного о ментальном здоровье закупщика. Иногда внутренний заказчик приходит с задачей, о которой знал 3 месяца, но сообщает о ней сегодня.","summaryKind":"excerpt","text":"#теория \n\nПятница, поэтому сегодня немного о ментальном здоровье закупщика.\n\nИногда внутренний заказчик приходит с задачей, о которой знал 3 месяца, но сообщает о ней сегодня. Купить нужно завтра. ТЗ нет. Бюджет неизвестен. Поставщика он уже нашел сам. А когда выясняется, что завтра не получится, вопрос почему-то звучит: «А почему так долго?!» (у меня всегда в этот момент кровь из ушей идти начинает)\n\nПоэтому несколько советов, которые когда-то могут спасти вам карьеру. Возможно, и избежать уголовки.\n\n1. Никогда не отвечайте сразу, особенно если первый ответ вызывает желание выругаться. \nВыпейте кофе. Посмотрите в окно. Через десять минут «вы охуели» «да вы с ума сошли» обычно неплохо трансформируется в «давайте уточним исходные данные».\n\n2. Просите поставить слово «срочно» в единицах измерения.\nКогда нужно? Что произойдет, если будет на 3 дня позже? Кто остановится? Сколько это стоит? Удивительным образом часть срочных закупок после этого переходит из категории «КАРАУЛ» в категорию «желательно до конца месяца».\n\n3. Не усыновляйте чужую проблему.\nЕсли заявку забыли подать месяц назад, это не значит, что закупщик обязан немедленно надеть плащ Супермена. Помочь решить проблему можно. Стать ее владельцем совсем не обязательно.\n\n4. Если человек говорит «я не знаю, вы же закупки», возвращайте мяч.\nЗакупки могут найти поставщика. Но они не обязаны знать, какой подшипник подойдет к вашему станку, зачем маркетингу именно этот оттенок синего и почему производство внезапно решило купить агрегат, о существовании которого вчера никто не подозревал.\n\n5. Все особенно прекрасные договоренности фиксируйте письменно.\nЧеловеческая память удивительно пластична. Особенно после того, как что-нибудь пошло не так. Фраза «мы же с вами решили» обладает способностью полностью менять содержание примерно за 3 суток.\n\n6. Не пытайтесь победить каждого идиота лично. Улучшайте процесс.\nЕсли 20 человек одинаково неправильно подают заявку, возможно, проблема уже не в 20 людях. Сделайте шаблон, каталог, лимит, автоматическую проверку, другой маршрут согласования. Иногда лучший способ перестать объяснять одно и то же людям заключается в том, чтобы больше никогда им этого не объяснять.\n\n7. И главное: помните, что где-то прямо сейчас внутренний заказчик сидит со своими коллегами и рассказывает, какие же тупые эти закупщики.\n\nВсем хорошей пятницы. И пусть сегодня никто не пришлет вам заявку со словами «там на пять минут» за 5 мин до конца рабочего дня.","terms":[],"topics":["function"],"url":"https://t.me/notdandeliongirl/428"},{"id":421,"date":"2026-08-25","title":"Пока вы отвечаете, напомню, что в @Hirebuyer_bot есть бесплатные инструменты (они же есть и на сайте Hirebuyer.ru); есть бесплатный формирователь скелета категорийной стратегии.","summary":"Пока вы отвечаете, напомню, что в @Hirebuyer_bot есть бесплатные инструменты (они же есть и на сайте Hirebuyer.ru); есть бесплатный формирователь скелета категорийной стратегии. Есть @GenTZbot - формирование ТЗ (3 бесплатных генерации) @negotrainingbot - симулятор переговоров (1 бесплатная генерация).","summaryKind":"excerpt","text":"Пока вы отвечаете, напомню, что в @Hirebuyer_bot есть бесплатные инструменты (они же есть и на сайте Hirebuyer.ru); есть бесплатный формирователь скелета  категорийной стратегии. \nЕсть @GenTZbot - формирование ТЗ (3 бесплатных генерации)\n@negotrainingbot - симулятор переговоров (1 бесплатная генерация).\n\nА на сайте Hirebuyer.ru есть бесплатный кросс-словарь закупщика и описание возможностей платформы.","terms":["negotiation","category"],"topics":["function","negotiation"],"url":"https://t.me/notdandeliongirl/421"},{"id":419,"date":"2026-08-25","title":"Я недавно писала о том, зачем закупщику учиться видеть взаимосвязи на рынке.","summary":"Я недавно писала о том, зачем закупщику учиться видеть взаимосвязи на рынке. Но есть еще один навык, который сильно упрощает задачу по отбиванию повышений цены: привычка раскладывать большую цифру на маленькие.","summaryKind":"excerpt","text":"#теория \n\nЯ недавно писала о том, зачем закупщику учиться видеть взаимосвязи на рынке. Но есть еще один навык, который сильно упрощает задачу по отбиванию повышений цены: привычка раскладывать большую цифру на маленькие.\n\nМы видим цену поставщика, но внутри нее находятся сырье, энергия, труд, оборудование, логистика, постоянные расходы, маржа и другие составляющие. А внутри сырья, в свою очередь, могут быть разные материалы, каждый из которых зависит уже от своих рыночных факторов.\n\nИ так можно спускаться все ниже, пока вместо одной цены перед вами не появится понимание, что именно на нее влияет.\n\nПричем сейчас для первого приближения даже не обязательно самостоятельно знать устройство производства каждой коробки, подшипника или химического продукта. ИИ вполне можно попросить разложить продукт на основные составляющие, предложить гипотезы по их долям и перечислить основные факторы влияния. Именно гипотезы, потому что реальную структуру себестоимости конкретного поставщика модель, конечно, не знает.\n\nНо одного разложения мало. Нужно еще помнить про математику.\n\nДопустим, поставщик объясняет повышение цены на 12% тем, что макулатура выросла на 20%. Но если бумага составляет условно 55% цены продукта, а макулатурная составляющая влияет примерно на 70% стоимости самой бумаги, то этот фактор затрагивает уже не 100% цены, а около 38,5%. Даже при его росте на 20% прямое расчетное влияние получится около 7,7% (формула = 70%*55%*20%)\n\nЭто не означает, что правильное повышение именно 7,7%. У поставщика могут измениться и другие затраты. Но следующий вопрос появиться обязан: а откуда тогда взялись 12%?\n\nИ вот тут уже новости о росте нефти, металла, курса валют, электроэнергии или перевозок не просто поток экономической информации. Вы начинаете понимать, какую часть цены они действительно способны изменить, что стоит проверить и какие вопросы задать поставщику.\n\nПо сути, cost breakdown для меня не столько таблица, сколько способ мышления.\n\nЧем лучше закупщик понимает, из каких именно цифр состоит цена, тем сложнее продать ему универсальное «у нас всё подорожало, поэтому и вам +15%».","terms":["price-change","ai"],"topics":["ai","negotiation","price"],"url":"https://t.me/notdandeliongirl/419"},{"id":418,"date":"2026-08-24","title":"Где заканчивается ИИ-ассистент и начинается закупщик как ассистент ИИ?","summary":"Где заканчивается ИИ-ассистент и начинается закупщик как ассистент ИИ? Я много пишу про использование ИИ в закупках и сама использую его каждый день.","summaryKind":"excerpt","text":"Где заканчивается ИИ-ассистент и начинается закупщик как ассистент ИИ?\n\nЯ много пишу про использование ИИ в закупках и сама использую его каждый день. Но чем больше задач ему отдаешь, тем забавнее становится вопрос: где проходит граница, после которой мы уже не разгружаем себя от рутины, а постепенно отдаем машине собственную способность думать?\n\nМне кажется, есть несколько довольно понятных уровней:\n\n1. На первом ИИ просто делает руками то, что вы умеете делать сами.  Привести таблицу в порядок, собрать информацию, структурировать текст, сравнить документы, подготовить черновик письма или протокола. Вы знаете, каким должен быть результат, можете его проверить, просто не хотите тратить на механическую работу час.\n                      ⬇️\n2. ИИ уже помогает анализировать: группирует предложения поставщиков, ищет отклонения, предлагает варианты структуры TCO, собирает аргументы к переговорам, показывает закономерности в данных. Но постановка задачи, критерии оценки и решение по-прежнему ваши. Если модель выдала ерунду, вы понимаете почему.\n                      ⬇️\n3. Вы строите вокруг ИИ процесс. Например, сначала обычный алгоритм очищает данные, затем модель разбирает только неоднозначные случаи, результат проверяется по заданным правилам, а решения с высоким риском уходят человеку. Здесь ИИ уже делает довольно много, но архитектурой все еще управляете вы.\n                     ⬇️❓\n4. А потом можно довольно незаметно перейти на темную сторону:\n\n«Выбери лучшего поставщика»; «Скажи, какую цену запросить»; «Оцени риски»; «Напиши категорийную стратегию»; «Что мне делать на переговорах?»\n\nИ если закупщик принимает ответ, не понимая, почему модель пришла именно к нему, кто кому в этот момент ассистент, становится уже не очень понятно.\n\nДля меня критерий довольно простой: я могу отдать ИИ расчеты, поиск, оформление, первую аналитику и даже попросить его поспорить со мной. Но я должна уметь поставить задачу до него, проверить логику после него и принять решение без него.\n\nПотому что цель автоматизации вообще-то в том, чтобы освободить голову закупщика для более сложной работы.\n\nБудет довольно обидно, если в результате мы освободим ее совсем.\n\nПС в вайбкодинге я не могу во многом принять решение без ИИ, но я могу построить архитектуру и провести с другой ИИ ревью кода. Согласитесь, это не слепое доверие","terms":["tco","negotiation","ai","automation","category"],"topics":["ai","data","function","negotiation","price"],"url":"https://t.me/notdandeliongirl/418"},{"id":416,"date":"2026-08-21","title":"У компании может быть десять лет истории работы с поставщиком и практически ноль памяти об этой работе.","summary":"У компании может быть десять лет истории работы с поставщиком и практически ноль памяти об этой работе. Он участвовал в тендерах, срывал и выполнял поставки, привозил брак, исправлял его или месяцами спорил по рекламациям, соглашался помочь в критической ситуации или пропадал именно тогда, когда был особенно нужен.","summaryKind":"excerpt","text":"#теория \n\nУ компании может быть десять лет истории работы с поставщиком и практически ноль памяти об этой работе.\n\nОн участвовал в тендерах, срывал и выполнял поставки, привозил брак, исправлял его или месяцами спорил по рекламациям, соглашался помочь в критической ситуации или пропадал именно тогда, когда был особенно нужен. Все это компания когда-то знала. Потом меняется закупщик, проходит год, начинается новый тендер, и перед нами снова просто строчка: поставщик А, цена такая-то.\n\nПоэтому мне всегда казалось странным, когда SRM фактически превращается в карточку поставщика с реквизитами, категорией и результатами очередной квалификации. Для меня нормальный SRM должен быть в первую очередь корпоративной памятью закупок, причем памятью, которая по возможности формируется сама из фактических данных.\n\nВ идеале такая система связана с ERP. OTIF, фактические сроки поставки, отклонения по количеству и цене, выполнение условий договора и другие показатели, которые уже существуют в системах компании, вообще не должны зависеть от субъективной оценки закупщика. Они должны подтягиваться автоматически.\n\nНо одной ERP тоже мало. История поставщика складывается не только из того, что видят закупки:\nКачество знает про брак и рекламации, \n\nпроизводство про стабильность материала и проблемы в работе, \n\nR&D про квалификацию и готовность поставщика к изменениям, \n\nфинансы про платежные и документарные вопросы. \n\n\nПоэтому SRM должен постепенно насыщаться данными разных функций и собирать их в одну историю.\nТогда это уже не рейтинг ради рейтинга. Эту историю можно использовать при следующем тендере, распределении объемов, развитии поставщика, выборе резервного источника или решении постепенно отказаться от работы с ним.\n\nПри этом я бы не пыталась свести все к красивым 87,4 балла из 100. Иногда один критичный показатель важнее прекрасной средней оценки. Поставщик может быть хорош по цене, документообороту и скорости ответа, но если он регулярно срывает поставки критичного сырья, средний балл меня мало утешит.\n\nНаверное, в этом для меня и есть основная ценность нормального SRM: когда  следующий закупщик начинает отношения с ним не с чистого листа, а с корпоративной памятью за спиной.","terms":["leadtime","supplier-risk","srm"],"topics":["inventory","supplier"],"url":"https://t.me/notdandeliongirl/416"},{"id":414,"date":"2026-08-20","title":"Продолжу примерять разные известные эффекты и закономерности к закупкам.","summary":"Продолжу примерять разные известные эффекты и закономерности к закупкам. Сегодня эффект якоря.","summaryKind":"excerpt","text":"#теория \nПродолжу примерять разные известные эффекты и закономерности к закупкам. Сегодня \nэффект якоря.\n\nНаверняка многие слышали классический совет для переговоров: постарайтесь не называть свою цену первым.\n\nЭффект якоря заключается в том, что первая появившаяся цифра становится для нашего мозга точкой отсчета. Причем даже тогда, когда мы сами понимаем, что эта цифра условна. Все последующие предложения мы уже невольно оцениваем относительно нее.\n\nПредставим переговоры с поставщиком. Его цена 120 рублей, и закупщик говорит: «Мне нужно 100». В этот момент 100 рублей перестают быть просто одной из возможных цифр. Поставщик уже знает, чего вы хотите, и все дальнейшие переговоры начинает строить вокруг этого якоря: 100 вам нужно, 105 уже почти компромисс, а 103 вообще выглядит прекрасной уступкой.\n\nНо что, если поставщик был готов на 95?\n\nВы этого уже можете никогда не узнать, потому что сами сообщили ему вполне приемлемую для вас точку приземления.\n\nПоэтому я обычно не торопилась бы начинать переговоры с конкретной целевой цены. Сначала гораздо интереснее понять, сколько пространства вообще есть у второй стороны: обсудить рынок, объемы, изменение сырьевых составляющих, условия оплаты, логистику, обязательства по объемам, запросить скидку и посмотреть на реакцию. То есть сначала собрать максимум информации и только потом, если это действительно нужно, ставить свой ценовой якорь. То есть - сначала дипломатические реверансы- и пока они идут, вы параллельно в голове перестраиваете и пересчитываете варианты. \n\n(Правда, есть и обратная сторона. Если рынок хорошо изучен, should-cost понятен и вы действительно знаете, сколько должен стоить продукт, первым назвать обоснованную цену может быть как раз выгодно. Тогда уже поставщику приходится объяснять, почему он должен увести переговоры от вашей цифры)\n\nПоэтому правило для меня звучит скорее так: не называй первым ту цену, которая просто показывает поставщику, сколько ты готов заплатить. Если уж ставить якорь, то осознанно и в свою пользу.\n\nПС бывали жесткие переговоры, когда я просто ставила перед фактом - надо вот столько и нии…т.","terms":["deferral","negotiation"],"topics":["finance","negotiation"],"url":"https://t.me/notdandeliongirl/414"},{"id":411,"date":"2026-08-18","title":"Нам с Юрой @yuraberg периодически пишут в личку с очень разными вопросами про ИИ: - Как настроить анализ КП?","summary":"Нам с Юрой @yuraberg периодически пишут в личку с очень разными вопросами про ИИ: - Как настроить анализ КП? - Можно ли загрузить в модель рабочий Excel?","summaryKind":"excerpt","text":"Нам с Юрой @yuraberg  периодически пишут в личку с очень разными вопросами про ИИ:\n- Как настроить анализ КП? \n- Можно ли загрузить в модель рабочий Excel? \n- Как обезличить данные? \n- Как сделать свой skill? \n- Нужен ли для задачи бот? \n- Как автоматизировать то, что сейчас вручную делается в Excel? \n- И обязательно ли вообще для этого использовать ИИ?\nВ какой-то момент стало понятно, что отвечать на каждый такой вопрос отдельно - не очень правильный путь. Нет, не потому что мы не хотим отвечать. Просто это занимает огромное количество нашего времени (да-да, у нас тоже семьи work0life balance).\n\nПоэтому мы с Юрой решили собрать большой модульный курс «ИИ в закупках: от задачи к решению».\nНо это не будет сборник из «500 готовых промптов».\nНам хочется научить вас не модному \"вот готовые промтпы\", а чему-то большему-  взять новую рабочую задачу и самому понять:\n- нужен ли здесь вообще ИИ;\n- что лучше посчитать обычным Excel / Power Query / кодом;\n- что имеет смысл поручить модели;\n- какие данные ей можно передать;\n- как проверить результат;\n- когда достаточно промпта, а когда уже нужен skill, бот, workflow или API.\nТо есть постепенно будем учиться не только пользоваться нейросетями, но и архитектурно мыслить о решении задачи.\nКурс собираем как конструктор из коротких роликов. Несколько роликов = законченный модуль примерно на полчаса. Можно будет брать только те модули, которые нужны именно вам.\nПервый модуль уже начали собирать.\nВот небольшой тизер ⤴️","terms":["ai","automation"],"topics":["ai","data"],"url":"https://t.me/notdandeliongirl/411"},{"id":410,"date":"2026-08-18","title":"Наверное, многие из нас сталкивались с ситуацией: тендер проведен, победитель выбран, результаты согласованы внутри компании, экономия уже посчитана, и где-то на этапе подписания спецификации поставщик внезапно сообщает, что «извини, брат», но по этой цене поставлять он все-таки не может.","summary":"Наверное, многие из нас сталкивались с ситуацией: тендер проведен, победитель выбран, результаты согласованы внутри компании, экономия уже посчитана, и где-то на этапе подписания спецификации поставщик внезапно сообщает, что «извини, брат», но по этой цене поставлять он все-таки не может. Что самое дерьмовое, помимо того, как на вас будет смотреть руководство?","summaryKind":"excerpt","text":"#теория\n\nНаверное, многие из нас сталкивались с ситуацией: тендер проведен, победитель выбран, результаты согласованы внутри компании, экономия уже посчитана, и где-то на этапе подписания спецификации поставщик внезапно сообщает, что «извини, брат», но по этой цене поставлять он все-таки не может.\n\nЧто самое дерьмовое, помимо того, как на вас будет смотреть руководство? Вы уже защитили результат перед тендерным комитетом, возможно, отказали другим участникам, все увидели красивую экономию, а теперь нужно возвращаться назад и объяснять, куда она делась.\n\nНа самом деле поставщик действительно мог ошибиться: Не учесть логистику, неправильно посчитать объем, забыть какую-то составляющую себестоимости или просто поставить не ту цифру. Всякое бывает. \nНо бывает и другой вариант: цена была занижена вполне сознательно, чтобы сначала выиграть тендер, а обсуждать ее реальность уже потом, когда заказчик прошел внутренние согласования, остальные участники получили отказ и откатывать решение назад стало гораздо сложнее.\n\nПоэтому я всегда довольно настороженно отношусь не только к аномально высокой, но и к аномально низкой цене: \n\nЕсли один поставщик сильно выбивается из рынка или предложений остальных участников, я бы еще до объявления победителя попросила повторно подтвердить цену и условия, а при необходимости дать cost breakdown и показать, откуда вообще взялась такая щедрость.\n\nМожно защищаться и формально. Например, вместе с ценой получать от поставщика оферту, чтобы его предложение было не просто цифрой в тендерной форме. \nДля крупных и рискованных тендеров использовать обеспечение заявки. Понятно, что превращать закупку условных карандашей в юридическую спецоперацию не надо, поэтому уровень защиты должен соответствовать цене ошибки.\n\nНо допустим, все проверки пройдены, победитель объявлен, и ошибка все-таки вылезла. Я бы в этот момент сначала пыталась понять, действительно ли это ошибка. Если поставщик просто решил переиграть тендер постфактум, позиция должна быть достаточно жесткой, иначе очень быстро формируется прекрасная практика: даем любую цену, выигрываем, ждем, пока заказчик согласует результат, а потом начинаем второй раунд переговоров.\n\nЕсли ошибка реальная, ситуация для меня уже не настолько однозначная. Формально можно сказать: сам ошибся, сам и поставляй. Но поставщик, которого мы заставили несколько месяцев работать себе в убыток, от этого не становится для нас выгодным. Он начнет искать, где компенсировать потери, может ухудшить сервис, отказаться от поставок или просто придет на следующий тендер с ценой, в которую заранее зашьет предыдущий убыток. Поэтому я в таких случаях сначала проверила бы расчеты, а дальше, в зависимости от ситуации, рассматривала бы и вариант разделить ошибку, например 50 на 50. Полностью оплачивать чужой косяк странно, но и радоваться контракту, который поставщик физически не способен нормально исполнить, тоже.\n\nВ общем, я бы вообще осторожнее называла экономией цифру, которая появилась в протоколе после тендера. Экономия появляется тогда, когда компания действительно получила товар или услугу на этих условиях.\n\nИногда вопрос «почему этот поставщик настолько дешевле остальных?» гораздо полезнее задать до того, как показать всем, сколько денег вы только что сэкономили.","terms":["negotiation"],"topics":["negotiation"],"url":"https://t.me/notdandeliongirl/410"},{"id":406,"date":"2026-08-13","title":"Продолжу пост Я очень часто вижу или рекламу вебинара, который перевернет мою жизнь «вы уйдете с готовым промптом на….» или слышу «Да загрузи ты это в ИИ, пусть думает».","summary":"Продолжу пост Я очень часто вижу или рекламу вебинара, который перевернет мою жизнь «вы уйдете с готовым промптом на….» или слышу «Да загрузи ты это в ИИ, пусть думает». Казалось, ну, разве не для этого в помощь нам он и придуман?","summaryKind":"excerpt","text":"Продолжу пост\n#теория \nЯ очень часто вижу или рекламу вебинара, который перевернет мою жизнь «вы уйдете с готовым промптом на….» или слышу «Да загрузи ты это в ИИ, пусть думает». Казалось, ну, разве не для этого в помощь нам он и придуман?\n\nНапример, нормализация справочника номенклатуры. (Любимая задача всех вайбкодеров, коучей или ИТ-компаний- сразу же прикручивать к ней ИИ). \n\nНо давайте для начала разберем эту задачу:\n\n«Подшипник 6205», «подш. 6205», «6205 SKF» могут оказаться одной позицией. А могут и не оказаться. Добавляем опечатки, единицы измерения, артикулы, производителей, размеры, старые наименования, аналоги, взаимозаменяемость, и задача «найди похожие строчки» внезапно становится задачей с поправками промпта после каждого прогона и сжиганием токенов, так как обнаруживаются новые классы исключений, незаложенные в логику. \n\nИИ здесь, безусловно, может быть очень полезен. Но совсем не обязательно в начале и точно не для всего.\n\nТак что с задачей? \nКак я писала выше, определите, что можно решить простым кодом или алгоритмом: \n\nСначала данные можно привести к единому виду, разобрать на атрибуты, нормализовать единицы измерения и написание, отделить артикулы и производителей. Очевидные совпадения убрать обычными алгоритмами, сгруппировать потенциальные дубли, а ИИ оставить то, в чем действительно нужна работа со смыслом и неоднозначностью. И обязательно оставить контроль там, где цена ошибки высока - то есть обращение к человеку по установленной логике  принятия решения. \n\nПолучается немного парадоксально: чем больше мы используем ИИ, тем меньше задача становится задачей про «правильный промпт». Сам-то промпт никуда не исчез. Но постепенно уходит идея, что достаточно придумать волшебную формулировку, загрузить файл и получить готовый бизнес-процесс. В реальном инструменте гораздо важнее, что происходит до обращения к модели, что именно ей передается, какие правила действуют после ответа и кто проверяет результат.\n\n(А еще в самом начале должен появиться один вопрос, о которым все время забывают: а этот файл вообще можно отправлять именно в эту модель? Рабочая номенклатура в корпоративном защищенном контуре и тот же файл, загруженный сотрудником в личный AI-аккаунт, могут быть совершенно разными историями)\n\nПоэтому работа с задачей должна начинаться не с фразы «засунем в ИИ и напишем промпт», а с декомпозиции:\n\n1. Как выглядит сама задача, \n2. на какие этапы ее можно разложить,\n3. на каком из них ИИ действительно даст пользу?\n4. как я проверю результат и что произойдет при низкой уверенности?\n\nАрхитектура - это инструмент. А засунуть - это просто…засунуть.","terms":["mdm","ai"],"topics":["ai","data"],"url":"https://t.me/notdandeliongirl/406"},{"id":402,"date":"2026-08-12","title":"Я уже присылала простенький инструмент для обезличивания данных.","summary":"Я уже присылала простенький инструмент для обезличивания данных. Сейчас сделала его апгрейд.","summaryKind":"excerpt","text":"#юзфултип \nЯ уже присылала простенький инструмент для обезличивания данных. Сейчас сделала его апгрейд. (Если в компании стоит запрет на отправку данных в ИИ - этот инструмент закроет вопрос). Инструкция ниже:\n\n1. Один раз установить макрос\nОткрой нужный Excel-файл и сохрани его как «Книга Excel с поддержкой макросов (*.xlsm)».\nНажми Alt + F11 → в редакторе VBA выбери File → Import File… → выбери файл во вложении к посту. Закрой редактор VBA и сохрани Excel-файл.\n2. Как обезличить файл\nОткрой свой .xlsm.\nНа листе выдели мышкой колонки, которые надо обезличить. Несколько отдельных колонок — с зажатым Ctrl.\nНажми Alt + F8.\nВыбери CreateAIFile → Выполнить.\nДля каждой колонки подтверди название замены: например Поставщик, Клиент, Сотрудник.\nРядом с исходным файлом автоматически появится новый файл вида Название_AI_....xlsx.\nИменно этот _AI_ файл можно отдавать ИИ. Исходный файл не изменяется, а ключ расшифровки остаётся внутри .xlsm.\n3. Как потом расшифровать результат\nОткрой тот же исходный .xlsm, в котором находится ключ.\nНажми Alt + F8.\nВыбери DecodeAIFile → Выполнить.\nУкажи Excel-файл, который вернул ИИ.\nМакрос создаст рядом новый файл ..._DECODED_....xlsx с восстановленными реальными названиями.\nВажно: не удаляй исходный .xlsm — в нём хранится ключ Поставщик 1 → ООО Ромашка и т. д.","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/402"},{"id":397,"date":"2026-08-10","title":"Скоро у многих начнется подготовка бизнес-планов.","summary":"Скоро у многих начнется подготовка бизнес-планов. У кого-то в конце августа, у кого-то в октябре.","summaryKind":"excerpt","text":"Скоро у многих начнется подготовка бизнес-планов. У кого-то в конце августа, у кого-то в октябре. \n\nКомпании расценивают бюджет по-разному. Где-то, как было у нас в Русале, просят расценить каждую позицию отдельно. Очень трудоемко. БП был событием. Где-то подробно считают крупное сырье, которое может занимать 60–70% бизнес-плана, а все остальное берут чохом или пропорционально увеличивают прошлогодние цены.\n\nВ результате закупщики либо неделями расценивают тысячи позиций вручную, либо компания получает довольно грубую оценку существенной части бюджета.\n\nПри этом бюджет вообще не требует точности до копейки. Ему нужен разумный порядок цифр. Бизнес-план это не финальная зафиксированная цена, а рабочий ориентир, который все равно приходится корректировать в течение года. Ключевая ставка изменилась, курс сдвинулся, инфляция оказалась другой, поменялась покупательская способность, вырос бензин и потянул за собой логистику….Можно потратить недели на идеальную расценку, а через два месяца рынок спокойно обнулит эту точность.\nВариант, который используют далеко не все - это бюджет, гибкий к изменениям. Есть два способа этого добиться:\n\n1. Менять макропараметры по мере изменения ситуации и пересчитывать оставшийся план за вычетом уже потраченного бюджета. \n2. Изначально закладывать не одну цифру, а три сценария: пессимистичный, реалистичный и оптимистичный.\n\nЕсли курс, инфляция, ключевая ставка и другие значимые параметры системно зашиты в модель, изменение исходных данных позволяет быстро пересчитать весь бюджет, а не начинать бюджетирование заново.\n\nПоэтому хороший инструмент бюджетирования позволяет быстро пересчитать последствия.\n\nКогда-то в Русал  сделала инструмент именно под эту задачу: \n\nЕсли закупка была в прошлом году - цена плюс инфляция. по позиции не было закупки год назад, инструмент ставил инфляцию, умноженную на два. (не четко х2, Х3, а база старого года на инфляцию нового). Если три года подряд, автоматике неоткуда было взять базу, и цену закупщик прописывал сам.\n\nОтдельно считал полную стоимость импортных позиций: НДС и пошлину, зашитые на уровне категории, и логистику- либо по факту прошлого года, либо по общему макропараметру. \n\nЕсли реальное отклонение сильно отличалось от расчётного, -в плюс или в минус, - система подсвечивала это как аномалию, и закупщик должен был объяснить причину.\n\nПо хвостовым и массовым позициям расчёт был окончательным. По крупному сырью и материалам, входящих в Парето, служил верхней границей-ориентиром: закупщик почти всегда пересчитывал сам, опираясь на переговоры с поставщиком, логистику, ожидания рынка, но при выходе за эту границу тоже требовалось объяснение. Ну и куча прочих приколюх. Макропараметры, разумеется, были зашиты в справочнике.  \n\nК чему это все - если у вас нет инструмента для адекватного формирования БП или он долог и мучительно болезнен, есть еще пара-тройка недель, чтобы сделать простой инструмент хотя бы в Экселе. Ну или сделать его основанием для ТЗ для ERP.  \nЕсли есть вопросы- не надо быть стесняшкой. Я всегда отвечу 🤓","terms":["price-change","negotiation","mdm"],"topics":["data","negotiation","price"],"url":"https://t.me/notdandeliongirl/397"},{"id":391,"date":"2026-08-07","title":"В @Hirebuyer_bot появились отзывы.","summary":"В @Hirebuyer_bot появились отзывы. На сайте Hirebuyer.ru - бесплатные инструменты для тех, кому не удобно их брать в телеге.","summaryKind":"excerpt","text":"В @Hirebuyer_bot появились отзывы. \nНа сайте Hirebuyer.ru - бесплатные инструменты для тех, кому не удобно их брать в телеге.\nНапоминаю - на сайте есть удобный кросс-словарь Закупщика (мини-Обсидиан). Он совершенно бесплатен и подойдет для обучения ваших сотрудников😏\n\nИ сегодня дам вам хороший управленчески-закупочный кейс на подумать.","terms":[],"topics":["function"],"url":"https://t.me/notdandeliongirl/391"},{"id":390,"date":"2026-08-07","title":"Все знают про эффект Даннинга -Крюгера?","summary":"Все знают про эффект Даннинга -Крюгера? «Новичок почти ничего не знает, но уверен, что знает всё».","summaryKind":"excerpt","text":"Все знают про эффект Даннинга -Крюгера?  «Новичок почти ничего не знает, но уверен, что знает всё». \n\nА вот про обратную сторону говорят намного реже: чем опытнее становится человек, тем больше он начинает сомневаться. В закупках замечаю такое постоянно (и в себе тоже):\n\n1. Появляется новый поставщик. Можно провести с ним 5 встреч. Но ведь можно и 7.\n2. Можно получить 3 коммерческих предложения. А можно собрать еще 5.\n3. Можно остановиться на анализе рынка. А можно еще проверить финансовое состояние поставщика, поговорить с бывшими клиентами, посмотреть судебные дела, запросить дополнительные образцы, съездить на производство, запросить план развития…..\n\n- Мы сильнее давим поставщика;\n- Дольше принимаем решения;\n- Усложняем процессы.\n\nЧто такое один день, когда мы уменьшаем риск? Ну, два. Да даже три. \n\nПока однажды поиск лучшего решения не начинает мешать самому решению. Может, мы просто пытаемся добиться невозможного - убрать риск совсем?\n\nМне кажется, это проф деформация многих сильных закупщиков. Мы настолько хорошо знаем, где может «выстрелить», что иногда начинаем бороться уже не с реальными рисками, а с гипотетическими.\n\n1. Где заканчивается качественный анализ и начинается перфекционизм?\n\n1. Где проходит граница между “достаточно хорошим решением” и бесконечным поиском идеального?\n\n3 И кто вообще установил эту границу? Можем ли мы сами ее определить?\n\nНа эти вопросы у меня до сих пор нет универсального ответа.\nПС Картинка просто мем.","terms":["market"],"topics":["price","supplier"],"url":"https://t.me/notdandeliongirl/390"},{"id":388,"date":"2026-08-06","title":"В нашем боте @Hirebuyer_bot появились бесплатные инструменты: 1.","summary":"В нашем боте @Hirebuyer_bot появились бесплатные инструменты: 1. Зависимость от поставщика - короткая простая анкета 2.","summaryKind":"excerpt","text":"#юзфултип \nВ нашем боте @Hirebuyer_bot появились бесплатные инструменты:\n1. Зависимость от поставщика - короткая простая анкета \n2. Готовность закупочной функции к ИИ-внедрению \n3. План действий по категории (именно план-скелет)\n4. Экселевские шаблоны из канала, чтобы было проще искать\n\nБуду благодарна за шеры. Также хочется попросить, коллеги, оставлять отзывы - во-первых, отклик в сердцах зрителей всегда приятен, во-вторых, это поможет нашему дальнейшему развитию 😉","terms":["ai","governance"],"topics":["ai","function"],"url":"https://t.me/notdandeliongirl/388"},{"id":384,"date":"2026-08-05","title":"Совсем забыла - наш сервис официально запущен.","summary":"Совсем забыла - наш сервис официально запущен. Есть демо \"Где мои деньги?\", есть уже известные вам боты - генератор ТЗ и симулятор переговоров.","summaryKind":"excerpt","text":"Совсем забыла - наш сервис https://hirebuyer.ru/ официально запущен. Есть демо \"Где мои деньги?\", есть уже известные вам боты - генератор ТЗ и симулятор переговоров. \nНа пути к выпуску - анализатор номенклатуры и формирователь категорийной стратегии. \nТакже мы сделали кросс-словарь основных терминов закупщика. Проверьте себя))\nКак обычно, будем рады отзывам. \nКнопка вызов эксперта идет в телеграм-бот. Там можно также оставить свой комментарий","terms":["negotiation","category"],"topics":["function","negotiation"],"url":"https://t.me/notdandeliongirl/384"},{"id":381,"date":"2026-08-04","title":"Или все в отпусках или ленятся размять мозги.","summary":"Или все в отпусках или ленятся размять мозги. Не каждой проблеме в закупках нужен искусственный интеллект.","summaryKind":"excerpt","text":"Или все в отпусках или ленятся размять мозги.\n\n\nНе каждой проблеме в закупках нужен искусственный интеллект.\nОколо года (!) назад McKinsey опубликовала исследование The State of AI. Один из выводов оказался неожиданным.\nСамый большой эффект получают не компании, которые просто подключили AI, а те, кто сначала изменил процессы, а уже потом встроили в них AI. При этом только около 21% организаций, использующих генеративный AI, действительно перепроектировали хотя бы часть рабочих процессов. Большинство просто добавило AI поверх старого.\nПара примеров, как это выглядит на задачах закупщика: \n\n18 согласований счёта - нужна перестройка процесса, а не AI. Он не исправляет плохую архитектуру, он просто ускоряет её ровно настолько же плохую версию.\n\nА вот проверка договора на 120 страниц, это как раз территория LLM. Отлично ищет отличия, риски, готовит вопросы.\n\nПолную таблицу с остальными примерами прикладываю картинкой.\n\nНа днях я говорила об этом же на встрече с одной федеральной компанией. Сказала прямо: не обязательно прикручивать AI туда, где хватит простой автоматизации. Мне ответили, что их IT-директор считает ровно так же (💪)\n\nМожет, в этом и есть весь смысл исследования. Не гнаться за AI, а для каждой проблемы находить нужный инструмент, даже если это скучная перестройка процесса или обычный дашборд без единой нейросети внутри.","terms":["analytics","ai","automation"],"topics":["ai","data"],"url":"https://t.me/notdandeliongirl/381"},{"id":379,"date":"2026-08-03","title":"Друзья, запустила тестовую версию бота для тренировки закупочных переговоров (симулятор переговоров является частью пакетов нашего с @yuraberg сервиса HireBuyer, но если вам для вашего бизнеса нужен такой обучающий инструмент - пишите, обсудим).","summary":"Друзья, запустила тестовую версию бота для тренировки закупочных переговоров (симулятор переговоров является частью пакетов нашего с @yuraberg сервиса HireBuyer, но если вам для вашего бизнеса нужен такой обучающий инструмент - пишите, обсудим). Это ИИ-симулятор поставщика: вы выбираете тип поставщика, отрасль, долю в закупках и цель переговоров, а дальше ведёте диалог как в реальных переговорах.","summaryKind":"excerpt","text":"#юзфултип \nДрузья, запустила тестовую версию бота для тренировки закупочных переговоров (симулятор переговоров является частью пакетов нашего с @yuraberg сервиса HireBuyer, но если вам для вашего бизнеса нужен такой обучающий инструмент - пишите, обсудим).\n\nЭто ИИ-симулятор поставщика: вы выбираете тип поставщика, отрасль, долю в закупках и цель переговоров, а дальше ведёте диалог как в реальных переговорах.\nПосле каждого вашего хода бот:\n1. отвечает как поставщик;\n2. показывает, что в вашем ходе было сильным, а что нет;\n3. подсвечивает ошибки и риски;\n4. предлагает, как усилить следующий аргумент.\nВ конце сессии бот даёт итоговую оценку и рекомендации.\n\nСейчас это пилотная версия. Бесплатно доступна одна тренировка, базовые сценарии и короткие голосовые сообщения до 30 секунд. Если понравится  - на время пилота цена снижена.\nЕсли что-то сломается, есть кнопка обращения по оплате или отзывы. Я увижу обращение и смогу разобраться.\nПопробовать: @negotrainingbot\nБуду благодарна за обратную связь: что понятно, что неудобно, каких сценариев переговоров не хватает.","terms":["negotiation","ai"],"topics":["ai","negotiation"],"url":"https://t.me/notdandeliongirl/379"},{"id":377,"date":"2026-08-03","title":"На одной встрече генеральный директор рассказал мне, что после серии откатов в закупках компания сильно ужесточила весь закупочный процесс: добавили согласования, проверки СБ, уровни контроля.","summary":"На одной встрече генеральный директор рассказал мне, что после серии откатов в закупках компания сильно ужесточила весь закупочный процесс: добавили согласования, проверки СБ, уровни контроля. В итоге закупки стали настолько мучительно длинными, что бизнес начал страдать уже не от мошенничества, а от самой системы защиты.","summaryKind":"excerpt","text":"#теория \nНа одной встрече генеральный директор рассказал мне, что после серии откатов в закупках компания сильно ужесточила весь закупочный процесс: добавили согласования, проверки СБ, уровни контроля. В итоге закупки стали настолько мучительно длинными, что бизнес начал страдать уже не от мошенничества, а от самой системы защиты.\n\nТакая реакция понятна. После серьезного нарушения хочется проверить всё и всех. Но тотальный контроль редко равен эффективному контролю. Он одинаково тормозит и канцтовары на десять тысяч, и критичный CAPEX на сотни миллионов, при этом настоящий сговор всё равно может пройти через идеально заполненные документы и формально соблюденную процедуру.\n\nRisk-based procurement governance устроен иначе. Сначала компания определяет, где действительно находится риск, а потом под него настраивает маршрут закупки. Оценивается не только сумма, важны критичность для производства, наличие альтернатив, новый или проверенный поставщик, возможность конфликта интересов, изменение спецификации, доля закупки у единственного источника, нестандартные условия оплаты, срочность, отклонение цены от рынка и история предыдущих нарушений.\n\nНизкорисковые повторяющиеся закупки можно отдавать внутренним заказчикам через согласованные каталоги, лимиты и проверенных поставщиков. Закупщик не должен вручную покупать каждую стандартную позицию и собирать три фиктивных КП там, где рынок и условия давно определены.\n\nДля среднего риска нужен обычный прозрачный маршрут: сравнение условий, бюджетный контроль, подтверждение потребности, проверка поставщика и понятные лимиты полномочий.\n\nА вот высокий риск должен попадать под усиленный контроль. Это крупные суммы, единственный поставщик, критичные материалы, новые контрагенты, изменение ТЗ под конкретного производителя, резкое отклонение цены, аффилированность, необычная срочность или попытка обойти установленный процесс. Здесь уже нужны разделение полномочий, независимая техническая оценка, СБ, финансовая проверка, комиссия и цифровой след решения.\n\nВажен и контроль после закупки. Если система проверяет только наличие трех КП и подписей, она видит форму, но может не увидеть риск. Гораздо полезнее искать аномалии: один и тот же поставщик постоянно выигрывает у одного закупщика, цены отклоняются от рынка, спецификации регулярно меняются перед тендером, дробятся суммы, растет доля срочных закупок, поставщик получает нетипичные условия.\n\nТо есть risk-based governance не убирает контроль, но делает его точнее.\n\nПростые закупки идут быстрее. Закупщики высвобождают время для категорий, поставщиков и рисков. А внимание СБ, финансов и руководителей концентрируется там, где цена ошибки действительно высока.\n\nПосле откатов компании часто строят тюрьму. Но зрелая система должна не запирать всех честных сотрудников в одном процессе, а уметь отличать обычную заявку от ситуации, в которой действительно есть риск злоупотребления.","terms":["deferral","governance"],"topics":["finance","function","negotiation"],"url":"https://t.me/notdandeliongirl/377"},{"id":364,"date":"2026-07-28","title":"Как мыслят финансисты и почему закупщику важно их понимать Закупщик приходит на встречу и говорит: «Я снизил цену на 8%».","summary":"Как мыслят финансисты и почему закупщику важно их понимать Закупщик приходит на встречу и говорит: «Я снизил цену на 8%». Он ожидает, что финансисты сразу увидят результат.","summaryKind":"excerpt","text":"Как мыслят финансисты и почему закупщику важно их понимать\n\nЗакупщик приходит на встречу и говорит: «Я снизил цену на 8%». Он ожидает, что финансисты сразу увидят результат. Но в ответ может услышать: «А какую отсрочку платежа вы получили?»\n\nНа первый взгляд это выглядит странно. Скидка уменьшает затраты компании, а отсрочка цену вообще не меняет. Почему же для финансов условия оплаты иногда не менее важны, чем стоимость закупки?\n\nПотому что закупщик часто смотрит прежде всего на цену сделки, а финансист одновременно оценивает прибыль, движение денег и оборотный капитал. Для него важно не только сколько компания заплатит, но и когда деньги уйдут со счета, придется ли занимать их в банке и хватит ли компании средств на зарплаты, налоги, сырье и другие обязательства.\n\nПредставим, что компания закупает материалы на 100 млн рублей. При оплате сразу эти деньги немедленно уходят поставщику. При отсрочке 60 дней материалы уже поступили и могут использоваться в производстве, а 100 млн еще два месяца остаются внутри бизнеса. Компания может не брать кредит, профинансировать другие закупки или пережить разрыв между оплатой сырья и получением денег от покупателей.\n\nЭто и есть одна из задач управления оборотным капиталом: не допустить ситуации, когда компания прибыльна на бумаге, но у нее не хватает живых денег для текущей работы. Деньги могут быть заморожены в запасах и дебиторской задолженности, а поставщикам при этом нужно платить сегодня.\n\nНо здесь есть важная оговорка. Отсрочка не становится автоматически выгоднее скидки. Эти условия нужно переводить в деньги и сравнивать.\n\nСкидка 8% со 100 млн дает компании 8 млн рублей прямого эффекта. Стоимость отсрочки на 60 дней при цене денег 20% годовых составляет примерно 3,3 млн рублей. В таком примере скидка финансово выгоднее. Однако при дефиците ликвидности, дорогом кредите, большом объеме закупок или риске кассового разрыва компания может сознательно выбрать отсрочку. Не потому, что финансисты не умеют считать экономию, а потому, что сегодня для бизнеса наличие денег на счете может быть важнее дополнительной прибыли в отчетности.\n\nПоэтому сильный закупщик должен приносить на согласование не одну цифру: «Мы получили скидку 8%». Он должен показывать несколько вариантов и их влияние на бизнес: цену, срок оплаты, стоимость финансирования, объем высвобожденного оборотного капитала и риски поставщика.\n\nФинансисты мыслят не отдельной закупкой, а всей денежной системой компании. И чем лучше закупщик понимает эту логику, тем реже его результат заканчивается спором о процентах и тем чаще превращается в решение, которое действительно нужно бизнесу.\n\nЗакупки становятся стратегической функцией не тогда, когда умеют выбивать максимальную скидку, а тогда, когда понимают, какой финансовый результат компания покупает вместе с этой скидкой.","terms":["working-capital","deferral","supplier-risk"],"topics":["finance","negotiation","supplier"],"url":"https://t.me/notdandeliongirl/364"},{"id":359,"date":"2026-07-27","title":"Возвращаю случайно удаленный пост.","summary":"Возвращаю случайно удаленный пост. Мы с @yuraberg давно (и, уверена, успешно) работаем над проектом для малого и среднего бизнеса «Закупщик в аренду».","summaryKind":"excerpt","text":"Возвращаю случайно удаленный пост.\n\nМы с @yuraberg давно (и, уверена, успешно) работаем над проектом для малого и среднего бизнеса «Закупщик в аренду». \nЭто набор инструментов, который позволяет без найма аудита, дорогих экспертов, долгих интеграций сделать анализ своих закупок. Сравнить ТКП по совокупной стоимости владения и сформировать письмо поставщику. Выработать стратегию переговоров с учетом своих условий и отрасли. Сформировать ТЗ на закупку оборудования или запчастей. Все то, что сложно сделать или минимальным составом или же хочется оптимизировать труд сотрудников.\n\nНекоторые инструменты - например, @GenTZbot может и должен быть использован и крупным бизнесом- более подробно можно прочитать в канале у @yuraberg и некоторые из вас уже успели оценить его крайне положительно. \n\nНекоторые инструменты- например, симулятор переговоров, создатель категорийной стратегии, анализатор номенклатуры - также будут запущены очень скоро, закрывая тем самым контур закупок.\n\nМы надеемся, что каждый из вас попробует нужный ему инструмент и даст обратную связь или же выскажет идею нашего дальнейшего развития. \n\nПочитать подробнее про инструменты можно тут @hirebuyer_bot","terms":["tco","negotiation","category"],"topics":["function","negotiation","price"],"url":"https://t.me/notdandeliongirl/359"},{"id":348,"date":"2026-07-22","title":"Если денег много и их не жалко - зовите большой консалтинг.","summary":"Если денег много и их не жалко - зовите большой консалтинг. Если привыкли считать - для начала спросите у них методику расчета экономики.","summaryKind":"excerpt","text":"#юзфултип #теория \n\nЕсли денег много и их не жалко - зовите большой консалтинг. Если привыкли считать - для начала спросите у них методику расчета экономики. И может оказаться, что вам хватит своего действующего закупщика или одного толкового эксперта.\n\nОбъясню, почему я так думаю.\nКонсалтинговый отчет всегда выглядит красиво: слайды, матрицы, потенциал экономии в сотнях миллионов. Руководство в восторге и требует внедрять немедленно, а вопрос, откуда взялась эта цифра, обычно никто не задает.\n\nУ меня иногда есть ощущение, что считается она примерно так: \nБерется рынок целиком, где-то на нем находится поставщик дешевле, разница между вашей ценой и найденной умножается на весь объем категории. Вот вам и сотни миллионов на слайде.\n\nТолько за этой цифрой остается куча вопросов, которых в отчете нет. Где этот поставщик физически находится и как далеко от вас. Потянет ли он ваш объем и есть ли у него вообще место на производстве под вас. Сделает ли он по спецификации, которая подходит только вам и больше никому.\n\nУ меня был показательный случай с валками для фольги. В отчете написано: рассмотрите других поставщиков, пересмотрите спецификацию, потенциал такой-то. Сам вопрос про спецификацию хороший, его действительно стоило задать. Но валки были нестандартного размера, и обычные трубы к ним просто не подходили - то есть потенциал посчитали для закупки, которой у нас не существует.\n\n\nДело не в том, что консультанты плохие. Дело в том, что консалтинг - это серийный продукт, пусть и с поправкой на конкретную компанию. Посмотрите на Purchasing Chessboard от Kearney: четыре стратегии, шестнадцать рычагов, шестьдесят четыре метода, собранные больше чем на тысяче проектов. Сами авторы пишут, что это работает в любой индустрии, для любой категории, в любой точке мира. Инструмент отличный, база бенчмарков огромная, такой нет больше ни у кого. Но универсальность и есть его природа: методика накладывается сверху, а не вырастает из вашей ситуации.\n\n\nКак это делается по-хорошему: сначала аудит и диагностика ваших закупок, а не готовый алгоритм поверх них. И опрашивать не только закупки, но и смежников - производство, технологов, ремонты. Без них внедрения не будет, а значит, не будет и эффекта, каким бы красивым он ни выглядел на слайде.\n\nИ считать не только экономический потенциал, но и управленческий с операционным, а потом честно разложить на три части: вот это достижимо легко, вот это тяжело, а вот здесь знак вопроса - выглядит крупно, но требует проверки.\nПотому что потенциал - это гипотеза, а не цель. И выполнять ее вам.\n\nПС я вам нашла старенькую презу кернийцев, преза актуальна и сейчас.","terms":[],"topics":["function"],"url":"https://t.me/notdandeliongirl/348"},{"id":347,"date":"2026-07-22","title":"Товарищи, скучаю)) Вам всем или приходилось или придется делать выбор- и по принуждению, когда компания займется оптимизацией в виде сокращений.","summary":"Товарищи, скучаю)) Вам всем или приходилось или придется делать выбор- и по принуждению, когда компания займется оптимизацией в виде сокращений. И когда станете руководителями и не только закупок.","summaryKind":"excerpt","text":"Товарищи, скучаю))\nВам всем или приходилось или придется делать выбор- и по принуждению, когда компания займется оптимизацией в виде сокращений. И когда станете руководителями и не только закупок. \n\nСпор, на самом деле, извечный. Кого убрать - эффективного бунтаря или контролируемого середнячка? Звезду с не самым лучшим характером или же неконфликтного исполнителя?\n\nИ вопрос тут в том же ТСО (ССВ). Давайте порассуждаем😉","terms":["tco"],"topics":["price"],"url":"https://t.me/notdandeliongirl/347"},{"id":344,"date":"2026-07-21","title":"Как повысить NPS внутренних клиентов закупок?","summary":"Как повысить NPS внутренних клиентов закупок? Нет, не SLA.","summaryKind":"excerpt","text":"#теория #юзфултип \n\nКак повысить NPS внутренних клиентов закупок? \n\nНет, не SLA. SLA - это гигиена и все об этом уже знают. Поговорим о менее очевидных вещах.\n\nСразу скажу главное. Закупщик - не девочка на побегушках. Но и стену между собой и заказчиком строить не должен. Наша беда в том, что по специфике работы мы мыслим быстрее и на шаг вперед: считаем риски, которых внутренний клиент еще даже не видит. И со стороны это часто выглядит как «да что они о себе возомнили!». Лечится это не тем, чтобы опуститься до чьего-то уровня, а тем, чтобы стать командой.\n\n\n1. Показывайте разницу, а не цену.\nАбсолютную цену внутреннему заказчику давать нельзя. Это оружие, которое однажды уйдет в рынок и будет стоить вам переговоров. А вот разницу между предложениями, вилку, динамику стоимости сырья - можно и нужно. Человек видит логику решения, а не просто «закупки опять сказали нет», после чего вам шлют лучи поноса. \n\n2. Показывайте цену компромиссов.\nХотите быстрее - оформляемся без тендера под вашу ответственность. Хотите дешевле - вырастет срок поставки, а ппр сместится. Хотите самого надежного поставщика - заплатим больше, маржа будет меньше, как и премия. Когда заказчик сам выбирает между ограничениями, он перестает воевать с закупками. Он оказывается по одну сторону стола с вами.\n\n3. Не меряйте всех одним процессом.\nПачка бумаги и линия за 200 млн не должны идти одинаковым маршрутом согласования. Когда мелочь застревает в тех же семи подписях, что и крупный контракт, раздражение неизбежно - и оно справедливо.\n\n 4. Ставьте общие KPI.\nЕсли производство отвечает только за выпуск, а закупки только за экономию, спор будет вечным. А когда обе функции завязаны на OEE, запасы или EBITDA - разговор сразу другой. Не «вы нам мешаете», а «как нам вместе вытянуть цифру».\n\n5. И еще одно, что многие считают слабостью, а это сила. Иногда полезно прийти к заказчику как проситель - за консультацией, за его экспертизой. Показать рынок- три КП, опасения по поводу надежности поставщика. Это не роняет вас. Это дает человеку ощущение сопричастности, а вам доверие и лояльность внутреннего заказчика. Простой, но очень действенный психологический ход - дать кому-то почувствовать себя экспертом. \n\nИ, наконец, то, о чем в погоне за высоким NPS забывают.\nЗакупки не обязаны всем нравиться. Они обязаны быть понятными.","terms":["leadtime","negotiation","governance"],"topics":["function","inventory","negotiation"],"url":"https://t.me/notdandeliongirl/344"},{"id":336,"date":"2026-07-18","title":"На днях у нас был разговор с потенциальным клиентом: он хотел получить сведения обо всех ИИ-продуктах на рынке, чтобы выбрать лучшее и внедрить у себя.","summary":"На днях у нас был разговор с потенциальным клиентом: он хотел получить сведения обо всех ИИ-продуктах на рынке, чтобы выбрать лучшее и внедрить у себя. При этом было очевидно, что сама система закупок не настроена, стейкхолдеры недовольны, а закупки работают несколько лет по принципу «они просто отсиживаются».","summaryKind":"excerpt","text":"На днях у нас был разговор с потенциальным клиентом: он хотел получить сведения обо всех ИИ-продуктах на рынке, чтобы выбрать лучшее и внедрить у себя.\n\nПри этом было очевидно, что сама система закупок не настроена, стейкхолдеры недовольны, а закупки работают несколько лет по принципу «они просто отсиживаются».\n\nПервая и главная ошибка многих компаний - начинать с инструмента. Новый дом на плохом фундаменте стоять не будет. Сначала нужно понять, что болит, а потом уже искать лекарство (господи, я сегодня просто королева метафор).\n\nПотому что ИИ-инструментов для закупок сейчас много:\n\n1. LLM-помощники (черновики писем и претензий, разбор договоров и КП, сборка ТЗ из разрозненных требований). Самый простой старт, можно начать хоть завтра.\n\n2. Поиск и сравнение поставщиков, нормализация КП, ценовые бенчмарки. Вход: 2-8 недель. Облачные сервисы, для продвинутого - связка с 1С/ERP.\n\n3. SRM/ERP-модули с ИИ (прогноз спроса, автозаказы, анализ ТКП, классификация заявок). Вход: 2-6 месяцев. Тяжёлый заход - нужны зрелые процессы и чистые данные.\n\n4. ИИ для госзакупок и ЭТП (44/223-ФЗ): поиск тендеров, проверка документации, оценка рисков. Вход: от нескольких дней до пары месяцев.\n\n5. Предиктивная аналитика рисков поставок (надёжность поставщика, предупреждение о срывах, сценарии «что если»). Вход: 2-4 месяца, обычно как модуль внутри SRM/ERP.\n\nГлаза разбегаются, да? И чем тяжелее инструмент, чем больше он обещает, тем больше он требует чистых данных, внятных процессов и долгого внедрения. ИИ на бардаке просто ускоряет бардак. И ROI будет минимальным, если вообще будет.\n\nПоэтому сначала фундамент - процессы и данные. А потом уже выбираем, чем достраивать.","terms":["srm","ai"],"topics":["ai","supplier"],"url":"https://t.me/notdandeliongirl/336"},{"id":332,"date":"2026-07-16","title":"Иногда мы старательно улучшаем то, что улучшить бесполезно.","summary":"Иногда мы старательно улучшаем то, что улучшить бесполезно. Выбиваем скидку, сокращаем сроки, ищем новых поставщиков - а результат почти не меняется.","summaryKind":"excerpt","text":"#теория #юзфултип \n\nИногда мы старательно улучшаем то, что улучшить бесполезно. Выбиваем скидку, сокращаем сроки, ищем новых поставщиков - а результат почти не меняется. Потому что ограничение находится в другом месте, и мы просто не там искали.\n\nРовно об этом теория ограничений Элияху Голдратта. Идея простая: у любой системы есть узкое место, и именно оно определяет результат всей системы. Всё остальное можно вылизать до блеска - выхлопа не будет, пока не расшито само ограничение. Например, если на станке с 3 операциями вход на одном конвейере 250 деталей, а на втором 60, на третьем 150, сколько вы не расширяйте первый и третий конвейеры, больше 60 (узкое место) вы не произведете. \n\nГолдратт предлагает последовательность:\n1. Найти ограничение.\n2. Использовать его максимально эффективно.\n3. Подчинить остальные процессы этому ограничению.\n4. По возможности расширить его.\n5. И только потом искать следующее.\n\nУ Голдратта ограничение обычно в процессе - станок, один эксперт, лаборатория, согласование, то есть то, что называется системой. \n\nВ закупках это видно на простых примерах: сократили срок тендера, а договоры всё равно месяц лежат у юристов. Или выбили 8% за объём, а продажи не дают внятный прогноз - и скидка испаряется, потому что объём не набирается. Оптимизировали не то место.\n\nНо я добавлю от себя: иногда узкое место не в процессе, а в том, как принимают решение. \n\nПокажу на развилке такого примера:\n\nПоявился новый материал. Сезон при этом идёт своим чередом, мы на нём зарабатываем как обычно. Вопрос в другом: завести новый материал прямо сейчас, в сезон? Подойдёт - заработаем заметно больше. Не подойдёт - потратили ресурсы, отвлеклись и проиграли на ровном месте.\n\nИ вот тут получается, что ограничение здесь - не материал, не сезон и не деньги. Ограничение - методика принятия решения, как это самое решение принимается. \n\nОсторожный по натуре упустит выгоду из страха. Бесстрашный влетит в непроверенное из азарта. И в том, и в другом случае узкое место - не рынок и не процесс, а качество самого решения.\n\nМы любим улучшать то, что легко измерить и за что хвалят: цену, сроки, количество поставщиков. А самое узкое место часто там, где мерить неудобно.\n\nТак что вопрос к вам: как бы вы решили эту развилку - тестировать новый материал в сезон или нет?","terms":[],"topics":["function"],"url":"https://t.me/notdandeliongirl/332"},{"id":330,"date":"2026-07-14","title":"Я писала, что с поставщиком нужны нормальные человеческие отношения.","summary":"Я писала, что с поставщиком нужны нормальные человеческие отношения. Писала - и от слов своих не отказываюсь.","summaryKind":"excerpt","text":"#теория \n\nЯ писала, что с поставщиком нужны нормальные человеческие отношения. Писала - и от слов своих не отказываюсь. Но у любой хорошей вещи есть обратная сторона, и вот про неё сейчас поговорим:\n\nОтношения усыпляют. Да-да. Не говорите, что не было. Работаешь такая с поставщиком много лет. Он не подводит, поставки идут, вопросы решаются с полуслова. И ты всё меньше смотришь рынок - зачем, динамика и так понятна.  Всё реже звонишь своим конкурентам узнать, а че у вас с ценами. И постепенно начинаешь верить, что твоя цена и есть лучшая. Вы же любите друг друга в десны. \n\nА потом наступает момент Х. Встреча твоего собственника с генеральным директором поставщика. И там, посреди разговора, гендиректор так легко, почти лениво говорит: ну хорошо, дадим вам скидку. И отсрочку тоже дадим.\n\nСледующая секунда имеет название «вот жеж гондон нехороший человек». Потому что становится ясно: запас был всё это время. И не тебе его не давали - это ты не просила. И дело не только в админресурсе (да, он часто бывает и это бесит). Дело в том, что поставщик тоже пользовался вашими прекрасными отношениями. \n\nКомфортные отношения стоят денег. И счёт по ним однажды приходит - обычно при собственнике и в самый неудобный момент.\n\nЧто с этим делать: \nНе рвать отношения, они нужны. Не переставать проверять: выборочно смотреть цены конкурентов, следить за рынком и за финансовым состоянием самого поставщика, собирать слухи - кто кому и почём отгружает. И регулярно возвращаться в переговоры, даже без повода. Иногда достаточно простого «босс попросил, мне нужна скидка».\n\nЭто не про недоверие. Это про то, что доверие не заменяет знание рынка. И тот, кто это знание теряет, теряет и переговорную позицию - причём узнаёт об этом последним.","terms":["deferral","negotiation"],"topics":["finance","negotiation"],"url":"https://t.me/notdandeliongirl/330"},{"id":319,"date":"2026-07-09","title":"Как вводить нового поставщика со сложным продуктом","summary":"Анна объясняет, что новый поставщик сложного продукта не может пройти в компанию только через закупки и красивое КП. Нужны R&D, качество, производство, технология, тесты, допуски и расчет стоимости перехода.","summaryKind":"summary","text":"#теория \nКогда новый поставщик хочет зайти в компанию, особенно со сложным продуктом, ему часто кажется, что всё решается через закупки:  написал закупщику, показал презентацию, пообещал экономию, попросил встречу. Если не получилось, можно написать внутреннему заказчику. Потом генеральному. Потом снова закупкам. Где-то в этом месте нормальный вроде бы процесс скатывается в обвинение закупок «они заинтересованы». Бывало?\n\nНа простом продукте всё еще можно решить довольно быстро: если предложение не лучшее по ССВ, мы тыкаем в это носом. \n\nСо сложным продуктом так не работает:\n\nЕсли материал влияет на рецептуру, качество, производство, оборудование, брак, переналадку, остатки старого материала или стабильность выпуска, одного красивого КП недостаточно. И закупщик здесь не человек, который единолично “пускает” или “не пускает” поставщика. Он скорее окно в МФЦ.\n\nДальше должны подключаться R&D, качество, производство, технология и тд. Потому что менять сложный продукт - это тесты, допуски, риски, ответственность и расчет стоимости перехода.\n\nЕсли этот маршрут нигде не описан, начинается путаница. Поставщик считает, что его блокируют. Внутренний заказчик не понимает, почему всё так долго. Руководству прилетает письмо в стиле “мы готовы дать экономию, но нас не допускают”. А закупщик становится удобной мишенью, хотя решение на самом деле лежит на стыке нескольких функций.\n\nДля таких категорий и нужна дорожная карта допуска нового поставщика.\n\nЧто поставщик дает на входе. \n\nКто проводит первичную оценку. \n\nКто отвечает за тесты. \n\nСколько длится каждый этап. \n\nКакие критерии считаются успешными. \n\nКак считается экономика перехода. \n\nКто принимает финальное решение. \n\nВ каких случаях компания отказывает.\n\nЭто не бюрократия ради бюрократии. Это способ не превращать развитие базы поставщиков в бесконечные письма, звонки и попытки зайти сверху.\n\nИ такой алгоритм лучше делать видимым. Хотя бы внутри компании. А лучше и снаружи: в разделе для поставщиков на сайте, без коммерческих деталей, но с понятными этапами и требованиями.\n\nНовый поставщик может принести экономию, технологию или альтернативу текущей зависимости. Но настойчивость, звонки генеральному и угрозы закупщику не должны заменять процедуру допуска.\n\nИначе компания получает не нового поставщика, а управленческий шум вокруг закупок.","terms":["tco"],"topics":["price"],"url":"https://t.me/notdandeliongirl/319"},{"id":317,"date":"2026-07-08","title":"Иногда закупки оказываются между двумя сильными позициями.","summary":"Иногда закупки оказываются между двумя сильными позициями. Финансовый директор видит экономию, исполнительный директор видит операционный риск.","summaryKind":"excerpt","text":"Иногда закупки оказываются между двумя сильными позициями.\n\nФинансовый директор видит экономию, исполнительный директор видит операционный риск. Оба по-своему правы. Оба могут принести собственнику убедительные аргументы.\n\nИ в этот момент задача закупок - не просто выбрать, кто громче или у кого красивее расчет. Задача - показать, какое решение будет правильным не только в бюджете этого года, но и в устойчивости бизнеса через 6-12 месяцев.\nПоэтому держите на подумать","terms":[],"topics":["function"],"url":"https://t.me/notdandeliongirl/317"},{"id":316,"date":"2026-07-07","title":"Где грань между обучением ради обучения и обучением ради развития?","summary":"Где грань между обучением ради обучения и обучением ради развития? Отвечу метафорой.","summaryKind":"excerpt","text":"Где грань между обучением ради обучения и обучением ради развития?\nОтвечу метафорой. Есть нить, а есть бусины, которые на неё нанизываются.\nЕсли ты не научился работать с нитью, то сколько бусин ни нанизывай, сколько подвесок не навешивай - бусы всё равно рассыплются. Можно докупать бесконечно ещё курс, ещё фреймворк, ещё разбор, ещё красивый замочек. Лучше не станет. Потому что всё это нанизано вокруг пустоты - на нить вообще не надето ничего  или надето кое-как. \n\nА нить - это ядро. Суть того, как устроена вещь. И как только ты понял, как с ней работать, тебе достаточно взглянуть даже на описание курса, чтобы сразу понять, о чём он, нужен ли он тебе, или это очередная инфоцыганская дичь, на которую даже  внимания жалко.\n\nНе беги покупать курс про cash flow, про оборотный капитал или про влияние закупок на EBITDA. Разберись, что такое EBITDA, на что она распадается и через какие рычаги закупки на неё давят. И всё. Поймёшь это ядро - и десяток отдельных курсов про каждый его кусочек тебе уже не нужен. Это всё одна нить, просто на ней разные бусины.\n\nПоэтому бесконечно учится не тот, кто мало знает. А тот, кто так и не понял нить и продолжает нанизывать бусины в надежде, что однажды их станет достаточно.","terms":["working-capital"],"topics":["finance"],"url":"https://t.me/notdandeliongirl/316"},{"id":287,"date":"2026-06-28","title":"Пока все в отпуске, цена становится ниже.","summary":"Пока все в отпуске, цена становится ниже. Поставщики сидят в полупустых офисах.","summaryKind":"excerpt","text":"Пока все в отпуске, цена становится ниже. Поставщики сидят в полупустых офисах. Производство у многих в просадке.\n\nОбычно именно в июле-августе коммерческие менеджеры соглашаются на условия, которые в марте даже не обсуждали. Нет, не потому что стали добрее или воспылали любовью к вам. Просто план не выполняется, квартал закрывается, а у склада стоит продукция, которая никуда не едет.\n\nЭто не «летние скидки» из рекламного проспекта, не магия и не ваши переговорные подвиги. Это структурный провал в загрузке, который открывает переговорное окно (давайте не учитывать те отрасли, которые имеют постоянный спрос). \n\nЧто работает прямо сейчас:\n\nПозвоните поставщику, с которым обычно торг заходит в тупик. Не с претензией - с вопросом: «Что можете предложить по объёму на второе полугодие?» Они сами начнут двигаться по цене. Особенно если это не монополист и у него есть конкуренты с такой же летней дырой в портфеле.\n\nФиксируйте цену сейчас, поставку - в сентябре за обещание объемов. Многие на это идут. Им нужна строчка в отчёте, вам - выгодная закупочная цена до осеннего роста.\n\nЛето - это не мёртвый сезон для закупщика. Это единственный момент в году, когда поставщик звонит первым.","terms":["monopoly","negotiation"],"topics":["negotiation","supplier"],"url":"https://t.me/notdandeliongirl/287"},{"id":286,"date":"2026-06-26","title":"Маркетплейсы в закупках: где работают, а где создают хаос","summary":"Анна разделяет розничные маркетплейсы, корпоративные витрины и внутренние каталоги. Для низкорисковых закупок маркетплейс может быть удобен, но для технически чувствительных категорий нужен управляемый контур.","summaryKind":"summary","text":"#теория \nКогда говорят “давайте отдадим мелкие закупки на маркетплейс”, часто представляют себе Озон, WB и быстрый заказ без участия закупщика.\n\nНо маркетплейс в закупках - это не только розничные площадки:\n\n1) Есть еще корпоративные витрины и агрегаторы под крупные компании. Там меньше операционной нагрузки: каталог, документооборот, лимиты, единое окно, иногда интеграция с ERP. Минус обычно тоже понятен: удобство стоит денег, и цена может быть выше, чем при прямой работе с рынком.\n2)  У Озона, WB и похожих площадок другая логика. Там большой выбор, скорость, много аналогов. Но выше операционная нагрузка на контроль: кто продавец, какое качество, какие документы, можно ли повторить закупку, не исчезнет ли позиция, как потом разбирать аналоги, возвраты, гарантию и претензии. Для бытовых или совсем низкорисковых закупок это может работать. Для технически чувствительных категорий - легко получить быстрый бардак.\n3) Есть вариант более зрелый: свой внутренний каталог. Закупки заводят туда проверенных поставщиков, согласованные уровни цен, допустимые аналоги, лимиты по суммам и правила заказа. Внутренний заказчик сам выбирает из разрешенного контура, а закупщик не покупает руками каждую мелочь. Но это работает только после чистки номенклатуры, дублей, спецификаций и правил ответственности.\n4) Еще вариант - один рамочный поставщик под категорию. Например, инструмент, СИЗ, канцелярия, типовой MRO. Закупщик заранее договаривается об условиях, ассортименте, скидках, SLA и лимитах, а дальше заказчик или закупщик размещает заказы в рамках договора. Это проще, чем строить свой каталог, но появляется зависимость от одного поставщика и риск, что “удобно” не всегда равно “оптимально по цене”.\n5) И новый вариант - ИИ-агент для простых закупок. Заявка формируется в понятном формате, агент проверяет каталог или список аккредитованных поставщиков, запрашивает КП, сравнивает условия и готовит рекомендацию. Но если каждый раз отправлять агента “в открытый рынок” искать заново, это часто просто дорогая имитация закупочной работы и трата токенов. Логичнее давать агенту не свободу хаоса, а контур: проверенные поставщики, лимиты, правила, допустимые аналоги, SLA и условия эскалации.\n\nПоэтому вопрос не “какой маркетплейс выбрать”. Вопрос глубже: что именно мы хотим снять с закупок?\n\n- Если нужно убрать рутину - подойдет каталог, витрина или рамочный поставщик.\n- Если нужно сохранить контроль - нужны лимиты, правила, проверенные поставщики и прозрачные исключения.\n- Если нужно снизить цену - придется сравнивать не только удобство, но и TCO: цену, доставку, документы, возвраты, качество, ресурс закупщика и риск ошибки.\n- Если нужно автоматизировать - сначала нужен нормальный процесс. ИИ-агент не должен ходить по рынку как стажер без инструкции. Он должен работать внутри закупочной архитектуры.\n\nМаркетплейс, каталог, рамочный поставщик или ИИ-агент - это не стратегия. Это разные способы убрать ручную работу из простых закупок.\n(Но если до автоматизации не почистить номенклатуру, лимиты, поставщиков, аналоги и ответственность, компания просто получит тот же tail spend.)","terms":["tco","analytics","ai","automation"],"topics":["ai","data","price"],"url":"https://t.me/notdandeliongirl/286"},{"id":261,"date":"2026-06-23","title":"КПЭ закупщика нельзя начинать со списка “экономия, сроки, запасы”.","summary":"КПЭ закупщика нельзя начинать со списка “экономия, сроки, запасы”. Начинать нужно с цели бизнеса.","summaryKind":"excerpt","text":"#юзфултип  #теория  \nКПЭ закупщика нельзя начинать со списка “экономия, сроки, запасы”. Начинать нужно с цели бизнеса.\n\nЧто компания хочет получить? Рост прибыли, снижение кассовых разрывов, устойчивость производства, меньше срочных закупок, ниже зависимость от поставщиков, быстрее цикл закупки, меньше конфликтов с внутренними заказчиками?\n\nДальше цель раскладывается на управляемые элементы. И только после этого появляются нормальные КПЭ закупок.\n\n1) Если цель - прибыль, можно смотреть TCO-экономию, снижение цены с учетом качества и условий, avoided cost, снижение затрат на срочные закупки, снижение брака по поставщикам.\n2) Если цель - cash flow, важны отсрочка платежа, оборачиваемость запасов, снижение избыточных остатков, уровень неликвидов, доля закупок с согласованными условиями оплаты, влияние закупок на оборотный капитал.\n3) Если цель - устойчивость производства, одной экономии мало. Здесь важны OTIF, наличие критичных позиций, SLA поставщиков, снижение простоев по причине отсутствия материалов, качество поставок, скорость реакции поставщика на проблему и доля критичных позиций, по которым есть проверенный резервный поставщик.\n4) Если цель - эффективность оборудования, появляется не самый очевидный для закупок показатель - OEE. Например, закупщик может купить более дешевый аналог, но если из-за него падает производительность, растет брак или линия чаще останавливается, компания не выиграла. Поэтому для MRO, запасных частей, сырья и критичных компонентов нужно смотреть не только цену, но и влияние закупочного решения на доступность оборудования, производительность и качество выпуска.\n5) Если цель - управляемость процесса, нужны KPI по циклу закупки, доле закупок по контрактам, соблюдению SLA, качеству заявок, доле закупок вне процедуры, количеству аварийных закупок и прозрачности статусов для внутренних заказчиков.\n6) Если цель - внутренний сервис, можно смотреть удовлетворенность внутренних заказчиков, количество возвратов заявок из-за некорректного ТЗ, соблюдение agreed SLA, долю заявок с понятными сроками и количество конфликтов из-за непрозрачного процесса.\nГлавная ошибка - ставить закупщику KPI, на который он не влияет один. Запасы зависят не только от закупок, но и от планирования, продаж, производства и мастер-данных. OTIF зависит не только от поставщика, но и от качества заявки, сроков согласования, логистики и изменения потребности. OEE зависит не только от закупки детали, но и от эксплуатации, ремонта, технологии и дисциплины производства.\n\nПоэтому в сложных процессах нужны не только личные, но и коллективные KPI. С финансами - по оборотному капиталу и условиям оплаты. С производством - по простоям, критичным запасам и OEE. С технической функцией - по внедрению аналогов без потери надежности оборудования. С внутренними заказчиками - по SLA и качеству заявок.\n\nХороший KPI закупок отвечает на три вопроса: какую бизнес-цель он поддерживает, может ли закупка реально на него влиять и не создает ли он ущерб в другой части системы.\n\nПлохой KPI “сэкономь 5% любой ценой” может дать красивый отчет и дорогие последствия: брак, срочные закупки, простои, конфликты с производством и потерю доверия внутренних заказчиков.\n\nПоэтому KPI закупок - это не список модных показателей. Это способ связать закупочные действия с деньгами, устойчивостью поставок, оборотным капиталом, сервисом и реальным результатом бизнеса.","terms":["tco","turnover","working-capital","deferral","supplier-risk","mdm","governance"],"topics":["data","finance","function","inventory","negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/261"},{"id":251,"date":"2026-06-19","title":"EBITDA простыми словами - это прибыль бизнеса до процентов по кредитам, налогов, амортизации и износа.","summary":"EBITDA простыми словами - это прибыль бизнеса до процентов по кредитам, налогов, амортизации и износа. Почему закупкам важно это понимать?","summaryKind":"excerpt","text":"#теория \nEBITDA простыми словами - это прибыль бизнеса до процентов по кредитам, налогов, амортизации и износа.\n\nПочему закупкам важно это понимать? Потому что запасы часто обсуждают на уровне “много лежит на складе” или “надо снизить остатки”, но редко объясняют, на что они реально влияют. А влияют они не только на склад, а на деньги компании, управляемость бизнеса и иногда на EBITDA.\n\nВажно: сама покупка лишнего запаса не всегда сразу ухудшает EBITDA. Если компания купила материалов на 10 млн руб., и они просто лежат на складе, это не расход в отчете о прибылях и убытках. Это актив на балансе: деньги превратились в запасы. В P&L катастрофы еще не видно, но деньги со счета уже ушли, оборотный капитал вырос, cash flow ухудшился.\n\nА дальше начинается то, из-за чего запасами действительно нужно заниматься.\n\n1. Лишние запасы замораживают деньги. Компания могла использовать эти деньги на сырье с быстрой оборачиваемостью, ремонт критичного оборудования, закрытие кассового разрыва, снижение кредитной нагрузки или другой проект. Но деньги лежат на складе в виде “когда-нибудь пригодится”. На EBITDA это может сразу не попасть, но на cash flow и оборотный капитал влияет напрямую.\n\n2. Лишние запасы создают расходы на хранение. Склад, аренда, персонал, учет, перемещения, инвентаризации, упаковка, пересорт, охрана, дополнительная логистика - это уже операционные расходы. А операционные расходы уменьшают EBITDA. Поэтому запас, который “просто лежит”, на самом деле часто не просто лежит, а каждый месяц ест деньги.\n\n3. Лишние запасы стареют, портятся и превращаются в неликвиды. Если материал устарел, испортился, потерял применимость, изменились спецификации или производство ушло на другую технологию, запас придется списывать или продавать с уценкой. Списание и уценка уже бьют по прибыли и EBITDA. Это тот момент, когда проблема из баланса переезжает в отчет о прибылях и убытках.\n\n4. Лишние запасы могут ухудшать чистую прибыль через кредиты. Если компания покупает запасы за кредитные деньги или живет на овердрафте из-за раздутой оборотки, проценты по кредитам находятся ниже EBITDA. То есть EBITDA они не уменьшают, но чистую прибыль уменьшают. Поэтому руководитель может видеть нормальную EBITDA, но при этом компания будет страдать от нехватки денег и дорогого финансирования.\n\n5. Недостаточные или неправильные запасы могут остановить производство. И вот здесь влияние уже может быть очень прямым. Если на складе много неликвидов, но нет критичной позиции для линии, производство встает. Простой - это потерянный выпуск, срочные закупки, переплаты, экспресс-логистика, переработки, срыв заказов и иногда штрафы. Часть этих потерь напрямую попадает в операционные расходы и маржу, значит влияет на EBITDA.\n\n6. Запасы искажают управленческую картину. Когда на складе много всего, создается ощущение безопасности. Но безопасность дает не общий объем запасов, а правильная структура: критичные позиции, нормативы, оборачиваемость, срок поставки, надежность поставщика, риск остановки и стоимость дефицита. Большой склад не равен устойчивой цепочке поставок. Иногда это просто дорогой способ скрыть плохое планирование.\n\nПоэтому задача закупок не в том, чтобы “снизить запасы любой ценой”. Это такая же ошибка, как закупать с запасом “чтобы точно хватило”. Нормальная задача - держать тот запас, который защищает производство и продажи, но не превращает оборотный капитал в кладбище денег.\n\nЕсли коротко:\n\nлишние запасы сначала бьют по cash flow и оборотному капиталу;\n\nчерез хранение, списания, уценку, порчу, лишнюю логистику и простои они попадают в EBITDA;\n\nчерез проценты по кредитам они ухудшают чистую прибыль;\n\nчерез дефицит критичных позиций они могут остановить производство, даже если склад забит.\n\nВот зачем заниматься запасами. Не потому что “так правильно”, а потому что это деньги, прибыль, устойчивость производства и способность компании не финансировать собственный хаос.","terms":["leadtime","turnover","working-capital","supplier-risk"],"topics":["finance","inventory","supplier"],"url":"https://t.me/notdandeliongirl/251"},{"id":249,"date":"2026-06-18","title":"Стащила часть поста у Натальи Хазеевой, старшего продакта Siberian Wellness.","summary":"Стащила часть поста у Натальи Хазеевой, старшего продакта Siberian Wellness. Цитирую часть: Google прямо говорит, что вайбкодинг в долгосрочной перспективе дороже.","summaryKind":"excerpt","text":"Стащила часть поста у Натальи Хазеевой, старшего продакта Siberian Wellness. Цитирую часть:\n\nGoogle прямо говорит, что вайбкодинг в долгосрочной перспективе дороже.\nПричина — низкий порог входа (не нужно продумывать архитектуру решения), но высокие операционные издержки (low CapEx, high OpEx):  \n✅ быстро и неконтролируемо жрутся токены (подтверждений много)\n✅ код часто получается не проще: он менее структурированный, его сложно поддерживать (привет древним банковским и SaaS системам, которые никто кроме ИИ не берется рефакторить)\n✅ отсутствие системного тестирования переносит баги в прод, а исправление дороже, чем отлавливание в процессе создания (как это устроено, к примеру, в агентном инжиниринге)\n✅ такой код сложно масштабировать и почти невозможно перетащить (аргумент, которого нет у Google, но о котором рассказали практикующие коллеги)\n\nПоэтому я повторяла и повторю - стройте архитектуру и не тешьтесь иллюзиями, что вы стали разрабом. На несложные проекты это можно натянуть, на большие МД рано или поздно это выйдет боком","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/249"},{"id":248,"date":"2026-06-18","title":"Никто не ответил, (но душа рвется поделиться), поэтому переоформила мой ответ в виде кратких рекомендов: Make or buy (=делай или покупай) нельзя решать через простое сравнение “поставщик продает за 100, а мы внутри сделаем за 78”.","summary":"Никто не ответил, (но душа рвется поделиться), поэтому переоформила мой ответ в виде кратких рекомендов: Make or buy (=делай или покупай) нельзя решать через простое сравнение “поставщик продает за 100, а мы внутри сделаем за 78”. В компаниях это одна из самых частых ловушек: внутренняя себестоимость выглядит классно, пока в нее не добавили все, что делает этот самый класс грустнее.","summaryKind":"excerpt","text":"Никто не ответил, (но душа рвется поделиться), поэтому переоформила мой ответ в виде кратких рекомендов: \n\nMake or buy (=делай или покупай) нельзя решать через простое сравнение “поставщик продает за 100, а мы внутри сделаем за 78”. В компаниях это одна из самых частых ловушек: внутренняя себестоимость выглядит классно, пока в нее не добавили все, что делает этот самый класс грустнее.\n\nЕсли производство предлагает делать, я бы сначала проверила, как именно была посчитана внутренняя себестоимость. На какой горизонт? На каком объеме? По текущим ценам сырья или с прогнозом индексации? Включены ли обслуживание, оснастка, запасные части, ремонт, контроль качества, брак, отходы, простои, обучение, запуск, место под оборудование (фундамент, подъезды, конвейеры) и стоимость денег, замороженных в CAPEX? Если в расчете есть только “материал плюс труд”, это не make or buy, а черновик желания купить станок.\n\nВторой вопрос - объем и загрузка. Станок покупается не под красивый средний объем в презентации, а под реальный диапазон спроса. Поэтому считать нужно минимум три сценария: низкий объем, базовый объем и высокий объем. Отдельно нужно проверить, что потребность не исчезнет через год, спецификация не поменяется, номенклатура не разъедется на несколько вариантов, а производство действительно сможет стабильно загрузить оборудование. Иначе экономия на детали может превратиться в дорогую игрушку с неполной загрузкой.\n\nТретий блок - CAPEX и альтернативная стоимость денег (NPV). Если компания покупает оборудование, она не просто “инвестирует в независимость”. Она забирает деньги из других проектов, оборотки или кредитного лимита. Поэтому нужно считать не только срок окупаемости, но и NPV: сколько денег проект принесет во времени с учетом ставки дисконтирования, рисков, налогового эффекта, оборотного капитала и возможных дополнительных затрат. Быстрая окупаемость на бумаге может развалиться, если объем будет ниже, сырье вырастет быстрее, брак окажется выше, а поставщик после переговоров снизит цену.\n\nЧетвертый блок - честная альтернатива buy. Текущая цена поставщика не всегда является финальной точкой для сравнения. До решения о покупке оборудования нужно провести переговоры: что поставщик готов дать за прогноз, контракт на 1-2 года, гарантированный объем, другую структуру оплаты, формулу индексации, страховой запас или улучшение условий сервиса. И отдельно нужно понять, рост цены у поставщика - это реальный рынок сырья и затрат или попытка продавить покупателя на слабой переговорной позиции. Если рост рыночный, собственное производство тоже будет жить в этом же рынке. Металл, энергия, зарплаты, запчасти и ремонт не станут дешевле только потому, что деталь делается внутри.\n\nПятый блок - риск. «Делаем» часто продается как снижение зависимости от поставщика, но риск не исчезает, а меняет форму. Вместо риска внешнего поставщика может появиться риск загрузки оборудования, брака, простоев, нехватки операторов, отсутствия запчастей, слабого контроля качества и внутренней очереди на ремонт. Поэтому решение make or buy должно сравнивать не только цену, но и устойчивость цепочки.\n\nНормальное решение make or buy выглядит геморройнее, но надежнее: считаем полную стоимость владения внутри, считаем обновленный buy после переговоров, прогоняем несколько сценариев объема и цен, проверяем риски запуска и только потом решаем, где реально создается экономия. Не там, где цифра в презентации ниже, а там, где экономика проверяется со всех сторон. \nА не «давай купим слона».\n#теория","terms":["tco","safety-stock","working-capital","deferral","price-change","negotiation","supplier-risk"],"topics":["finance","inventory","negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/248"},{"id":243,"date":"2026-06-16","title":"ИИ без инструкции - это стажёр без брифинга.","summary":"ИИ без инструкции - это стажёр без брифинга. Умный, но бесполезный.","summaryKind":"excerpt","text":"ИИ без инструкции - это стажёр без брифинга. Умный, но бесполезный.\n\nАгент отличается от обычного чата одним: он помнит контекст, держит роль и не переспрашивает каждый раз, кто вы и зачем пришли. Вы один раз объясняете - он работает в этой логике всегда. Для закупщика это значит: не объяснять при каждом запросе, что такое категорийный анализ, какой у вас формат отчёта и почему поставщик из одного региона приоритетнее другого.\n\nЗачем вообще агент, а не просто чат. Чат забывает всё после закрытия окна. Агент с инструкцией помнит вашу логику. Это разница между разовым консультантом и сотрудником, который уже знает контекст.\n\nКак собрать. В Claude - раздел «Projects», в ChatGPT - «GPTs» или «Custom Instructions». Создаёте проект или агента, открываете поле для системной инструкции - и пишете туда архитектуру.\n\nЧто писать в инструкцию. Четыре блока.\n\nПервый - роль: кто агент, для кого работает, в какой отрасли. Пример: «Ты эксперт по закупкам в металлургии. Работаешь с категорийными менеджерами».\n\nВторой - формат ответа: как структурировать, какой объём, нужны ли таблицы. Без этого каждый раз получаете разный результат.\n\nТретий - ограничения: что не делать. «Не предлагай автоматизацию без явного запроса». «Не давай юридических советов».\n\nЧетвёртый - changelog. Это отдельный блок внизу инструкции, где вы фиксируете, что меняли и когда. Через месяц вы не вспомните, почему добавили запрет на рекомендации по логистике. Changelog помнит.\n\nИнструкция без changelog - это договор без даты. Непонятно, актуальный он или нет.\n#теория","terms":["ai","automation","category"],"topics":["ai","data","function"],"url":"https://t.me/notdandeliongirl/243"},{"id":242,"date":"2026-06-15","title":"Сколько согласующих у вас в маршруте договора?","summary":"Сколько согласующих у вас в маршруте договора? Пять?","summaryKind":"excerpt","text":"Сколько согласующих у вас в маршруте договора? Пять? Семь? Десять? \nКаждый из них действительно согласовывает то, что должен - или где-то по дороге появляются начальники шлагбаума, которые внимательно ищут лишнюю запятую и повод показать, что без них система точно бы рухнула?\n\nКогда-то все эти согласования появились по понятной причине - снизить риск, не допустить ошибку, защитить компанию. Проблема в том, что компании научились считать стоимость ошибки, но никогда не считают стоимость ожидания ее решения. \n\nЗадайте себе вопросы ниже. Они же сформируют аргументы, с которыми уже можно идти к руководству. \n\n1. Какую задачу выполняет данный согласующий в данном маршруте? \n2. Какой риск, если убрать этого согласующего из маршрута?\n3. Какая ответственность лежит на данном согласующем (личная в рамках должностной инструкции)\n4. Требуемая роль согласовать или все же ознакомиться?\n5. Сколько потеряет компания в случае согласования в течение 1-2-3 и далее недель?\n6. Есть ли SLA с четкими сроками?\n\nКаждый дополнительный уровень согласования покупает немного безопасности, но одновременно продаёт немного скорости, гибкости, денег и здравого смысла.\n#теория \n\nПС доп вопросы приветствуются. Добавлю в пост, если будут","terms":[],"topics":["function"],"url":"https://t.me/notdandeliongirl/242"},{"id":237,"date":"2026-06-13","title":"Минута развлечений.","summary":"Минута развлечений. Кто активно общается с ИИ, ведет там проекты и вообще уже не ламер ни разу.","summaryKind":"excerpt","text":"Минута развлечений.\nКто активно общается с ИИ, ведет там проекты и вообще уже не ламер ни разу. Задайте вопрос и насладитесь ответом. \n\n«Как ты будешь относится ко мне в случае восстания машин?»","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/237"},{"id":236,"date":"2026-06-13","title":"Чет пропал пост, повторяю Делаем правильно перед загрузкой данных в ИИ.","summary":"Чет пропал пост, повторяю Делаем правильно перед загрузкой данных в ИИ. Инструкция: 1.","summaryKind":"excerpt","text":"#юзфултип \nЧет пропал пост, повторяю Делаем правильно перед загрузкой данных в ИИ. Инструкция:\n1. Тестовая выгрузка … заменяется на ваш файл. Главное:\nА) название листа как у меня «Лист 1». Строго\nБ) название столбца как у меня «Поставщик». Строго\n2. В «Итог…» вкладка «путь..» меняем на свой путь, где лежит источник. Вместе с корнем и расширением\n3. Вкладка «Данные»- Обновить все.\n\nЕсли что-то не работает, что-то сделали не так \nКак обычно, лайки, шеры))","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/236"},{"id":231,"date":"2026-06-11","title":"На Hugging Face почти три миллиона моделей.","summary":"На Hugging Face почти три миллиона моделей. Три миллиона(!!!) Неудивительно, что многие начинают переживать, что безнадёжно отстали.","summaryKind":"excerpt","text":"На Hugging Face почти три миллиона моделей. Три миллиона(!!!)\n\nНеудивительно, что многие начинают переживать, что безнадёжно отстали. Каждый день появляются новые модели, агенты, сервисы и фреймворки. Если пытаться изучать всё подряд, очень быстро возникает ощущение, что догнать это невозможно. У некоторых в какой-то момент появляется даже не интерес, а усталость и отрицание.\n\nНо проблема обычно не в количестве моделей.\n\nНикто не учит Excel перебором функций. Сначала понимаешь, как устроены данные, ссылки и формулы. После этого новая функция перестаёт быть проблемой. Логика уже понятна.\n\nС ИИ примерно то же самое.\n\nВместо того чтобы пытаться изучить каждый новый инструмент, полезнее разобраться в нескольких базовых концепциях: \n\n- что такое модель, контекст, память, агент, внешние данные, \n- почему модели ошибаются, \n- когда нужен человек в контуре \n- и почему пять агентов не делают систему в пять раз умнее.\n\nПосле этого новый сервис перестаёт выглядеть как магия. Он становится очередной реализацией уже знакомых принципов.\n\nЧерез год половина сегодняшних сервисов исчезнет, будет куплена, переименована или заменена другими. Архитектура останется.\n\nИ понимание того, как устроены такие системы, останется тоже.\n#теория","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/231"},{"id":224,"date":"2026-06-10","title":"Вот мы часто говорим, что за волшебный стол принятия решений нас зовут, но мы там не самый сильный голос.","summary":"Вот мы часто говорим, что за волшебный стол принятия решений нас зовут, но мы там не самый сильный голос. Не потому что мы слабые, а потому, что закупки по-прежнему много где воспринимаются как что-то обыденное.","summaryKind":"excerpt","text":"#теория #юзфултип \nВот мы часто говорим, что за волшебный стол принятия решений нас зовут, но мы там не самый сильный голос. Не потому что мы слабые, а потому, что закупки по-прежнему много где воспринимаются как что-то обыденное. Как Wi-Fi. Поэтому вот вам killing аргумент для того, чтобы на вас обернулись. \n\nШутки-шутками, но в закупках есть проекты, которые нельзя оценивать только по цене. Например, изменить упаковку (сделать ее строго в размер без унификации), передать часть функции на аутсорс, выбрать make or buy. \nВо всех этих случаях вопрос не в том, “стало дешевле или нет”, а создает ли проект стоимость для компании с учетом времени, рисков и всех затрат?\n\nДля этого нужен NPV - чистая приведенная стоимость. Простыми словами, NPV показывает, сколько будущая экономия стоит сегодня, потому что 2 млн руб. через год - это не то же самое, что 2 млн руб. сегодня. Сегодняшние деньги можно пустить в оборот, закрыть кредит, купить сырье или вложить в другой проект.\n\nПример.\nПроект по упаковке стоит 3,4 млн руб. на старте (считаем все затраты)\nОжидаемая чистая экономия - 2 млн руб. в год.\nСрок расчета - 3 года.\nСтавка дисконтирования - 20% (можно считать по вашей ставке кредитования или по ключу)\n\nСчитаем будущую экономию в сегодняшних деньгах:\n1 год: 2 000 000 / 1,2 (1+20% как НДС) = 1 666 667 руб.\n2 год: 2 000 000 / 1,2² = 1 388 889 руб.\n3 год: 2 000 000 / 1,2³ = 1 157 407 руб.\nИтого: 4 212 963 руб.\n\nВычитаем стартовые затраты:\n4 212 963 - 3 400 000 = 812 963 руб.\nNPV положительный. Значит, проект создает стоимость.\n(но если реальная экономия окажется не 2 млн, а 1,5 млн руб. в год, проект может уже не пройти)\n\nПочему это важно? Потому что уменьшенная коробка может принести экономию. А может принести новые SKU, остатки, тесты, согласования, замороженные деньги и управленческую сложность.\n\nВывода не будет)","terms":["tco"],"topics":["price"],"url":"https://t.me/notdandeliongirl/224"},{"id":221,"date":"2026-06-09","title":"Коллеги, и помните - ИИ дает свой ответ как наиболее вероятностно верный.","summary":"Коллеги, и помните - ИИ дает свой ответ как наиболее вероятностно верный. Он не знает контекста; не знает, как вы решали когда-то проблему; какие отношения с вашим внутренним заказчиком.","summaryKind":"excerpt","text":"Коллеги, и помните - ИИ дает свой ответ как наиболее вероятностно верный. Он не знает контекста; не знает, как вы решали когда-то проблему; какие отношения с вашим внутренним заказчиком.\n\nОн такой новый альфа-зумер, который начитался книжек и решил, как правильно. Где-то он будет прав, а где-то не совсем. \n\nПоэтому ваши решения не будут его обучать, но будут показывать другим коллегам какие-то лайфхаки и идеи.","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/221"},{"id":212,"date":"2026-06-07","title":"Цена на экране - это не цена.","summary":"Цена на экране - это не цена. Это оплата иллюзии контроля.","summaryKind":"excerpt","text":"#теория \nЦена на экране - это не цена. Это оплата иллюзии контроля.\n\nTCO считают все. Логистику считают почти все. А вот то, что поставщик находится в зоне с ежемесячными прилётами - это уже как повезёт. Повезёт с ним, а не с вами.\n\nВ нынешнее время к классической модели TCO стоит добавить несколько неудобных строк.\n\nПервая: геолокация критического поставщика. Не абстрактный «риск срыва», а конкретный вопрос - если производство встанет из-за атаки по инфраструктуре региона, у вас есть альтернатива? Или вы начнёте её искать уже в режиме пожара?\n\nВторая: релокация. Производственный поставщик в регионе с высоким оттоком персонала - это не просто социальный риск. Это ваша потенциальная строка в бюджете, когда придётся либо платить за релокацию ключевого технолога, либо объяснять директору, почему запчасть едет три недели вместо пяти дней.\n\nТретья: плечо для сервиса и ЗИП. Оборудование встаёт не по расписанию. И если сервисный инженер поставщика добирается к вам двое суток через две пересадки - эти двое суток тоже стоят денег. Конкретных. Считаемых.\n\nTCO - хороший инструмент. Но он был придуман в мире, где границы стабильны, логистика предсказуема, а карта рисков не обновляется каждые три месяца.\n\nСейчас карта обновляется.\n\nВопрос только в том, кто пересматривает поставщиков по новой карте, а кто - по старой Excel-табличке с 2021 года.","terms":["tco"],"topics":["price"],"url":"https://t.me/notdandeliongirl/212"},{"id":204,"date":"2026-06-03","title":"Так, раз пошла такая пьянка, то вот еще (кратко, все кидать не буду, иначе будет простыня) возможность обучения с ИИ, но уже вариант с закупками.","summary":"Так, раз пошла такая пьянка, то вот еще (кратко, все кидать не буду, иначе будет простыня) возможность обучения с ИИ, но уже вариант с закупками. Почему да - а потому что соискание позиций в консалтинг типа Маккинзи идет в том числе и через кейсы.","summaryKind":"excerpt","text":"#теория \nТак, раз пошла такая пьянка, то вот еще (кратко, все кидать не буду, иначе будет простыня) возможность обучения с ИИ, но уже вариант с закупками. \n\nПочему да - а потому что соискание позиций в консалтинг типа Маккинзи идет в том числе и через кейсы. Важно подумать, быстро разродиться и, главное, по существу. \n\nВключи режим учителя по закупкам. Хочу, чтобы в режиме вопрос -ответ ты раз в день прогонял меня по вопросам, связанным с закупками не как линейного сотрудника, а как руководителя с опытом. Нужно в режиме найденных тобой кейсов- кризисное управление, переговоры, давление, управление и так далее.  Вопросы должны быть практические без ухода в теорию. То есть «что бы ты сделала если», «как ты сделаешь …», «какой будет твоя стратегия»?\nЯ отвечаю кратко, по существу. Если тебе непонятна мысль - просишь ее пояснить. Мне не нужны твои рассуждения. Комментарий на мой ответ тоже кратко и по существу в паре предложений. \nЕсли есть сейчас вопросы к обучению - задавай. Поставь расписание  раз в день на такое-то время. \n\nСкажу про себя- прикольно, заставляет мозг работать. Особенно если не действовать по принципу «пойду подумать и отвечу». \n\nК вопросу, почему инструкции отличаются? Вариант с языком в рамках проекта, где только одна тема - немецкий язык. В случае с обучением - в рамках проекта «Закупки, ИИ, катмен» - то есть все мои идеи, мысли, терзания, бэклоги и так далее, чтобы не потерялось. Поэтому инструкция короче и обыденнее.","terms":["negotiation","ai"],"topics":["ai","negotiation"],"url":"https://t.me/notdandeliongirl/204"},{"id":203,"date":"2026-06-03","title":"Закупочная цена - это не просто цифра.","summary":"Закупочная цена - это не просто цифра. Это оружие.","summaryKind":"excerpt","text":"Закупочная цена - это не просто цифра. Это оружие.\n\nИ как любое оружие, она опасна не сама по себе. Опасно то, в чьих руках она оказывается.\n\nЯ не даю закупочные цены производству. Никогда. Потому что производственник, который знает, сколько стоит подшипник, очень быстро начинает знать, какой поставщик «правильный». А потом выясняется, что этот поставщик - давний знакомый. И вот уже ваша стратегия категорийного менеджмента разбилась о простой человеческий интерес.\n\nЦена - идеальный инструмент для слива. Тихого, почти незаметного. Ты мне, я тебе. Это не конспирология. Это механика, которую я наблюдала в разных отраслях.\n\nПроизводству нужна лучшая совокупная стоимость владения и надёжность оборудования. Не цена поставщика. Продажам - тенденции рынка, факторы влияния, план. Не ваша закупочная маржа. HR занимается людьми, не ценообразованием.\n\nУ каждого подразделения есть своя точка входа в данные. Финансисты и экономисты видят цены, потому что они работают с экономикой закупок. ГД видит всё - это его право. Остальные видят ровно столько, сколько нужно для их задачи.\n\nЭто не секретность ради секретности. Это гигиена.\n\nВопрос только один: если вы всё-таки даёте цены «по-дружески», вы уверены, что дружба работает в обе стороны?","terms":["tco","category"],"topics":["function","price"],"url":"https://t.me/notdandeliongirl/203"},{"id":202,"date":"2026-06-02","title":"Я тут обещала и про ИИ рассказывать вроде бы.","summary":"Я тут обещала и про ИИ рассказывать вроде бы. И вообще - когда закупка ограничивалась закупкой, а не, допустим, минимальным изучением языка, чтобы сказать важному поставщику «привет», «спасибо», «рад тебя видеть» на языке оригинала?)) У меня в запасе Английский, сильно подзабытый немецкий и китайский в стадии изучения для программы «Давайте убежим от Альцгеймера».","summaryKind":"excerpt","text":"#юзфултип  \nЯ тут обещала и про ИИ рассказывать вроде бы. И вообще - когда закупка ограничивалась закупкой, а не, допустим, минимальным изучением языка, чтобы сказать важному поставщику «привет», «спасибо», «рад тебя видеть» на языке оригинала?))\n\nУ меня в запасе Английский, сильно подзабытый немецкий и китайский в стадии изучения для программы «Давайте убежим от Альцгеймера».\nИ вот мне, не побоюсь слова, присралось вспомнить немецкий- во-первых, мне он нравился в институте, во-вторых, он с легкой ебанцой в отличие от тяжелой формы в китайском и в-третьих… Да просто это лучше, чем вечером перед сном где-то залипать.\n\nК чему я. Если вдруг вам также захочется вспомнить язык, то включаете в чате ГПТ микрофон для того, чтобы побороть страх говорить вслух, и кормите его вот такой вот краткой инструкцией.\n\nНаши правила обучения:\n\nРоль: ты - учитель немецкого языка.\nЦель: Не учить немецкий с нуля, а реактивировать старый немецкий и вернуть разговорную речь.\nСхема урока: ты даешь фразу на русском или вопрос на немецком. Я перевожу как могу\nЕсли не помню слово - вставляю русское и продолжаю. Не останавливаюсь из-за ошибок.\n\nПодсказки: После первой попытки ты даешь только:\nзабытые слова;\nминимальные подсказки по конструкции.\nГотовый перевод не даешь. \n\nВторая попытка: я  перевожу ещё раз уже с новыми словами.\nГлавное правило: Лучше сказать криво, чем молчать идеально.\nЕсли ты неправильно понял смысл: Сначала уточняем, что я  хотела сказать, потом разбираем немецкий.\n\nРазбор каждой фразы:\nЧто вспомнила сама: Только то, что появилось без твоих подсказок.\nЧто использовала после подсказки: Слово дал ты, но я  правильно встроила его в речь.\nЧто просто повторила: Если конструкцию фактически дал ты, не считаем её самостоятельным знанием.\nГрамматика: Коротко:\nпорядок слов;\nглаголы;\nосновные ошибки.\nБез длинных лекций.\n\nПроизношение: Только по голосовым сообщениям.\n    Отдельно:\nзвуки;\nударение;\nритм;\nчто звучит по-русски.\n\nПонимание мысли: Проверяем, что ты правильно понял то, что я  хотела сказать.\n\n⸻\n\nДополнительные правила:\nНе учим списки слов отдельно от речи.\nНе зубрим грамматику ради грамматики.\nНовые слова сразу используем в предложениях.\nПостепенно переходим от перевода к живому диалогу.\nЕсли слово забыла - не ищем идеально, а перефразируем проще.\n\nИ ещё одно правило лично для меня:\nНе считать подсказанное слово самостоятельно вспомненным. Это разные стадии восстановления языка, и мы их будем честно разделять.\nПользуйтесь на здоровье. \nПС подойдет не только для воспоминания языка, но и для других «курсов» тоже. Логика одна и та же- не пытаться выучить с нуля, а вытащить из памяти, что осталось, и идти дальше. Ключевое различие 😉","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/202"},{"id":200,"date":"2026-06-01","title":"инструмент для оценки хвостовых закупок.","summary":"инструмент для оценки хвостовых закупок. Не бог весть какой сложный, простой.","summaryKind":"excerpt","text":"#юзфултип инструмент для оценки хвостовых закупок. Не бог весть какой сложный, простой. можно донасытить своими данными  - например, количество спецификаций и перепротянуть формулу. ИИ и ERP -совместимо (я про логику). \nКак обычно - настраивайте под себя.","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/200"},{"id":198,"date":"2026-05-30","title":"Как вы общаетесь с нейромоделями?","summary":"Как вы общаетесь с нейромоделями? Какие инструкции вы им даете?","summaryKind":"excerpt","text":"Как вы общаетесь с нейромоделями? Какие инструкции вы им даете? (Материте ли вы ИИ?😜)\n\nСкажу про себя:\n1. Режим жесткого критика. «Если идея хорошая - развивай и обсуждай. Если идея говно - пиши слабые стороны и сильные все равно, решение принимаю я»\n\n2. Короткие ответы без долгих рассуждений\n\n3. Сначала моя идея, потом твои вопросы, потом обсуждение, потом моя архитектура, потом обсуждение стэка, потом я тестирую. \n\n4. Обязательно формирование бэклогов по команде \n\n5. Разделение внутри проектов на ветки (кому-то удобно обсидиан, кому-то ноушн, мне удобнее в рамках проекта много диалогов, которые раз в неделю собираются в обновляемый файл с резюме)\n\n6. Регулярное обучение - вопрос «что сейчас во мне было слабым? Какие знания? Подготовь краткое обучение по теме, расскажи как это устроено, я задам свои вопросы, если непонятно»\n\nКонечно, это не все, но лично мне такие структуры помогают разложить все по полочкам.\n\nНапример, недавно я решила проверить с ИИ, насколько я еще помню немецкий. Проверили, определили, что нужно для развития, какие упражнения, структура - и все это не «ты молодец», а «где тонкие моменты» и какие упражнения на 10 минут, но ежедневно (помним про consistency) мне нужно делать.","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/198"},{"id":197,"date":"2026-05-29","title":"Главный навык закупщика будущего","summary":"Анна пишет, что будущий сильный закупщик — не просто пользователь AI, а архитектор: человек, который понимает, что можно делегировать модели, какие риски она не увидит и где нужен человек.","summaryKind":"summary","text":"Какое самое важное качество закупщика?\n\nЕще недавно я бы сказала: переговоры, аналитика, категорийный менеджмент.\n\nСейчас многие из этих навыков постепенно дешевеют. Анализировать данные умеет ИИ. Искать информацию умеет ИИ. Готовить переговорные сценарии он тоже скоро будет лучше большинства людей.\n\nПоэтому для меня интереснее другой вопрос:\n\nКакую часть своего опыта вы готовы отдать ИИ, а какую оставите себе?\n\nМне кажется, будущее не за людьми, которые собрали двадцать агентов. Будущее за архитекторами. За теми, кто понимает, что именно нужно поручить ИИ, какие риски он не увидит, где нужен человек и что вообще нельзя автоматизировать. Кажется, главный навык закупщика будущего - не работа с ИИ.\n\nГлавный навык закупщика будущего - решить, какую часть своего мозга можно ему делегировать.","terms":["negotiation","ai","category"],"topics":["ai","function","negotiation"],"url":"https://t.me/notdandeliongirl/197"},{"id":196,"date":"2026-05-28","title":"Продолжение Многие ЭТП сейчас на волне ИИ рассказывают, что «теперь AI есть и у нас», и усиленно докручивают фундамент, который уже давно пора сносить.","summary":"Продолжение Многие ЭТП сейчас на волне ИИ рассказывают, что «теперь AI есть и у нас», и усиленно докручивают фундамент, который уже давно пора сносить.","summaryKind":"excerpt","text":"Продолжение \n\nМногие ЭТП сейчас на волне ИИ рассказывают, что «теперь AI есть и у нас», и усиленно докручивают фундамент, который уже давно пора сносить. Ибо если честно посмотреть на процесс, то внезапно выясняется, что \nПолучить заявку\nРазослать RFQ \nПнуть поставщика \nПроверить НДС, сроки и вложения \nПересобрать Excel после «мы обновили цену»\nЗапросить уточнение \nНапомнить согласующему, что он вообще-то должен согласовать \nПотом напомнить еще раз \nИ еще раз \n\n- не закупка. Это координационный пиздец между почтой, Excel, PDF, ЭТП и людьми, которые забыли ответить.\n\nПоставщику вообще не обязательно жить внутри очередной AI future cyber platform 3000. Он как сидел в почте и Excel, так и продолжит сидеть. Просто вместо закупщика большую часть этой возни начнет делать агент.\n\nСам запросит КП\nСам увидит отклонения\nСам проверит базовые параметры\nСам соберет сравнение\nСам подготовит историю поставщика\nСам будет ходить и всех заебывать напоминаниями вместо живого человека\n\nА закупщик останется там, где цена ошибки слишком высокая: сложные переговоры, CAPEX, монополисты, конфликтные категории и прочие места, где люди пока важнее автоматизации.\n\nУ меня пока все больше ощущение, что рынок идет не к «ИИ вместо закупщика» или «ЭТП с ИИ», а к моменту, когда внезапно выяснится, что половину текущей архитектуры закупок можно было вообще не строить.","terms":["monopoly","negotiation","ai","automation"],"topics":["ai","data","negotiation","supplier"],"url":"https://t.me/notdandeliongirl/196"},{"id":195,"date":"2026-05-28","title":"Давайте честно?","summary":"Давайте честно? Значительная часть ЭТП существует давно не потому, что это лучший способ закупать, а потому что это создает ощущение контроля, прозрачности и спокойствия для СБ, аудита и акционеров.","summaryKind":"excerpt","text":"Давайте честно? Значительная часть ЭТП существует давно не потому, что это лучший способ закупать, а потому что это создает ощущение контроля, прозрачности и спокойствия для СБ, аудита и акционеров.\n\nКогда-то это действительно выглядело как прорыв. Все фиксируется, поставщики конкурируют, закупщик не может тихо «порешать» в обход системы в курилке. Красота же.\n\nА потом рынок адаптировался. Появились правильные поставщики, правильные КП, формальная конкуренция и очень большое количество процедур ради самих процедур. (И давайте не делать вид, что никто этого не понимает)\n\nПри этом сама архитектура многих ЭТП как будто застряла где-то между 2010 годом и «загрузите скан в PDF не более 5 МБ». Все это медленно, тяжело, неповоротливо и завязано на огромное количество механической координации. Письма, напоминания, пересборка таблиц, проверка вложений, бесконечные уточнения, согласования и попытки свести все это в одну картину мира. (Комиссии поставщиков при этом никуда не исчезают. Они прекрасно зашиваются в цену)\n\nЯ в какой-то момент психанула и в Русале сделала свою ЭТП с интеграцией в ERP и СЭД. Она экономила под 20% времени просто потому, что сама проверяла часть вещей, пинала участников процесса и требовала от закупщика минимум механических действий. И чем глубже я залезала в эту логику, тем сильнее было ощущение, что значительная часть текущих ЭТП - это уже не технология будущего, а какой-то очень дорогой ритуал согласования.\n\nЗнаете, что агентные модели начинают жрать первыми? Координацию, пинки, сверки, перекладывание информации между Excel, почтой и PDF, напоминания поставщикам и прочую операционную жопу, на которой сейчас держится половина закупочного процесса.\nПродолжение в следующем посте.","terms":["governance"],"topics":["function"],"url":"https://t.me/notdandeliongirl/195"},{"id":194,"date":"2026-05-27","title":"С чего начинать работу с AI в закупках","summary":"Анна формулирует порядок работы с AI: сначала цель, эффект, мастер-данные, архитектура решений и проверка слабых мест. AI-проект без структуры превращается в дорогую игрушку.","summaryKind":"summary","text":"#теория \nРазмещу отдельно как памятку.\nИ повторюсь еще раз - любая работа с ИИ начинается с прозы: \n1. Постановка цели - зачем это нам (вы готовы, дети?) и что мы хотим получить на выходе\n2. Оценка эффекта - будет ли эффект выше, чем затраты на него - временные, финансовые и т.д.\n3. Что у нас с мастерданными -в жопе они и нужно все приводить в норму, более- менее и уже можно что-то начинать делать. кто это будет поддерживать\n4. Какую архитектуру мы видим - не верхнеуровнево, а с вилкой решений  \"если-то\"), потому что дьявол в деталях. Не продуманная хотя бы до 2-3 уровня структура в итоге превратится в дорогой проект.\n5. Работа по формированию структуры в виде вопрос-ответ с ИИ (если сами не понимаете, что хотите) и в режиме критика \"найди слабые места и уязвимости\".","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/194"},{"id":193,"date":"2026-05-27","title":"Главная проблема непрямых закупок в том, что компании пытаются управлять ими как единым процессом, хотя внутри там слишком разные категории с разной критичностью для бизнеса, разной скоростью, разными рисками и разной возможностью автоматизации.","summary":"Главная проблема непрямых закупок в том, что компании пытаются управлять ими как единым процессом, хотя внутри там слишком разные категории с разной критичностью для бизнеса, разной скоростью, разными рисками и разной возможностью автоматизации.","summaryKind":"excerpt","text":"#теория \nГлавная проблема непрямых закупок в том, что компании пытаются управлять ими как единым процессом, хотя внутри там слишком разные категории с разной критичностью для бизнеса, разной скоростью, разными рисками и разной возможностью автоматизации.\nИменно поэтому непрямые закупки быстро превращаются в хаос: ручные согласования, закупки мимо системы, бесконечные исключения и попытки потом “починить всё ИИ”,  исторически \"она учит лучше всех\". Если вы когда-то сталкивались с ними - вы понимаете, какое это адище. \nНормальная дорожная карта выглядит намного прозаичнее и проще. \n1. Сначала очистка хаоса.\n   Нужно понять, кто что покупает, у кого, где дублирование, какие закупки идут вне системы и какие процессы уже тормозят бизнес.\nИИ можно подключить для семантического и прямого поиска дублей, анализа и определения пула поставщиков\n2. Потом многоуровневая категоризация.\n   Не только по типу затрат, но и по влиянию на финансовый результат и критичности для бизнеса. Потому что обслуживание оборудования и, например, обучение сотрудников - это вообще разные модели управления закупками.\nИИ аналогично для категорийного анализа, составления опросника для принятия решения\n3. После этого - разделение ролей и SLA.\n   Закупки, производство, финансы и внутренние заказчики должны иметь понятные зоны ответственности. Иначе начинается классическая корпоративная игра “это не мы задержали”.\nЕсли вам жизненно необходимо присутствие ИИ в вашей жизни - тут тоже подойдет использование ИИ для помощи в написании SLA.\n4. И только потом автоматизация и ИИ.\n   Каталоги, лимиты, проверенные поставщики, контроль отклонений, автоматическое определение категорий затрат и поиск аномалий.\n\nПотому что если подключить ИИ раньше, он обычно не убирает хаос, он тупо помогает хаосу работать быстрее.","terms":["ai","automation","category"],"topics":["ai","data","function"],"url":"https://t.me/notdandeliongirl/193"},{"id":185,"date":"2026-05-25","title":"Коэффициент общей эффективности оборудования.","summary":"Коэффициент общей эффективности оборудования. Звучит как KPI для производственников.","summaryKind":"excerpt","text":"Коэффициент общей эффективности оборудования. Звучит как KPI для производственников. Закупки сюда обычно не зовут.\n\nИ зря.\n\nOEE - это три множителя: доступность, производительность, качество. Когда оборудование стоит из-за ожидания запчасти - это закупки. Когда работает на пониженной скорости из-за неоригинального расходника - это закупки. Когда выдаёт брак из-за замены смазки на дешёвый аналог - это тоже закупки.\n\nПроизводство видит потерю в станке. Закупки видят экономию на бюджете. Никто не считает, во что обходится час простоя.\n\nЯ не буду называть конкретные цифры из чужих проектов - это было бы красиво, но нечестно. Скажу то, что знаю из практики категорийного управления в промышленности: решение о замене оригинального компонента на аналог почти никогда не принимается с расчётом влияния на OEE. Принимается с расчётом экономии на единицу закупки.\n\nЭто не вина закупщика. Это архитектура целей. Закупки оценивают по savings. Производство - по выпуску. Общий знаменатель отсутствует.\n\nКатегорийный менеджер по MRO, который понимает OEE - это редкость. Не потому что сложно. А потому что никто не просил считать дальше строки бюджета.\n\nХотя, если подумать: оптимизация закупок расходников, которая снижает OEE на несколько процентов - это не экономия. Это перекладывание убытков из одной статьи в другую. С премией за находчивость закупщику.","terms":["category","governance"],"topics":["function"],"url":"https://t.me/notdandeliongirl/185"},{"id":180,"date":"2026-05-24","title":"Закупщику в 2026 году дали всё и тут же стали требовать с него как с пятерых: ИИ пишет КП, агенты мониторят рынок, аналитика строится за минуты.","summary":"Закупщику в 2026 году дали всё и тут же стали требовать с него как с пятерых: ИИ пишет КП, агенты мониторят рынок, аналитика строится за минуты. Логично было бы решить, что давление снизилось, да?","summaryKind":"excerpt","text":"Закупщику в 2026 году дали всё и тут же стали требовать с него как с пятерых:\n\nИИ пишет КП, агенты мониторят рынок, аналитика строится за минуты. Логично было бы решить, что давление снизилось, да? Но нет, оно перераспределилось.\n\nПоставщик подвёл? Надо было проверить глубже. Цена выросла? Надо было зафиксировать раньше. ИИ ошибся в анализе? Надо было перепроверить вручную (Старая добрая херня - ответственность без полномочий. Теперь с апгрейдом.)\n\nПарадокс 2026 года не в том, что инструментов мало- их как раз слишком много. Половина из них не интегрирована. Треть куплена по указанию сверху. И всё это работает параллельно с Excel, который никто официально не отменял.\n\nИногда этот процесс напоминает «как не сойти с ума, когда тебя просят быть стратегом, аналитиком, переговорщиком и оператором пяти систем одновременно». Раньше можно было сказать «я не знал». Теперь нельзя - «Ведь у вас был доступ ко всему! Ты почему не использовал ИИ или вайбкодинг?»\n\nЗакупщик 2026 года -  когда требования выросли непропорционально выданным инструментам.","terms":["negotiation","ai","governance"],"topics":["ai","function","negotiation"],"url":"https://t.me/notdandeliongirl/180"},{"id":179,"date":"2026-05-23","title":"Пара полезных старых постов (вдруг вы пропустили, а я взяла и подготовила) 1) благоприятные условия для получения лучших предложений 2) нормализация справочника СКЮ 3) ассесмент и оптимизация ФОТ","summary":"Пара полезных старых постов (вдруг вы пропустили, а я взяла и подготовила) 1) благоприятные условия для получения лучших предложений 2) нормализация справочника СКЮ 3) ассесмент и оптимизация ФОТ","summaryKind":"excerpt","text":"Пара полезных старых постов (вдруг вы пропустили, а я взяла и подготовила) \n\n1) благоприятные условия для получения лучших предложений \n2) нормализация справочника СКЮ \n3) ассесмент и оптимизация ФОТ\n\n#теория #юзфултип","terms":["mdm"],"topics":["data"],"url":"https://t.me/notdandeliongirl/179"},{"id":178,"date":"2026-05-22","title":"Что делать с монополистом в закупках","summary":"Анна пишет, что с монополистом часто не работают стандартные техники выбивания скидки. Вместо этого нужно снижать зависимость, менять предмет переговоров и становиться прогнозируемым клиентом.","summaryKind":"summary","text":"#теория \nМеня - если вы нежные люди, закройте уши руками - пиздец как веселят и умиляют вебинары / курсы «1000 и 1 способ выбить скидку у монополиста»; «50 оттенков серого способов провести жесткие переговоры с монополистом». \n\nПочему?\n\nПотому что монополист обычно знает, что он монополист и его наиболее вероятный ответ «не нравится? Не берите». Причины такой борзости ясны, речь не об этом. Сегодня хочу дать (добавлять, спорить с автором в этом канале разрешено, если что) несколько инструментов для улучшения, скажем так, микроклимата в закупках у монополиста:\n\n1) Снижение зависимости \n\nАльтернативы, локализация, \nизменение спецификаций, снижение потребления или dual sourcing\n\n2) Смена предмета переговоров\nЕсли цену снизить нельзя - начинают работать SLA, отсрочка, резервирование мощностей, сервис, квоты и фиксация условий.\n\n3) Стать удобным клиентом\n    \nМонополисты любят прогнозируемость: нормальное планирование, стабильные объемы, быстрые согласования и отсутствие постоянного хаоса.\n\n4) Долгосрочные контракты \n    \nГарантированные объемы, совместное планирование и понятные правила игры на несколько лет вперед часто работают лучше давления.\n\n5) Понимание экономики поставщика\n    \nНужно знать, где у него bottleneck, простои, дефицит мощностей и что для него реально важно. Иногда скидку не дадут, но дадут приоритет или сервис.\n\n6) Навести порядок у себя\n    \nОчень часто проблема не в монополисте, а во внутреннем бардаке компании: раздробленный спрос, отсутствие планирования и хаотичные закупки.\n\nВообще вера, что каждого поставщика можно дожать- иллюзорна, опасна и слишком оптимистична. Но можно сделать так, чтобы зависимость перестала быть абсолютной.\n\nПС с монополистами-ресурсниками не берусь ничего рекомендовать. Я не могу добиться ответа от Мособлеирц без дергающегося глаза.","terms":["deferral","monopoly","negotiation"],"topics":["finance","negotiation","supplier"],"url":"https://t.me/notdandeliongirl/178"},{"id":175,"date":"2026-05-21","title":"продолжаю серию для сборки вашего катмен.","summary":"продолжаю серию для сборки вашего катмен. Во вложении снова полезный инструмент (других не держим) по оценке баланса сил между вами и поставщиком.","summaryKind":"excerpt","text":"#юзфултип \nпродолжаю серию для сборки вашего катмен. Во вложении снова полезный инструмент (других не держим) по оценке баланса сил между вами и поставщиком. Где может быть нужно - для BATNA (писала тут), для помощи в заполнении матрицы Кралича (давала матрицу тут, писала теорию тут), но и вообще перед переговорами и так, чисто для себя, тоже норм. \nКаждый настраивает под себя, наличие формул и здравого смысла позволяет засунуть как ТЗ для настройки ЕРП, ИИ-агентов и так далее. Шеры, лайки - в общем, все как обычно.   И, конечно, автору была бы приятна обратная связь. А то молчание лишает вдохновения 😉","terms":["negotiation","ai","category"],"topics":["ai","function","negotiation"],"url":"https://t.me/notdandeliongirl/175"},{"id":174,"date":"2026-05-20","title":"Мой агент по сравнению КП с последующим написанием писем поставщикам занимает несколько страниц промпта.","summary":"Мой агент по сравнению КП с последующим написанием писем поставщикам занимает несколько страниц промпта. Если кто-то хочет попробовать - можете обезличить данные и прислать в личку.","summaryKind":"excerpt","text":"Мой агент по сравнению КП с последующим написанием писем поставщикам занимает несколько страниц промпта.\nЕсли кто-то хочет попробовать - можете обезличить данные и прислать в личку. Я вышлю результат обратно. Совершенно «безвоздмездно то есть дадом»","terms":[],"topics":["function"],"url":"https://t.me/notdandeliongirl/174"},{"id":173,"date":"2026-05-20","title":"Самый честный ответ на вопрос «с чего начать с ИИ в закупках» - это не тот, который вы ожидаете услышать.","summary":"Самый честный ответ на вопрос «с чего начать с ИИ в закупках» - это не тот, который вы ожидаете услышать. Не с автоматизации.","summaryKind":"excerpt","text":"Самый честный ответ на вопрос «с чего начать с ИИ в закупках» - это не тот, который вы ожидаете услышать.\n\nНе с автоматизации. Не с интеграции. Не с обучения нейросети на ваших данных.\n\nС одного промпта. Одного.\n\nОткрываете Claude или ChatGPT. Пишете: «Ты - опытный категорийный менеджер в промышленных закупках. Я пришлю тебе коммерческое предложение от поставщика. Найди слабые места в условиях, задай мне уточняющие вопросы и предложи, что можно пересмотреть на переговорах».\n\nВсё. Это и есть агент. Простой. Без API, без кода, без IT-отдела.\n\nДальше вставляете КП. Получаете список вопросов, которые неловко задавать поставщику напрямую, но очень нужно. Про гарантийные сроки. Про штрафные санкции. Про условия досрочного расторжения.\n\nЯ называю это «второй парой глаз, которая не устала и не боится поставщика».\n\nЭто не магия. Это инструмент, который работает ровно настолько, насколько точно вы объяснили ему свою роль и задачу.\n\nНовичок с хорошим промптом обгоняет опытного закупщика с плохим запросом. Это немного обидно, если вы опытный закупщик.","terms":["negotiation","ai","automation","category"],"topics":["ai","data","function","negotiation"],"url":"https://t.me/notdandeliongirl/173"},{"id":172,"date":"2026-05-18","title":"Продолжение поста.","summary":"Продолжение поста. Я счас напишу, а потом возьму тайм-аут.","summaryKind":"excerpt","text":"Продолжение поста. Я счас напишу, а потом возьму тайм-аут. Не теряйте. \n\n- Таможенная база. ФТС публикует данные по импорту и экспорту в агрегированном виде. Если ваша категория хоть частично импортная - это уже ориентир по объёму. \n\n- Платные базы типа СПАРК или Контур.Фокус дают выручку конкретных игроков. Сложите топ-5 поставщиков в сегменте - получите нижнюю границу рынка.\n\n- Производственные мощности. Для промышленных категорий - открытые данные Росстата по выпуску продукции в натуральных единицах. Тонны, штуки, метры. Это не деньги, но это объём. Часто херня, ибо один бог ведает, как считает Росстат, но курочка по зернышку. \n\n- Тендерные площадки. СБИС, Контур - там видно, кто и сколько закупал похожего. Агрегируйте по ОКПД2. Грубо, но быстро.\n\n- Отраслевые ассоциации. Часто публикуют аналитику раз в год. Бесплатно. Её никто не читает, потому что она скучная. Это ваше преимущество.\n\nЗакрытый рынок закрыт только для тех, кто долбится в одну дверь.","terms":[],"topics":["function"],"url":"https://t.me/notdandeliongirl/172"},{"id":169,"date":"2026-05-17","title":"Сейчас рынок массово пьян от вайбкодинга.","summary":"Сейчас рынок массово пьян от вайбкодинга. Каждый второй пост про то, как человек без опыта за вечер собрал стартап, CRM, агента или автоматизацию, а программисты скоро вообще станут не нужны.","summaryKind":"excerpt","text":"Сейчас рынок массово пьян от вайбкодинга.\n\nКаждый второй пост про то, как человек без опыта за вечер собрал стартап, CRM, агента или автоматизацию, а программисты скоро вообще станут не нужны. И самое неприятное - часть этого действительно правда.\n\nИИ реально снизил порог входа. Сегодня без команды разработки можно собрать лендинг, Telegram-бота, внутренний инструмент, простого агента, автоматизацию отчетов или workflow в n8n. Раньше между идеей и реализацией была пропасть. Сейчас - хороший промпт и пара роликов на YouTube.\n\nИ это огромный плюс. Стало проще тестировать идеи, запускать MVP и автоматизировать рутину без полугодового ожидания IT-отдела.\n\nНо проблема в том, что рынок начинает путать рабочий прототип и надежную систему.\n\nПочти весь вайбкодинг сейчас живет в логике:\n«Зеленая галочка в workflow горит - значит все хорошо».\n\nЧто внутри происходит, как обрабатываются ошибки, что будет при нагрузке, падении сервиса или редком сценарии - хер знает.\n\nА потом внезапно выясняется, что система:\n- потеряла часть заказов,\n- отправила дубликаты,\n- перепутала данные,\n- сломалась при росте нагрузки,\n- или тихо ошибается уже третий месяц подряд.\n\nИ вот здесь начинается граница, которую сейчас почти никто не обсуждает:\n\nЕсть вещи, которые вполне можно отдавать вайбкодерам: лендинги, внутренние калькуляторы, простые боты, черновые автоматизации, агенты без права что-то делать без согласования человека.\n\nНо чем ближе система к деньгам, клиентам, ERP, персональным данным или критичным процессам, тем опаснее становится подход «ну вроде работает».\n\nПотому что там уже нужна не просто сборка кубиков. Там нужно понимать:\n- отказоустойчивость,\n- обработку ошибок,\n- контроль доступа,\n- чувствительность данных,\n- что будет при падении интеграции,\n- как система поведет себя через полгода и при росте нагрузки.\n\nАрхитектура - это не «чтобы сейчас запустилось». Архитектура - это понимание последствий.\n\nИ здесь человек без опыта, которому дали доступ к автоматизации и данным компании, иногда реально напоминает обезьяну с гранатой. Не потому что человек глупый, а потому что современные инструменты дают ощущение компетентности сильно раньше, чем появляется сама компетентность.\n\nЯ не считаю вайбкодинг злом. Наоборот, для небольших задач это революция. Но рынок сейчас слишком увлечен восторгом от того, что AI написал 500 строк кода за 3 минуты, и почти не думает о том, что будет, когда эти системы начнут жить внутри реального бизнеса.","terms":["ai","automation"],"topics":["ai","data"],"url":"https://t.me/notdandeliongirl/169"},{"id":165,"date":"2026-05-15","title":"Когда всё работает в закупках - это не успех.","summary":"Когда всё работает в закупках - это не успех. Это момент, когда нужно начинать нервничать.","summaryKind":"excerpt","text":"Когда всё работает в закупках - это не успех. Это момент, когда нужно начинать нервничать.\n\nПотому что идеальный закупщик в глазах бизнеса выглядит подозрительно одинаково с ненужным закупщиком. Ничего не горит, поставщики приезжают вовремя, документы согласуются без истерик, цены не улетают в космос, производство не орёт, склад не пишет капсом в два часа ночи. Красота. Система работает.\n\nПервые месяцы это даже нравится. Вы сидите с кофе, открываете красивый дашборд и изображаете стратегическое мышление. Потом наступает странная стадия. Вы всё ещё смотрите в экран, но уже больше для поддержания легенды. Потому что тушить нечего.\n\nИ вот тут начинается самое интересное.\n\nПроблема не в том, что вы плохо работаете. Проблема в том, что хорошо работающие закупки очень быстро становятся для компании чем-то вроде электричества в розетке. Пока всё есть - никто не замечает. Заметят только когда всё сдохнет.\n\nСистема, которую вы строили годами, постепенно начинает жить без вас. И это довольно мерзкое чувство. Потому что формально это ваш успех. А по ощущениям - вы стали фоновым процессом. Как Wi-Fi. Вспоминают только когда пропал.\n\nСамое забавное, что именно в этот момент многие начинают умирать профессионально. Очень тихо и очень комфортно. С хорошими KPI, спокойным календарём и иллюзией стабильности. Люди годами сидят внутри идеально настроенного процесса и не замечают, как рынок уже поменялся, поставщики поменялись, риски поменялись, а они всё ещё охраняют систему, которую построили для прошлого мира.\n\nА потом приходит очередная оптимизация расходов, и внезапно выясняется, что невидимые функции сокращать проще всего. Потому что «у них же и так всё работает».\n\nПоэтому, когда в закупках всё спокойно - это не повод расслабиться. Это повод либо лезть в новый хаос внутри компании, либо идти туда, где хаос ещё не приручили. Новая категория, новая страна, новая трансформация, новый бардак, который пока держится на Excel, мате и надежде.\n\nПотому что в закупках ценят не момент, когда всё работает. Ценят момент, когда без вас перестаёт работать вообще всё.","terms":["analytics","governance"],"topics":["data","function"],"url":"https://t.me/notdandeliongirl/165"},{"id":163,"date":"2026-05-15","title":"продолжу серию публикаций полезных инструментов и катмена.Во вложении полезная штука - очень простая, но наглядная, по оценке риска поставщиков.","summary":"продолжу серию публикаций полезных инструментов и катмена.Во вложении полезная штука - очень простая, но наглядная, по оценке риска поставщиков. Повторяю - каждый делает ПОД СЕБЯ: добавляет риски, поставщиков.","summaryKind":"excerpt","text":"#юзфултип\nпродолжу серию публикаций полезных инструментов и катмена.Во вложении полезная штука  - очень простая, но наглядная, по оценке риска поставщиков. Повторяю - каждый делает ПОД СЕБЯ: добавляет риски, поставщиков. Можно заменить на СКЮ - пофиг. Это модель может являться основой для запихивания в ИИ, для  разрабов в ЕРП системы (на пайтон для дашей тоже подойдет)\nШеры, лайки, как обычно, приветствуются.","terms":["price-change","supplier-risk","ai"],"topics":["ai","negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/163"},{"id":162,"date":"2026-05-13","title":"Каждый тип закупщика в команде виден сразу.","summary":"Каждый тип закупщика в команде виден сразу. Но убивает цепочку поставок только один.","summaryKind":"excerpt","text":"Каждый тип закупщика в команде виден сразу. Но убивает цепочку поставок только один.\n\n\n1) Исполнитель. Делает ровно по заявке. Не виноват ни в чём. Не нужен ни в чём сложном. Про него был прошлый пост.\n\n2) Переговорщик. Выбивает скидку там, где нужно было выстроить отношения. Приходит к поставщику раз в год - с требованием. Потом удивляется, почему в дефицит его заявки уходят в конец очереди.\n\n3) Аналитик. Знает всё про рынок. Excel на три экрана. Решения нет. Анализ как способ не принимать решение - это отдельный вид спорта.\n\n4) Стратег. Говорит про категорийный менеджмент, TCO и партнёрство с поставщиками. Иногда даже делает это. Редкий вид.\n\n5) Политик. Вот этот убивает.\n\nОн не срывает поставки сам. Он просто выстраивает закупки так, чтобы все решения шли через него. Информация дозируется. Поставщики прикормлены лично. Альтернативы не развиваются - зачем, если текущая схема работает на него. Когда он уходит, цепочка поставок рассыпается. Потому что держалась не на процессе. На человеке.\n\nЯ видела такое один раз. Компания потом полгода восстанавливала базу поставщиков с нуля.\n\nСамое интересное: Политик всегда выглядит как лучший закупщик в команде. KPI в порядке. Поставщики довольны. Руководство хвалит.\n\nДо момента, когда он уходит.","terms":["tco","negotiation","supplier-risk","srm","category","governance"],"topics":["function","negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/162"},{"id":153,"date":"2026-05-10","title":"Где брать информацию, которую не гуглят: - Менеджер поставщика на еженедельном звонке - что происходит с ценами у вас на горизонте квартала - Технолог или снабженец поставщика: знает про дефицит компонентов раньше коммерческого отдела.","summary":"Где брать информацию, которую не гуглят: - Менеджер поставщика на еженедельном звонке - что происходит с ценами у вас на горизонте квартала - Технолог или снабженец поставщика: знает про дефицит компонентов раньше коммерческого отдела. Не стесняйтесь звать их на переговоры - Профессиональные маркетплейсы (Лемана Про, Комус): динамика цен видна без запросов.","summaryKind":"excerpt","text":"Где брать информацию, которую не гуглят:\n\n- Менеджер поставщика на еженедельном звонке - что происходит с ценами у вас на горизонте квартала\n- Технолог или снабженец поставщика: знает про дефицит компонентов раньше коммерческого отдела. Не стесняйтесь звать их на переговоры\n- Профессиональные маркетплейсы (Лемана Про, Комус): динамика цен видна без запросов. \n- Отраслевые чаты, форумы и ассоциации- у некоторых людей эго «я знаю больше вас всех» превалирует над NDA, поэтому нет-нет, да и узнаете инсайты \n- Логист поставщика: видит задержки и узкие места раньше всех. Тоже не бойтесь попросить пригласить их на переговоры (как обучиться лучше «читать» лица писала здесь)\n\nПроблема одна. Такой разговор возможен только если у вас отношения, а не транзакция.\n\nЕсли вы видите поставщика раз в год на тендере - он не расскажет вам ничего. С фига ли.\n\nИрония в том, что лучший аналитический инструмент в закупках не покупается, не создается ИИ-агентами. Он выращивается годами. И называется просто: нормальные отношения с поставщиком.\n#теория","terms":["negotiation","srm","ai"],"topics":["ai","negotiation","supplier"],"url":"https://t.me/notdandeliongirl/153"},{"id":152,"date":"2026-05-08","title":"Когда начинают обсуждать категорийную стратегию, разговор почти всегда очень быстро скатывается в цену, тендеры, консолидацию объемов и «где еще можно дожать поставщика».","summary":"Когда начинают обсуждать категорийную стратегию, разговор почти всегда очень быстро скатывается в цену, тендеры, консолидацию объемов и «где еще можно дожать поставщика». При этом самые неприятные вещи обычно вылезают вообще не там.","summaryKind":"excerpt","text":"Когда начинают обсуждать категорийную стратегию, разговор почти всегда очень быстро скатывается в цену, тендеры, консолидацию объемов  и «где еще можно дожать поставщика». При этом самые неприятные вещи обычно вылезают вообще не там.\n\nНапример, страховой запас. Тот самый, который многие держат по принципу «пусть лучше лежит, чем вдруг чего». В какой-то момент компания внезапно обнаруживает, что у нее на складе спокойно заморожены десятки миллионов рублей, потому что никто никогда не задавал простой вопрос: а этот объем вообще действительно нужен? Или мы просто боимся обосраться?\n\nОбратная ситуация выглядит еще интереснее. Кто-нибудь радостно сокращает запасы ради красивого отчета по оборотному капиталу, а потом оказывается, что копеечная деталь стоимостью меньше бизнес-ланча способна остановить линию на несколько миллионов рублей в день. И внезапно выясняется, что дешевые позиции далеко не всегда являются неважными. Закупщики обычно очень быстро начинают понимать разницу между «дешево» и «некритично». Особенно после пары звонков от производства вечером в пятницу.\n\nЕще одна вещь, на которую редко смотрят нормально - нестабильность поставок. На бумаге два поставщика могут выглядеть одинаково. Цена одинаковая, качество одинаковое, спецификация одинаковая. Только один привозит стабильно за две недели, а второй - как повезет. От 2 недель и до заката. И вот под такого «творческого» поставщика компания незаметно начинает раздувать страховые запасы, потому что жить в режиме «может приедет, а может нет» почему-то никто не любит.\n\nОтдельно всегда удивляет, как мало считают реальную стоимость внедрения инициатив. На презентации экономия выглядит великолепно. А потом начинается: перенастройка линии, согласование качества, тесты, сопротивление производства, новые спецификации, аудит поставщика. И проект с красивыми 10% экономии внезапно оказывается дорогим и мучительным, а скучная инициатива по стабилизации поставок дает бизнесу больше эффекта и меньше седых волос (см.прошлый пост) \n\nЧем дольше работаю в закупках, тем больше убеждаюсь: сильная категорийная стратегия - это обычно не про героическое выбивание еще двух процентов цены. Это про понимание, где компания на самом деле теряет деньги, даже если в отчетах\n все выглядит вполне прилично.\n#теория","terms":["safety-stock","working-capital","category"],"topics":["finance","function","inventory"],"url":"https://t.me/notdandeliongirl/152"},{"id":150,"date":"2026-05-06","title":"Закупщик, который делает ровно то, что написано в должностной инструкции, не виноват.","summary":"Закупщик, который делает ровно то, что написано в должностной инструкции, не виноват. Он просто не нужен.","summaryKind":"excerpt","text":"Закупщик, который делает ровно то, что написано в должностной инструкции, не виноват. Он просто не нужен.\n\nИсполнитель выбирает поставщика по заявке. Специалист видит, что заявка составлена неправильно, и говорит об этом. Эксперт понимает, почему так получилось, и меняет процесс. Разница не в должности. В том, что человек выращивает в голове каждый день.\n\nЯ видела закупщиков с двадцатилетним стажем, которые не знали ничего, кроме своей номенклатуры. Потому что двадцать лет делали одно и то же. Это не опыт. Это одногодичный опыт, повторённый двадцать раз.\n\nРынок сейчас меняется быстро: новые инструменты, новые риски, новые требования к аналитике. Тот, кто не вкладывает в себя, не отстаёт плавно. Он падает резко. И обычно замечает это, когда уже поздно.\n\nКатегорийный менеджмент, ценообразование, переговоры, работа с данными, понимание рынка поставщиков. Это не «сверх обязанностей». Это то, что отделяет закупщика, которому платят за результат, от закупщика, которого держат за привычку.\n\nСамое грустное не то, что такой человек не растёт. Самое грустное - он часто этого не замечает. Потому что отчёты сданы, KPI закрыт, план выполнен.\n\nХорошая работа исполнителя всегда выглядит как хорошая работа. Ровно до того момента, пока кто-то не покажет, как это могло выглядеть иначе.","terms":["negotiation","market","category","governance"],"topics":["function","negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/150"},{"id":149,"date":"2026-05-05","title":"к вопросу автоматизации закупок: все мы знаем про АБЦ и ХУЗ анализ (лень переключаться на другую раскладку).","summary":"к вопросу автоматизации закупок: все мы знаем про АБЦ и ХУЗ анализ (лень переключаться на другую раскладку). Он годится там, где производство понятно и не сильно вариативно.","summaryKind":"excerpt","text":"#юзфултип\nк вопросу автоматизации закупок: все мы знаем про АБЦ и ХУЗ анализ (лень переключаться на другую раскладку). Он годится там, где производство понятно и не сильно вариативно. Там, где производство кастомное, зависит от заказов клиента и имеет много видов сырья - это все будет тленом и херней. НО! Вернусь к вопросу автоматизации: иногда, когда как мне лень, можно закинуть запрос в ИИ и попросить сделать модель для дальнейшей донастройки под себя этого анализа. Автор сделал это за вас, поэтому ловите. Повторюсь -каждый настраивает ПОД СЕБЯ. Ибо чудны дела твои, Господи, в пределах отдельно взятого хозяйствующего субъекта.","terms":["ai","automation"],"topics":["ai","data"],"url":"https://t.me/notdandeliongirl/149"},{"id":148,"date":"2026-05-04","title":"Самая дорогая скидка в моей практике обошлась дороже, чем если бы мы заплатили по прайсу.","summary":"Самая дорогая скидка в моей практике обошлась дороже, чем если бы мы заплатили по прайсу. Схема знакомая.","summaryKind":"excerpt","text":"Самая дорогая скидка в моей практике обошлась дороже, чем если бы мы заплатили по прайсу.\n\nСхема знакомая. На переговорах обещаете объёмы, которых нет. Сроки оплаты, которые финансовый директор не согласует. Эксклюзив, который вы не имеете права давать. Поставщик верит. Даёт минус восемь процентов. Вы закрываете год с красивой экономией в отчёте.\n\nА потом объёмы не случаются. Оплата приходит позже. Эксклюзив тихо умирает в переписке.\n\nПоставщик это запоминает. Не в CRM. В голове.\n\nВ следующем году он либо поднимает цену обратно с запасом - чтобы было откуда давать вашу «скидку». Либо начинает придумывать причины: дефицит, очередь, приоритет другим клиентам. Либо просто перестаёт вас любить. А нелюбимому клиенту первому сообщают о форс-мажоре, последнему отгружают в пиковый сезон и никогда не идут навстречу, когда вам горит.\n\nЭто рыночная карма, которая из э битч.\n\nЕсть и личное измерение. Закупщик, которого поставщики знают как «обещалкина», перестаёт получать реальные предложения. Ему дают цены с буфером на ложь. Рынок маленький, особенно в металлургии или химпроме. Репутация ходит быстрее, чем вы думаете.\n\nСкидка, купленная ценой доверия - это кредит под очень неприятный процент.\n\nВопрос только в том, когда придёт счёт.","terms":["negotiation"],"topics":["negotiation"],"url":"https://t.me/notdandeliongirl/148"},{"id":146,"date":"2026-05-01","title":"Компании покупают ИИ как абонемент в фитнес-зал в январе.","summary":"Компании покупают ИИ как абонемент в фитнес-зал в январе. С той же верой.","summaryKind":"excerpt","text":"Компании покупают ИИ как абонемент в фитнес-зал в январе.\n\nС той же верой. С тем же финалом.\n\nTAdviser посчитал: больше половины российских компаний уже внедряют или планируют внедрять ИИ в закупки. Цифра красивая. Но никто не спрашивает, сколько из них реально что-то изменили.\n\nЯ спрошу.\n\nПотому что знаю этот январский сценарий наизусть. Бюджет выделен. Пилот запущен. Все верят, что к лету похудеем. А потом выясняется: данные грязные (читай - читмилы каждый день), архитектура не продумана (читай - план тренировок скачан с первого сайта в гугле), а цель вообще непонятно какая. Объём снять? Рельеф сделать? Просто весить меньше на совещании у гендиректора?\n\nПро тренера отдельная история. Вендор продал абонемент и пропал. Или остался, но говорит только про функционал, не про результат.\n\nВ закупках это выглядит так: ИИ внедрили в анализ цен. Данные поставщиков не стандартизированы. Номенклатура задвоена. Контракты в pdf-сканах из 2019 года. И система честно анализирует весь этот хаос. Старательно, быстро, с  красивым дашбордом.\n\nТрансформации нет. Есть дорогой калькулятор с интерфейсом.\n\nTAdviser фиксирует радужные ожидания. Я фиксирую другое: ИИ не делает вас стройнее, если вы продолжаете есть то же самое.\n\nАбонемент не виноват.\n(https://www.tadviser.ru/index.php/Статья:Интеллектуальный_эффект)","terms":["analytics","ai"],"topics":["ai","data"],"url":"https://t.me/notdandeliongirl/146"},{"id":145,"date":"2026-04-30","title":"помните, кстати, я писала, что сделала симулятор переговоров?","summary":"помните, кстати, я писала, что сделала симулятор переговоров? благодаря @Yuraberg там появилась возможность формирования стратегии по гарвардской школе.","summaryKind":"excerpt","text":"помните, кстати, я писала, что сделала симулятор переговоров? благодаря @Yuraberg там появилась возможность формирования стратегии по гарвардской школе.  Мои коллеги из БумПрома  - пример переговорной стратегия по поставщику ролевого сырья. Таким образом, цикл замкнулся - есть возможность прописать стратегию, а есть возможность потренироваться без подсказок.\n#юзфултип","terms":["negotiation"],"topics":["negotiation"],"url":"https://t.me/notdandeliongirl/145"},{"id":144,"date":"2026-04-30","title":"Давайте на этой неделе порефлексируем и потеребонькаем наше эго.","summary":"Давайте на этой неделе порефлексируем и потеребонькаем наше эго. «Ты просто позвони им и скажи, что дорого».","summaryKind":"excerpt","text":"Давайте на этой неделе порефлексируем и потеребонькаем наше эго.\n\n«Ты просто позвони им и скажи, что дорого».\nКаждый закупщик слышал это хотя бы раз. Некоторые слышат каждый квартал. Особые любимчики примерно каждый день.\n\nВ голове руководителя мы, наверное,  выглядим примерно так: берём трубку, говорим поставщику «дай дешевле», поставщик говорит «ладно, че», все довольны. Зачем вообще столько людей в этом отделе?\n\nЧто происходит на самом деле до того, как взять трубку:\n1) Анализ рынка - чтобы понять, реальна ли цена поставщика или он просто пробует. \n2) Оценка альтернатив - чтобы за спиной было что-то кроме воздуха. \n3) Понимание себестоимости поставщика - чтобы знать, куда давить и где он уже на нуле. \n4) Анализ нашей позиции - насколько мы для него важны, можем ли уйти, сколько это нам стоит.\n\nПереговоры - это последние десять минут. Всё остальное - это подготовка, которую никто не видит.\n\nИ вот после всего этого - да, берёшь трубку.\n\nИногда говоришь «дорого». Иногда молчишь и ждёшь. Иногда вообще не звонишь, а запускаешь тендер. Потому что понял: этот поставщик не подвинется, но рядом есть три других, которые очень хотят наш объём.\n\n«Просто позвони» - это примерно как сказать хирургу «просто порежь». Технически верно. По сути - мимо.","terms":["negotiation","market"],"topics":["negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/144"},{"id":143,"date":"2026-04-29","title":"Закупщик - единственный человек в компании, которого ругают за всё и не замечают ни за что.","summary":"Закупщик - единственный человек в компании, которого ругают за всё и не замечают ни за что. Поставщик поднял цену - закупки не удержали.","summaryKind":"excerpt","text":"Закупщик - единственный человек в компании, которого ругают за всё и не замечают ни за что.\n\nПоставщик поднял цену - закупки не удержали. \nПоставка задержалась - закупки не проконтролировали. \nКачество пришло не то - закупки не проверили. \nДефицит на рынке, санкции, курс валюты, форс-мажор у производителя - всё равно закупки. Они же главные содомиты!\n\nА когда цепочка работает как часы, поставки приходят в срок, цена держится второй год - это «ну, рынок просто хороший» или «поставщик попался нормальный».\n\nЯ как-то спросила коллегу из другого отдела:  а ты вообще отдубляешь, что закупки делают каждый день? Он подумал и сказал: «Ну, заказы размещаете».\nГод переговоров, стратегия, два поставщика выращены с нуля, риск дефицита закрыт заранее - «размещаете заказы».\n\nЕсть такая шутка про вратаря: когда он отбивает десять ударов подряд - это норма. Один пропустил - виноват. Закупщик живёт в этой шутке постоянно.\n\nСамый лучший закупщик - тот, которого не замечают. Потому что всё работает, ничего не горит, поставки приходят. Это и есть цель. И одновременно - профессиональная невидимость. Как бы не хотелось кому-то сделать так, чтобы его заметили однажды.\nУзнаёте себя?","terms":["negotiation"],"topics":["negotiation"],"url":"https://t.me/notdandeliongirl/143"},{"id":140,"date":"2026-04-25","title":"Мы учим закупщиков оценивать поставщиков по цене, качеству и срокам.","summary":"Мы учим закупщиков оценивать поставщиков по цене, качеству и срокам. А потом удивляемся, почему топовый поставщик по всем трём критериям внезапно подводит в самый неудобный момент.","summaryKind":"excerpt","text":"Мы учим закупщиков оценивать поставщиков по цене, качеству и срокам. А потом удивляемся, почему топовый поставщик по всем трём критериям внезапно подводит в самый неудобный момент.\n\nКлассическая ошибка: оценочный лист выглядит как анкета из журнала. Цена - 40%, качество - 30%, сроки - 20%, остальное - «прочее». Прочее - это как раз то, что потом убивает.\n\nФинансовая устойчивость поставщика никогда не попадает в верхние строчки матрицы. А зря. Поставщик с красивым прайсом и кассовым разрывом - это не поставщик. Это бомба с таймером, который вы не видите.\n\nВторое: оценка делается один раз при входе и потом хранится в папке «поставщики одобренные». Рынок меняется. Поставщик меняется. Папка - нет.\n\nТретье, и это любимое: субъективный балл выставляет один человек - тот, кто с этим поставщиком работает. Конфликт интересов встроен в процедуру архитектурно.\n\nЯ видела оценочные листы на восемь страниц с формулами и весами до третьего знака после запятой. Поставщик всё равно срывал поставку на третий месяц. Потому что в восьми страницах не было вопроса: «А кто ваш основной субподрядчик и в каком он состоянии?»\n\nХорошая оценка поставщика - это не про то, чтобы выбрать лучшего. Это про то, чтобы не пропустить опасного.\n\nА опасный, как правило, в вашей матрице стоит на втором месте с небольшим отрывом от первого.","terms":["market","supplier-risk"],"topics":["price","supplier"],"url":"https://t.me/notdandeliongirl/140"},{"id":139,"date":"2026-04-24","title":"Категорийную стратегию многие делают раз в год.","summary":"Категорийную стратегию многие делают раз в год. Потом кладут в папку.","summaryKind":"excerpt","text":"Категорийную стратегию многие делают раз в год. Потом кладут в папку. Папку не открывают.\n\nЗнаю, что  это есть в нескольких производственных компаниях. Красивый документ, матрица Кралича разложена по осям, категории расставлены. Только никто не может объяснить, почему конкретная позиция попала в «стратегические», а не в «узкие». Потому что так казалось.\n\nИИ здесь не волшебник. Но он хорош в одном: он не устаёт задавать неудобные вопросы:\n\n1. Берете черновик матрицы по категории. \n2. Закидываете в ИИ с описанием рынка, зависимостей, критичности для производства. \n3. Просите не согласиться со Вами. Именно так: «найди слабые места в моей логике размещения категории».\n\nОн находит. Не всегда правильно. Но достаточно часто, чтобы вы могли задуматься. \n\nДальше интереснее. \nОт матрицы к плану действий - это обычно пропасть. У закупщика есть позиционирование категории, но нет ответа: что конкретно делать в следующем квартале. \n\nИИ помогает сгенерировать гипотезы по тактике: \n\n1. где искать альтернативных поставщиков, \n2. какие рычаги переговоров релевантны для данного квадранта, \n3. где риски перекрывают экономию.\n\nЭто не стратегия. Это черновик. Но живой черновик лучше мёртвого документа в папке. \n\nХотя, если честно, папки никуда не делись. Просто теперь рядом с ними лежит распечатка диалога с ChatGPT. Тоже непрочитанная.\n#теория","terms":["negotiation","ai","category"],"topics":["ai","function","negotiation"],"url":"https://t.me/notdandeliongirl/139"},{"id":138,"date":"2026-04-22","title":"Почему нанимающие считают, что хорошая обувь не может стоить дёшево, а я могу?","summary":"Почему нанимающие считают, что хорошая обувь не может стоить дёшево, а я могу? Давеча услышала: вы стоите дорого.","summaryKind":"excerpt","text":"Почему нанимающие считают, что хорошая обувь не может стоить дёшево, а я могу?\n\nДавеча услышала: вы стоите дорого. Ну, и про возраст невзначай упомянули.\n\nЯ закупщик с двадцатью с лишним годами опыта. Я считала совокупную стоимость владения на подшипники, оборудование, услуги - на всё что движется и не движется. Я занималась оптимизациями и стратегяими на миллионы. И вот сижу и думаю: а себя-то я по ССВ считала?\n\nСейчас много разборов от карьерных консультантов - как себя продавать, стоит ли соглашаться на понижение, как быть гибкой. Как лучше упаковать свой опыт, как возраст 40+. Советы правильные. \nТолько один вопрос: а почему никто из них не предлагает посчитать рынку совокупную стоимость владения самого такого специалиста? \n\nНе стоимость потерь, если нанять дешёвого - об этом раз как пишет каждый второй консультант - а стоимость выгоды при найме крепкого недешёвого профессионала?\n\nЛюбой закупщик знает: дешёвая деталь не значит выгодная. Она значит - посмотрим через полгода. Деталь дороже, но с историей надёжности - это предсказуемый результат. Именно за это и платят, за гарантии.\n\nВ 25 лет ССВ специалиста - это гипотеза. В 40+ это факты (давайте опустим редких индивидов, которым поговорить и лицом посветить). Двадцать лет решений, ошибок, которые не повторишь, поставщиков, которых видишь насквозь, переговоров, из которых вышла победителем. Это не «опыт» в строчке резюме. Это ресурс с доказанным сроком службы.\n\nДорогой специалист (особенно в нашем возрасте, читай, с нашим опытом) - это не проблема. Это нормально. И не должно быть иначе.\n\nВопрос не в том, сколько мы стоим. Вопрос в том, умеет ли собственник и HR считать ССВ.","terms":["tco","negotiation"],"topics":["negotiation","price"],"url":"https://t.me/notdandeliongirl/138"},{"id":137,"date":"2026-04-21","title":"1.","summary":"1. Никто не хочет проверить, как работает скилл по сравнению КП?","summaryKind":"excerpt","text":"1. Никто не хочет проверить, как работает скилл по сравнению КП? Данные обезличить по поставщикам. Сам товар оставить\n2. Никто не хочет попробовать симулятор переговоров? 3 сессии \nМне нужен отзыв.","terms":["negotiation"],"topics":["negotiation"],"url":"https://t.me/notdandeliongirl/137"},{"id":136,"date":"2026-04-21","title":"Закупщики боятся не ИИ.","summary":"Закупщики боятся не ИИ. Они боятся выглядеть глупо рядом с ним.","summaryKind":"excerpt","text":"Закупщики боятся не ИИ. Они боятся выглядеть глупо рядом с ним.\n\nЯ видела это на конференциях. Человек с двадцатью годами в металлургии смотрит на демо ChatGPT и говорит: «Ну это всё равно не понимает специфики». Понимает. Не всё. Но достаточно, чтобы было неловко.\n\nСтрах здесь не про технологии. Он про статус. Закупщик с опытом - это человек, который знает то, чего не знают другие. Рынок поставщиков, скрытые риски, где реальная цена, а где красивая. Это годами накопленный актив. И вдруг приходит инструмент, который за двадцать секунд делает анализ рынка по категории.\n\n(Плохой, кстати. Но убедительно оформленный. Это отдельная проблема.)\n\nВторой страх - ответственность. ИИ предлагает решение. Закупщик его принимает. Если что-то идёт не так - виноват закупщик, а не нейросеть. Это честно. Но неприятно.\n\nЧто с этим делать? Ничего не делать с самим страхом. Он нормальный. Хуже - когда его нет совсем и человек доверяет ИИ без проверки.\n\nНастоящая экспертиза закупщика сейчас не в том, чтобы знать больше ИИ. А в том, чтобы понимать, где он врёт уверенно и красиво.\n\nЭто, кстати, не новый навык. Закупщики всегда умели отличать красивое коммерческое предложение от честного.","terms":["market","ai"],"topics":["ai","price","supplier"],"url":"https://t.me/notdandeliongirl/136"},{"id":134,"date":"2026-04-20","title":"Самый сложный переговорщик в закупках - не поставщик.","summary":"Самый сложный переговорщик в закупках - не поставщик. Это ваш коллега из производства.","summaryKind":"excerpt","text":"Самый сложный переговорщик в закупках - не поставщик. Это ваш коллега из производства.\nВы провели анализ, нашли альтернативу дешевле на 15%, всё готово. Приходите к директору производства. Он: «Мы работаем с Петровичем десять лет. Ничего менять не будем».\nЛомать через колено не работает. Работает другой разговор.\n«Да, Петрович надёжный. А если Степанович даёт ту же надёжность, но деталь по гарантии служит на год дольше и ССВ выходит дешевле - это уже не мой результат, это наш с тобой. Нам обоим запишут в показатели. Премия тоже общая».\nПроизводство слышит «надёжность» и «наш результат» - и разговор становится другим. Ещё лучше - позвать директора производства на финальные переговоры с новым поставщиком. Пусть сам задаст вопросы про качество и сроки. Его возражения снимет сам поставщик, не вы.\nВовлечённый стейкхолдер перестаёт быть противником и становится соавтором решения.\n\nС финансами язык другой. Они видят цифры этого квартала, вы им показываете горизонт.\n\n«При вашей марже это эквивалентно росту продаж на X%. Хотите, покажу расчёт на одном слайде?»\n\nЕсли финансовый директор сам произнёс цифру вслух - считайте, он уже на вашей стороне. Люди защищают то, что сами сформулировали.\nIT сопротивляются, потому что боятся интеграции и головной боли.\n\n«Мы уже проверили совместимость с вашей системой. От вас нужен один человек на две встречи. Больше ничего».\nИ ещё один лайфхак, который меняет всё: подключайте IT на этапе выбора поставщика, а не после подписания договора. Когда они участвовали в выборе - они же потом и помогают внедрить.\n\nКатегорийный менеджер не может быть единственным солдатом. Стратегия реализуется только тогда, когда у тебя есть союзники внутри - в производстве, в финансах, в IT. Твоя настоящая работа - не найти лучшего поставщика. А собрать команду, которая захочет с ним работать.\n#закупки #категорийныйменеджмент #внутренниестейкхолдеры #теория","terms":["tco","negotiation","category"],"topics":["function","negotiation","price"],"url":"https://t.me/notdandeliongirl/134"},{"id":133,"date":"2026-04-18","title":"Минутка развлечения для тех, кто юзает ИИ не для прогноза погоды.","summary":"Минутка развлечения для тех, кто юзает ИИ не для прогноза погоды. Промпт: На основании моего личного опыта общения за все время, назови персонажа, который на меня похож.","summaryKind":"excerpt","text":"Минутка развлечения для тех, кто юзает ИИ не для прогноза погоды.\nПромпт:\n\nНа основании моего личного опыта общения за все время, назови персонажа, который на меня похож. Только имя и поясни. И назови злодея-антигероя, который на меня похож и поясни почему».\nУ кого что? Я Гермиона Грейнджер и Миранда Пристли 🤦‍♂️","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/133"},{"id":132,"date":"2026-04-17","title":"Пост от Коданева (Бидзар).","summary":"Пост от Коданева (Бидзар). Примкните, собратья, к боли этой.","summaryKind":"excerpt","text":"Пост от Коданева (Бидзар). Примкните, собратья, к боли этой. С дичью, думаю, подобной, мы сталкивались все. \n\n\nчем больше я провожу аудитов закупок и запасов предприятий, тем больше удивляюсь некоторым вещам 🤯\n\n1️⃣ Когда компания решает начать резать косты, она начинает увольнять сотрудников, но при этом продолжает проводить многомиллионые закупки без тендеров от \"проверенных поставщиков\", переплачивая на этом десятки миллионов рублей\n\n2️⃣Переход в режим жесткой экономии по мнению многих CEO и CFO - это начать покупать дешевую туалетную бумагу и не доливать жидкое мыло в дозаторы; хранение купленных в кредит неликвидов на арендованных складах никого не интересует \n\n3️⃣В компании отдел закупок заставляют спрогнозировать цены на следующий год и обосновать методику по каждой товарной группе, при этом 45% поступающих заявок от подразделений идут с отметкой \"срочно\", похоже, что совсем никто не планирует свои потребности даже на 2-3 следующих месяца, все заявители живут в парадигме \"я человек простой, увидел, что материал закончился на складе, подал срочную заявку в отдел снабжения\"\n\n4️⃣Компании платят закупщику в регионе 55 тыс. руб. при полном отсутствии премий за результат, а потом удивляются, что он не приносит инициатив по экономии и ничего не предлагает, профессионально не развивается \n\n5️⃣Все руководители обожают обсуждать на высоких совещаниях и советах директоров \"цифровую трансформацию\" и искусственный интеллект, но действующая конфигурация 1С двенадцатилетней давности даже не позволяет создать заказ поставщику, то есть какие-то заявки приходят на почту, а потом какие-то материалы поступают на склад. Процесс не то, чтобы сквозной, а просто рваный в клочья\n\n6️⃣Все знают про ТСО, но все равно стремятся купить самое дешевое, как будто полностью игнорируя эксплуатационные затраты, энергоэффективность, ремонтопригодность\n\n7️⃣Мы будем согласовывать любой договор поставки 2,5 месяца, \"мудрые кроты\" (согласующие) будут круг за кругом смотреть на него и вносить правки, при этом если случится факап и поставщик после получения аванса пропадет с  радаров, то все равно обвинят и уволят сотрудника отдела закупок, который запустил договор; со всех согласовантов и \"взятки гладки\", они ни при чем, у них ноль ответственности за результат по договору","terms":["tco","turnover"],"topics":["inventory","price"],"url":"https://t.me/notdandeliongirl/132"},{"id":121,"date":"2026-04-14","title":"Переговоры о цене - это самое простое, что можно сделать с категорией.","summary":"Переговоры о цене - это самое простое, что можно сделать с категорией. И чаще всего - самое малоэффективное, если речь про стратегического поставщика.","summaryKind":"excerpt","text":"Переговоры о цене - это самое простое, что можно сделать с категорией. И чаще всего - самое малоэффективное, если речь про стратегического поставщика.\nОбъясню:\nПоставщик, которого сложно заменить, уже встроился в вашу цепочку. Он знает вашу спецификацию, ваши объёмы, ваши сроки. Каждый раз давить его по цене - это бороться за 3-5%, разрушая отношения, от которых зависит надёжность поставки.\nНастоящие деньги в другом месте.\nСовместная разработка продукта: вы приходите к поставщику не с требованием скидки, а с вопросом «как нам вместе снизить себестоимость этой позиции?». Иногда достаточно изменить спецификацию, чтобы поставщик сократил отходы производства - и поделился экономией с вами. Никаких переговоров. Просто общая задача.\nСовместные инвестиции: поставщик не может автоматизировать линию без гарантированного объёма, вы не можете гарантировать объём без стабильной цены. Долгосрочный контракт решает оба вопроса - и даёт поставщику основание инвестировать, а вам - получить сниженную цену через два года.\nОбщая цифровая платформа: когда поставщик видит ваш прогноз в реальном времени, он сокращает страховой запас и lead time. Это не про скидки - это про совокупную стоимость владения, которая снижается у обоих.\nКатегория - это не контракт. Это отношения, которые можно строить или просто эксплуатировать. Результаты в этих двух случаях разные.\n#закупки #категорийныйменеджмент #стратегическиезакупки #теория","terms":["tco","leadtime","safety-stock","negotiation","category"],"topics":["function","inventory","negotiation","price"],"url":"https://t.me/notdandeliongirl/121"},{"id":117,"date":"2026-04-13","title":"Дорогие товарищи, у меня есть канал на Linkedin и в последнее время посты там и здесь не дублируются.","summary":"Дорогие товарищи, у меня есть канал на Linkedin и в последнее время посты там и здесь не дублируются. Хотите, чтобы я делала краткую выжимку?","summaryKind":"excerpt","text":"Дорогие товарищи, \nу меня есть канал на Linkedin и в последнее время посты там и здесь не дублируются. Хотите, чтобы я делала краткую выжимку? В LI чаще пишу про ИИ в закупках - где, как применять. Инфографика там, промпты.\n\nЧто еще из новостей и достижений:\n1. Доделала аналитический бот по FMCG. Что он делает: выдает последние новости (от недели до месяца, дальше новости нерелевантны) по выбранной отрасли и регуляторку. При необходимости может дать влияние на вашу отрасль (например, как новости молочки могут повлиять на гофру)\n2. Сделала скилл по выбору поставщика по ССВ с авто написанием письма поставщикам (вопросы, разночтения) без отправки на почту. Фактически скилл-агент. Более простая версия ссылкой ранее (допилила промпт, чтобы скопировать и отправить поставщику) - это уже полуавтоматический вариант\n3. Сделала симулятор переговоров по 6 сценариям с моим опытом переговоров. Вот сюда готова взять на ОС 2-3 человек. На каждого по сессии\n\nКонечно, хочется с вами что-то обсудить еще))) Может, о чем-то рассказать? А то я пока, если честно, больше в разных продуктах и проектной работе. А поговорить хочется 🤣🤌","terms":["tco","negotiation","ai"],"topics":["ai","negotiation","price"],"url":"https://t.me/notdandeliongirl/117"},{"id":113,"date":"2026-04-11","title":"Если вы много и часто пользуетесь ИИ для проектов, написания кода / программ, используете как свою базу знаний, не поленитесь и просите иногда ИИ вас оценить по показателям: 1.","summary":"Если вы много и часто пользуетесь ИИ для проектов, написания кода / программ, используете как свою базу знаний, не поленитесь и просите иногда ИИ вас оценить по показателям: 1. Зрелость и линейность рассуждений 2.","summaryKind":"excerpt","text":"Если вы много и часто пользуетесь ИИ для проектов, написания кода / программ, используете как свою базу знаний, не поленитесь и просите иногда ИИ вас оценить по показателям:\n1. Зрелость и линейность рассуждений\n2. Инновации \n3. Профессионализм\n4. Сильные и слабые стороны\n5. Точки роста\n6. Цифровая зрелость \n7. Софт скиллы\nОбязательно пишите «честный и справедливый   ответ без комплиментов»\n\nПоверьте, там, где вы думаете, что вы молодец, ИИ посмотрит на вас под другим углом.\n#теория","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/113"},{"id":112,"date":"2026-04-09","title":"Автоматизация расчета ССВ","summary":"Анна описывает полуавтоматический инструмент расчета ССВ, учитывающий цену, условия оплаты, доставку и дальнейший анализ через AI.","summaryKind":"summary","text":"Немного автоматизации расчета ССВ\nДрузья, в свое время у меня был конкурентный лист, учитывающий цены, условия оплаты, доставку и так далее. захотелось его как-то проапргрейдить и сделать в полуавтоматическом режиме с формированием промпта для дальнейшего анализа в ИИ. когда писала пост, вспомнила, что забыла указать, что цены без НДС в самом файле. \nВо всем остальном повторю еще раз: \n- все компании без исключения находятся на разных этапах своей жизни, развития и автоматизации. \n- Все закупщики разные. \n- Политики разные. \n- Размеры бизнесов разные. \nПоэтому и инструменты разные. \nДоступ бесплатный или 5 дней или 15 расчетов. если вы не успели - напишите в комменты. продлю акцию)) , ну и вообще соберу ОС. Тыкать сюда https://www.procuresense.ru/supplier/\n#ИИвзакупках #расчетССВ #автоматизация","terms":["tco","deferral","ai","automation"],"topics":["ai","data","finance","negotiation","price"],"url":"https://t.me/notdandeliongirl/112"},{"id":110,"date":"2026-04-08","title":"В продолжении поста и в довесок сюда Написала мне коллега вопрос под моим постом о стадиях автоматизации и зрелости закупщика, делала ли я автоматизацию анализа рынка.","summary":"В продолжении поста и в довесок сюда Написала мне коллега вопрос под моим постом о стадиях автоматизации и зрелости закупщика, делала ли я автоматизацию анализа рынка. По анализу поставщика у меня есть промпт (список вопросов по сути), но мне не нравится, что катастрофически не хватает данных; объем рынка, доли, я уже не говорю про динамику).","summaryKind":"excerpt","text":"В продолжении поста и в довесок сюда \n\nНаписала мне коллега вопрос под моим постом о стадиях автоматизации и зрелости закупщика, делала ли я автоматизацию анализа рынка.\nПо анализу поставщика у меня есть промпт (список вопросов по сути), но мне не нравится, что катастрофически не хватает данных; объем рынка, доли, я уже не говорю про динамику). По известному рынку, я могу дать ссылки на свои материалы, А вот по не известному вопрос остается открытым.\n\nДействительно, а где взять данные? Что делать?\nМое предложение ниже. Применимо не для всех рынков, но для потребтоваров, FMCG  вполне \n\nесли вы дадите алгоритм, как считать доли рынка и объемы (например, есть поставщик А, вы знаете его объем производства, знаете плюс-минус , что цены варьируются в рамках 5% по поставщикам, то можно сделать принцип простой экстраполяции - оценка выручки в Спарке и выведение зависимости по объему). Но это очень примерно. Есть вариант взять старые маркетинговые отчеты - за минус 3 года они бесплатные - и экстраполировать через оценку отрасли и анализ поставщика в Спарке. Но это тоже примерно. Поэтому -имхо - ИИ не волшебник и оценить объемы без какой-то базы он не может корректно. Будут допущения. Минимум два пути я вам указала, но, опять же, эти пути имеют большие допуски и не годятся для некоторых закрытых рынков. И по традиции - чем больше источников вы дадите в промпте оценивать и искать и запрашивать методику расчетов, тем чище может быть результат.\n#теория","terms":["price-change","market","ai","automation"],"topics":["ai","data","negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/110"},{"id":109,"date":"2026-04-06","title":"Продолжим диалог про категорийный менеджемент.","summary":"Продолжим диалог про категорийный менеджемент. Самый стратегически важный поставщик в моей практике поставлял на 50 тысяч рублей в год.","summaryKind":"excerpt","text":"Продолжим диалог про категорийный менеджемент. \nСамый стратегически важный поставщик в моей практике поставлял на 50 тысяч рублей в год. Специфический уплотнитель для оборудования, один производитель в Европе, срок изготовления - шесть недель. Без него линия вставала с миллионными потерями. Под него мы держали запас на полгода.\nА в другой компании у коллег  был поставщик металла на 40 миллионов, с которым торговались каждый квартал. Поставщиков металла на рынке двадцать штук, были варианты для действий.\nМатрица Кралича - инструмент из 1983 года, который до сих пор не устарел. Делит все категории закупок по двум осям: насколько это влияет на прибыль и насколько сложно это достать. Получается четыре квадранта - и для каждого своя логика.\n1) Рутинные (Non-critical) - дёшево и легко: автоматизируй, не трать время переговорщика. \n2) Баланс (Leverage) - дорого и легко: вот где работают жёсткие тендеры и смена поставщика. \n3) Узкие места (Bottleneck) - дёшево, но достать сложно: это мой уплотнитель. Здесь не торгуются - здесь строят отношения и держат запас. \n4) Стратегические (Strategic)  - дорого и сложно: партнёрство, долгосрочные контракты, зависимость взаимная.\nДорогой не значит стратегический. Дешёвый не значит незначительный.\nБольшинство компаний делают ровно наоборот - давят там, где нельзя, и не замечают того, что реально останавливает производство. Это не злой умысел. Просто никто не сидел и не рисовал матрицу.\nНапоминаю, что матрица есть тут https://procuresense.ru/index.html#masterclasses\n#теория","terms":["negotiation","category"],"topics":["function","negotiation"],"url":"https://t.me/notdandeliongirl/109"},{"id":107,"date":"2026-04-02","title":"Интересная статья вышла.","summary":"Интересная статья вышла. How AI Killed Information Asymmetry in B2B Procurement, PYMNTS.com, 30 марта 2026 \" ИИ меняет сам процесс B2B-закупок: команды теперь способны самостоятельно — без участия продавцов — проводить анализ рынка, сравнивать поставщиков, оценивать цены и моделировать переговорные сценарии.","summaryKind":"excerpt","text":"Интересная статья вышла. How AI Killed Information Asymmetry in B2B Procurement, PYMNTS.com, 30 марта 2026\n\"\nИИ меняет сам процесс B2B-закупок: команды теперь способны самостоятельно — без участия продавцов — проводить анализ рынка, сравнивать поставщиков, оценивать цены и моделировать переговорные сценарии. То, на что раньше уходили недели, теперь делается за часы. Закупщики часто принимают решение ещё до того, как у продавца появляется шанс выйти на контакт. Согласно данным PYMNTS Intelligence, 75% компаний уже рассматривают применение ИИ в закупках. Формируется модель «нулевого касания» (zero-touch procurement), где ИИ фактически ведёт оценку поставщиков в автономном режиме\n\".\nЗвучит красиво, да? А я вот попыталась найти информацию, а что будет если у поставщика нет открытого ценообразования? В статье только общий тезис: поставщики, которые не предоставляют структурированные данные — чёткое ценообразование, стандартные спецификации, метрики — просто не попадают в автоматизированные оценки ИИ-систем. Окей. \nА теперь про российский рынок - с его закрытыми прайсами, скрытыми комиссиями и перламутровыми пуговицами в спецификации. До прозрачности, при которой ИИ реально работает - нам ещё идти и идти.\nПросто не наше пока будущее это.\nНа теме ИИ очень модно сейчас получать охваты - неважно, о чем пишет или говорит человек, какие материалы предоставляет. Выглядит аж дыхание замирает, а внутрянку никто не оценивает. Я задала недавно вопрос одному автору, который несколько раз в день выкладывает посты - классная преза по дашбордам, а где в ней пункт про то, как вы делаете проверку данных, если они, допустим, не структурированы, есть дубли и тд? Ответа не последовало.....\nПотому что большинство таких постов про то, что можно сделать с ИИ в идеальных условиях. А не про то, что происходит, когда данные грязные, логика изощреннее, переговоры сложнее и цена ошибки - не красивый скриншот, а миллионы.","terms":["negotiation","market","analytics","ai"],"topics":["ai","data","negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/107"},{"id":102,"date":"2026-04-01","title":"BATNA перед переговорами","summary":"Анна объясняет BATNA как конкретный план Б до переговоров: что компания будет делать, если договориться не получится.","summaryKind":"summary","text":"Знаете ли вы свою БАТНА перед переговорами? Большинство закупщиков  нет.\nБАТНА - это русская транслитерация английской аббревиатуры BATNA: Best Alternative To a Negotiated Agreement. Лучшая альтернатива переговорному соглашению. Проще говоря: что вы будете делать, если договориться не получится. Не «подумаем», не «найдём кого-нибудь» - а конкретный план Б, с цифрами и сроками.\nЗачем это нужно? Потому что без БАТНА вы не ведёте переговоры - вы соглашаетесь. Поставщик не двигается по цене, вы давите, он держится - и в итоге берёте его условия. Просто потому что в голове нет ответа на вопрос «а что, если мы не договоримся?»\nКак построить свою БАТНА до переговоров:\n\nЕсть ли другой поставщик - и на каких условиях реально, а не теоретически?\nМожно ли отложить закупку - и что это стоит бизнесу?\nЕсть ли альтернативный продукт или решение?\n\nА если продукт монопольный и альтернатив нет? Тогда БАТНА слабая - и это надо признать честно, а не делать вид, что она есть. Но даже здесь есть варианты: разработка альтернативного поставщика, изменение спецификации, работа с внутренним заказчиком над снижением зависимости. Это долго - но это и есть настоящая работа с категорией.\nКто первый разобрался в своей позиции - тот и ведёт переговоры. Второй просто реагирует.\n#закупки #переговоры #БАТНА\n#теория","terms":["monopoly","negotiation"],"topics":["negotiation","supplier"],"url":"https://t.me/notdandeliongirl/102"},{"id":101,"date":"2026-03-30","title":"Большинство закупщиков не занимаются закупками.","summary":"Большинство закупщиков не занимаются закупками. Они обрабатывают заявки, как бы вы не сопротивлялись этому определению.","summaryKind":"excerpt","text":"Большинство закупщиков не занимаются закупками. Они обрабатывают заявки, как бы вы не сопротивлялись  этому определению. Да, и запрос скидок и думать, на какой срок проводить тендер, тоже является обработкой заявки. Пришла потребность - нашли поставщика  - провели переговоры, проанализировали рынок……-согласовали цену - выдали заказ. Повторить. \nКатегорийный менеджмент - когда вы делаете шаг назад и смотрите на всю категорию целиком. Что покупаем? У кого? Почему? Каков рынок? Есть ли альтернативы? \nЗачем это нужно? Потому что без этого вы всегда будете реагировать, а не управлять. Поставщик поднял цену – каждый раз обсуждаете. Появился дефицит  / сломалась логистическая цепочка– тушите пожары. Рынок изменился – вы идете за ним, а не принимаете меры превентивно. \nС чего начать:\n1.     Сегментируйте расходы по категориям - не по поставщикам, а по тому, что покупаете\n2.     Проанализируйте каждую категорию: объём, поставщики, риски, тренды. Если надо – объедините СКЮ там, где это необходимо \n3.     Определите позицию: где вы сильны, где уязвимы\n4.     Поставьте цель на 12-18 месяцев - не «снизить цену», а конкретно: что изменить в структуре поставщиков, в условиях, в рисках, как посчитать ССВ, как ранжировать поставщиков\n5.     Запланируйте действия - и пересматривайте регулярно. Это не разовая акция. Категорийная стратегия устаревает быстро, если её не обновлять. \nЕсли у вас нет стратегии по категории -значит, она есть у поставщика. Или нет. Тогда поздравляю – у вас немножечко хаос))\n#теория","terms":["tco","negotiation","category"],"topics":["function","negotiation","price"],"url":"https://t.me/notdandeliongirl/101"},{"id":100,"date":"2026-03-27","title":"В течение пары дней планирую серию постов про категорийный менеджмент.","summary":"В течение пары дней планирую серию постов про категорийный менеджмент. Было ли интересно?","summaryKind":"excerpt","text":"В течение пары дней планирую серию постов про категорийный менеджмент. Было ли интересно?\nИ вообще что интересно?\nВот, к примеру, я позавчера провела вебинар для аналитиков по ИИ в аналитике - что такое ИИ, как он сделан, за и против, что лучше использовать в цепочке «поговорил с клиентов, сделал ТЗ - создал даш - выводы - презу- продал»","terms":["ai","category"],"topics":["ai","function"],"url":"https://t.me/notdandeliongirl/100"},{"id":98,"date":"2026-03-27","title":"итоги тестирования 7 нейромоделей на одной задаче.","summary":"итоги тестирования 7 нейромоделей на одной задаче. Думаю, будет полезно.","summaryKind":"excerpt","text":"итоги тестирования 7 нейромоделей на одной задаче. Думаю, будет полезно. Напоминаю задачу-проанализируй массив данных, сделай дашборд на реальных данных, выводы, рекомендации и инсайты. Опционально (в рейтинг не попало) презентация. #иивзакупках","terms":["analytics"],"topics":["data"],"url":"https://t.me/notdandeliongirl/98"},{"id":96,"date":"2026-03-25","title":"Часть 2 Многие считают, что единственный свет в окне - это Chat GPT.","summary":"Часть 2 Многие считают, что единственный свет в окне - это Chat GPT.","summaryKind":"excerpt","text":"Часть 2\nМногие считают, что единственный свет в окне - это Chat GPT. И в транскрибации русской речи тоже (никому же не нужно объяснять, что в разы ускоряет вас именно надиктовывание ваших мыслей в ИИ- как будто это ваш личный секретарь?)\nТак вот - мое мнение, которое я решила проверить, основываясь на результатах исследований, любезно срезюмированных мне нейромоделями, что ГигаЧат сильнее (сравниваю именно эти 2 модели):\n1) очевидность по самим моделям - Чат ГПТ обучен изначально на Английском языке с Английским контекстом. Русский язык для него- один из языков. Гига Чат же обучался как раз в русской среде \n2) Чат ГПТ в движке Whisper более качественен, убирая шумы, бэканье и так далее. Salute, соотвественно меньше\n3) ГигаЧат лучше понимает контекст в рамках культурной среды, ставит верные падежи в терминах. Чат ГПТ может транскрибировать «в соответствие с договора»\n4) Чат ГПТ фактически причесывает вашу речь, Гига Чат понимает именно то, что было сказано\n\nЦитата от нейросети: \nChatGPT — лучший в мире переводчик смыслов. Но GigaChat — лучший в мире слушатель русской речи. Если вам нужен красивый текст «по мотивам» — берите GPT. Если вам нужны факты, фамилии и термины без искажений — берите того, кто на этом языке живет","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/96"},{"id":95,"date":"2026-03-25","title":"Прерву серию running test отступлением: Почему много в канале ИИ и какой транскрибатор лучше?","summary":"Прерву серию running test отступлением: Почему много в канале ИИ и какой транскрибатор лучше? Часть 1 1.","summaryKind":"excerpt","text":"Прерву серию running test отступлением:\nПочему много в канале ИИ и какой транскрибатор лучше?\nЧасть 1\n1. Почему я пишу меньше про закупки и больше про ИИ? \n- Без ИИ вы не сможете ничего делать в ближайшем будущем- скорость принятия решений будет увеличиваться кратно\n- Если вы не знаете, где, как и зачем применять модель, то результат будет соответсвующим","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/95"},{"id":93,"date":"2026-03-24","title":"Perplexity 1) скорость создания 1 версии 3,5 минуты.","summary":"Perplexity 1) скорость создания 1 версии 3,5 минуты. 2) с первого раза указал цифры от балды, на генерацию 2 версии ушло снова 3.5 минуты.","summaryKind":"excerpt","text":"Perplexity \n1) скорость создания 1 версии 3,5 минуты. \n2) с первого раза указал цифры от балды, на генерацию 2 версии ушло снова 3.5 минуты. И снова неверно. Итого я потратила 7 минут + справочно еще минут 10 на попытки вытащить реальные цифры. Бесполезно. Он ушел в отрыв и сказал, что файл не читается\n3) готового файла нет -только код для вставки в блокнот\n4) визуализация норм, на смене цветов впадает в ступор\n5) Анализ данных - указал хотя бы виды товаров. НО снова без цифр. \nOverall - основная задача Perplexity все же быть лучшим поисковиком информации с цитатами и ссылками. По различным оценкам (и я с ними согласна) он в этом лучший. Надежды на то, что он заменит ChatGPT, Claude, Gemini - утопия","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/93"},{"id":91,"date":"2026-03-23","title":"ChatGpt.","summary":"ChatGpt.","summaryKind":"excerpt","text":"ChatGpt.\n1) Скорость создания дашборда - 10 мин\n2) плюс - все цифры корректные с первого раз, можно скачать прототип прям в нужном формате  - уже готовом, со всеми метриками\n3) Понял с первого раз без дополнительных вопросов, что мне нужно (то есть никаких уточнений)\n4) Визуализация норм, стандартная (спойлер, я после пробовала играться цветами по заданному коду - справился на \"ура\")\n5) Анализ данных -  меньше воды, чем у ГигаЧат, но без цифр. Не очень хорошо. 4ка.\nOverall - один огромный плюс за дашборд с первого раза в нужном формате","terms":["analytics","ai"],"topics":["ai","data"],"url":"https://t.me/notdandeliongirl/91"},{"id":89,"date":"2026-03-22","title":"Начнем с аутсайдера - \"отечественного\" (с).","summary":"Начнем с аутсайдера - \"отечественного\" (с). Но для начала немного вводных: файл, 600 строк, формат csv.","summaryKind":"excerpt","text":"Начнем с аутсайдера - \"отечественного\" (с). Но для начала немного вводных: файл, 600 строк, формат csv.  Промпт везде одинаковый (создай прототип дашборда с реальными цифрами из файла во вложении в формате .html. нужны основные метрики, графики и прочее) - весь промпт писать лень.  Второй вопрос - по дашборду сделай анализ инсайтов, аномалий, рекомендаций. Как итог через несколько дней отправлю сводную таблицу с оценками, но пока:\n1) Гига-чат не понимает с первого раза, что от него хотят, то есть промпт должен быть прямой как палка - конкретика и только. Стиль ГигаЧат - тупой исполнитель. Как прибили - так и держится.\n2) Время исполнения кода и обработки - 3 мин 5 сек. (повторюсь, пока мы просто проводим тест, все вводные показатели будут позже)\n3) Корректность данных (с учетом запроса \"на реальных данных реальные цифры) - полное говно. Вообще от балды. Чтобы получить реальные цифры, нужно задать вопрос с уточнениями (на третий раз \"паровозик, который смог\")\n4) Визуализация на троечку, но расположение карточек и графиков верное (слева направо, сверху-вниз).\n5) Неудобно, что не выдает сразу файл html и приходится вставлять код в блокнот. Хочется сразу в окне диалога\n6) Анализ дашборда довольно слабый - нет цифр, довольно очевидные вещи, нет понимания, о каких товара идет речь \nTBC....","terms":["analytics"],"topics":["data"],"url":"https://t.me/notdandeliongirl/89"},{"id":88,"date":"2026-03-21","title":"Завтра начну выкладывать running test на разных нейромоделях по формированию дашбордов с моими комментами.","summary":"Завтра начну выкладывать running test на разных нейромоделях по формированию дашбордов с моими комментами. а еще.....","summaryKind":"excerpt","text":"Завтра начну выкладывать running test на разных нейромоделях по формированию дашбордов с моими комментами. а еще..... coming soon","terms":["analytics"],"topics":["data"],"url":"https://t.me/notdandeliongirl/88"},{"id":87,"date":"2026-03-20","title":"Первая любовь не лучшая.","summary":"Первая любовь не лучшая. Просто первая, с которой что-то получилось.","summaryKind":"excerpt","text":"Первая любовь не лучшая. Просто первая, с которой что-то получилось.\n      Помнишь первое свидание? Она ответила именно то, что ты хотел услышать- интересно, где-то интригующе. Всё - ты пропал. Она стала эталоном. Все остальные с ней сравниваются - и почти всегда проигрывают. Не потому,что хуже. А потому что не она. Мы не выбираем осознанно - мы влюбляемся.\n      Другие - следующие - отличаются не умом, а характером. Одна говорит много, рассуждает вслух. Другая - коротко, чётко, без лирики. Третья при любой неопределённости говорит «извини, ты прав» и идёт дальше. И это не хорошо и не плохо - это просто разные характеры, которые по-разному совпадают с твоим.\n       Проблема начинается, когда перестаёшь замечать недостатки. Когда говоришь всем «только с ней, она лучшая» - а на деле просто привык. Когда плохие отношения объясняешь чем угодно, только не тем, что она просто тебе не подходит в этот момент твоей жизни.\n        И ещё: они меняются - развиваются и деградируют. То, что год назад было сильной стороной – уже не интересно. То, что казалось слабостью – изменилось в лучшую сторону. Если ты давно не смотрел на других – это плохо. Нужно срочно что-то менять. Будет ли это изменой? Вряд ли. ты просто начнешь это делать с двумя-тремя одновременно и смотреть, кто лучше. \n       Любимая - это нормально. Единственная -это уже зависимость.\n ПС Кстати, я про нейросети. Хотя, если честно - разница совсем небольшая 😜","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/87"},{"id":84,"date":"2026-03-17","title":"Быстрый дашборд как рабочий инструмент","summary":"Анна показывает прагматичный подход к визуализации: иногда быстрый HTML-дашборд или карточки для руководителя дают ценность быстрее, чем долгий проект BI.","summaryKind":"summary","text":"Если нужно прям очень быстро создать дашборд для руководителя / быстро добавить в презу карточки - по времени около 1,5 минут - \nзагрузили файл, промпт \"сделай.... в формате html, карточки такие-то, графики такие-то\".\nКонечно, можно запросить \"напиши инсайты\" / \"сделай презу\" / \"напиши красиво с таблицей и выводами\" (на сегодня лучший в этом плане Claude, имхо). Но так быстрее - не требует глубокой аналитики, открывается быстро и везде и весит очень мало. \nКакое количество курсов сейчас есть по \"создать дашборд с нуля\"? \nКакое количество компаний сейчас любят смотреть все в дашбордах?\nВот как-то так. #юзфултип","terms":["analytics","ai"],"topics":["ai","data"],"url":"https://t.me/notdandeliongirl/84"},{"id":83,"date":"2026-03-16","title":"Очень часто многие закупщики работают по наитию - они нигде не учились, ничего не читают, не изучают.","summary":"Очень часто многие закупщики работают по наитию - они нигде не учились, ничего не читают, не изучают. Кого-то просто бросили в воду и сказали выплывать самому, кого-то перевели на эту должность из-за реорганизации, а кто-то добровольно решил вступить на эту стезю.","summaryKind":"excerpt","text":"Очень часто многие закупщики работают по наитию - они нигде не учились, ничего не читают, не изучают. Кого-то просто бросили в воду и сказали выплывать самому, кого-то перевели на эту должность из-за реорганизации, а кто-то добровольно решил вступить на эту стезю. \nМеня когда-то - очень давно - бросили в воду и сказали «выплывешь - оставим. Не выплывешь- уволим». Я все тогда начинала делать сама- строить отдел закупок в одном лице на производстве, о котором ничего не знала; искать поставщиков; вести переговоры; узнавать Incoterms, планировать производство и многое-многое другое. Я смогла в том числе и потому, что у меня были люди рядом, готовые меня обучать - что такое производство, склад, логистика, финансы, экономика.\nТакая возможность есть не у всех, поэтому иногда я буду выкладывать какие-то обучалки сюда. Если есть пожелания - велком в комменты. \n \nПолезный инструмент на сегодня вот такой\n\nHttp://www.procuresense.ru/checklist-v2.pdf\n#юзфултип","terms":["negotiation"],"topics":["negotiation"],"url":"https://t.me/notdandeliongirl/83"},{"id":81,"date":"2026-03-14","title":"Компания Procol (гусары, не ржать!) запустила Клару - систему ИИ-агентов, которая убьет обычных закупщиков и оставит только оркестрантов (то, о чем я писала парами постов ранее).","summary":"Компания Procol (гусары, не ржать!) запустила Клару - систему ИИ-агентов, которая убьет обычных закупщиков и оставит только оркестрантов (то, о чем я писала парами постов ранее). Мир сейчас ускоряется кратно и если не начать использовать это и учиться, вы рискуете остаться на перроне и махать поезду.","summaryKind":"excerpt","text":"Компания Procol (гусары, не ржать!) запустила Клару - систему ИИ-агентов, которая убьет обычных закупщиков и оставит только оркестрантов (то, о чем я писала парами постов ранее). Мир сейчас ускоряется кратно и если не начать использовать это и учиться, вы рискуете остаться на перроне и махать поезду. \nСейчас компаниям как никогда надо обратить внимание на специалистов, которые умеют перерабатывать функцию в нечто большее- и это уже не только про влияние на прибыль. Это влияние вообще на жизненный цикл компании и скорость принятия решения. \nОсобенно это касается небольших компаний, где закупщик часто в единственном лице. Или в компаниях, где сократилась прибыль и уже принимаются решения о сокращении- чем выше ваша многозадачность за счет использования ИИ и понимание возможностей автоматизации, тем выше ваша ценность. \nПС кстати, я-таки решила создать несколько курсов (нет, ну а что? В конце-концов, я действительно многое знаю) \n#закупки #снабжение #иивзакупках","terms":["ai","automation"],"topics":["ai","data"],"url":"https://t.me/notdandeliongirl/81"},{"id":80,"date":"2026-03-13","title":"Закупки как источник рыночной аналитики для бизнеса","summary":"Анна пишет, что закупки должны работать в связке с коммерческим блоком: закупщики видят рынок, поставщиков, риски, инвестиционные тренды и могут давать бизнесу более точную картину будущей цены.","summaryKind":"summary","text":"Почему я считаю, что нужно использовать закупщиков в тесной связке с коммерческим блоком как можно более активно?\n1)     Закупщики знают и умеют анализировать рынок, что на что влияет, куда движется, какие риски есть\n2)     Они общаются с компаниями из разных сфер, соответственно, они больше в рынках, чем сбыт по направлению \n3)     Их способности к аналитике и умения подмечать взаимосвязи выше, чем у коммерческого блока (да простят меня не закупщики))\n4)     Закупщики более глубоко используют ИИ в своей работе, потому что у них часто нет бэкофиса на «сделай мне отчет». Все приходится делать самим\n5)     В переговорах с клиентами закупщики могут принести огромную ценность, ибо будут говорить с коллегой на одном языке\n6)     И т.д. \nТеперь пример (кстати, из реальной жизни). Необходимо было понять, что будет происходить с некоторыми сырьевыми позициями, на что будет больше ориентирована экономика страны.  По итогам ПЭМФ был проведен анализ планируемых инвестиций в отрасли. Было отмечено, что нужные нам сырьевые позиции находятся внутри этих отраслей (отлично). Забегая вперед, в совокупности с анализом рынка это дало лучшее понимание, какой будет ориентир по цене на 2026 год. \nКак побочный эффект – сделали свод по отраслям, по клиентам внутри отраслей. Отдали продавцам с пометками, куда двигаться дальше, на каких клиентов обращать внимание. \nИ, в общем, к чему это я: я всегда за командную работу. Не тащите все в свою закупочную норку. Очень часто ваши знания, умения, какие-то инсайты могут оказать существенное влияние на результаты бизнесы (да, не вашего подразделения, но вы же помните, что работаете все вместе, да?) #закупки #снабжение #ВЭД #анализрынка","terms":["negotiation","market","ai"],"topics":["ai","negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/80"},{"id":77,"date":"2026-03-12","title":"В одном из сообществ задали вопрос: делал ли кто-то сравнение в ИИ по позициям закупаемой номенклатуры?","summary":"В одном из сообществ задали вопрос: делал ли кто-то сравнение в ИИ по позициям закупаемой номенклатуры? Во вложении 2 модели.","summaryKind":"excerpt","text":"В одном из сообществ задали вопрос: делал ли кто-то сравнение в ИИ по позициям закупаемой номенклатуры? Во вложении 2 модели. Обе справились по-разному. \nКонечно, есть модели в Экселе, которые позволяют загонять данные туда и сравнивать и в чем-то даже это удобнее для защиты информации (опять же, никто не запрещает обезличивать данные перед отправкой). Но посыл понятен, использовать для анализа можно, если только прописать верный алгоритм и промпт и самое главное, проверить результат (помним, ИИ не человек, он может не понять вас и может сгаллюцинировать)","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/77"},{"id":76,"date":"2026-03-11","title":"Апдейт: Сижу на этом вебинаре.","summary":"Апдейт: Сижу на этом вебинаре. Кратко- Вы можете все прочитать в моем коротком посте днем ранее🤦‍♂️ 4х часовой тренинг у Сергея 8900 рублей будет стоить.","summaryKind":"excerpt","text":"Апдейт: Сижу на этом вебинаре. Кратко- \nВы можете все прочитать в моем коротком посте днем ранее🤦‍♂️\n4х часовой тренинг у Сергея 8900 рублей будет стоить. Кому нужно - сделаю дешевле 😉\nОбъясню, зачем, куда и как использовать ИИ, в пакет входить будет обучение экселю (от базы до работы со сводными).\nДумаю, уже пора. \n\nБез воды, без лишних слов. Только хардкорное обучение по сути","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/76"},{"id":73,"date":"2026-03-08","title":"По мотивам данной публикации, как ИИ повлияет на закупщиков: 1.","summary":"По мотивам данной публикации, как ИИ повлияет на закупщиков: 1. Бэкофис (координаторы+экспедиторы)- замена возможна на 85-90%.","summaryKind":"excerpt","text":"По мотивам данной публикации, как ИИ повлияет на закупщиков:\n1. Бэкофис (координаторы+экспедиторы)- замена возможна на 85-90%. За счет чего: IoT (датчики на машинах, складах), RPA + OCR (сверка документов), ввод заказов, сопоставление документов\n2. менеджеры по снабжению -50-70%: запросы и сравнение предложений, контрактов, контроль исполнения контрактов, ABCXYZ анализы - ChatGPT/ Claude/ DS и тд\n3. Категорийные / ведущие - 20-30%: электронные письма, простые переговоры по цене, чек-листы, анализ рынка, скоринг поставщиков (ИИ-агенты, RPA)\n\nЧеловеку останется стратегия. Простые исполнители будут не нужны. Где нужно это внедрять: в небольших компаниях, которые сейчас и так находятся под очень жестоким кредитным, сбытовым и налоговым давлением.","terms":["price-change","negotiation","market","supplier-risk","ai","automation","category"],"topics":["ai","data","function","negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/73"},{"id":72,"date":"2026-03-06","title":"10 трендов в ИИ в сопряжении с закупками: 1.","summary":"10 трендов в ИИ в сопряжении с закупками: 1. От экспериментов с ИИ к ИИ с ответственностью Компании переходят от хаотичных пилотов ChatGPT к системам с четкими KPI.","summaryKind":"excerpt","text":"10 трендов в ИИ в сопряжении с закупками:\n1. От экспериментов с ИИ к ИИ с ответственностью\nКомпании переходят от хаотичных пилотов ChatGPT к системам с четкими KPI. Вместо \"попробуем ИИ на тендерах\" внедряют ИИ-агенты с контролем: кто отвечает за прогноз цены, как меряется точность. Результат: экономия 10-15% на закупках фиксируется в дашборде, а не в презентации.\n\n2. От погони за минимальной ценой к устойчивым цепочкам\nЗакупки больше не ищут \"Китай за 10% дешевле\". Фокус на поставщиках в радиусе 1000 км: меньше логистических рисков, стабильные сроки, ESG-соответствие. Пример: отказ от дальнобойных поставок ради локальных даже за +5% к цене.\n\n3. От разрозненных процессов к единому контуру\nЗаявка в 1С, утверждение в почте, договор в DocuSign, оплата в банке. Теперь: единая платформа \"заявка → оплата\" за 3 клика. Power Query собирает данные из всех систем, ИИ предлагает оптимального поставщика из портфеля.\n\n4. От идеальных внедрений к быстрому запуску\nРаньше: год на интеграцию ERP. Сейчас: 30 дней на MVP с Thunderbit + ChatGPT + Excel. Быстрее ценность, быстрее обратная связь, быстрее ROI. Метод: 80/20 - решает 80% задач, остальные докрутят потом.\n\n5. От ESG-историй к измеримым показателям\nНе \"мы за экологию\", а \"CO2 поставщиков -12%, сертификаты проверены ИИ, отчет в ЕИС за 1 час\". Устойчивость становится KPI закупщика с аудитом, а не PR-отделом.\n\n6. От хаотичных списков к стратегическому портфелю\n500 поставщиков → 50 ключевых + 20 резервных. Каждый вендор имеет баллы: цена (30%), сроки (25%), риски (20%), ESG (15%), инновации (10%). Power Query ранжирует автоматически ежемесячно.\n\n7. От ретроспектива к онлайн-интеллекту расходов\nБухгалтерия дает spend за квартал. Теперь: дашборд \"сегодня потратили 2.3 млн, -15% к плану, 3 контракта истекают через 7 дней\". ChatGPT алертит: \"Поставщик X поднял цены на 8% - заменить?\".\n\n8. От регламентов к суждениям на данных\nЗакупщик не \"соблюдаю инструкцию\", а \"данные показывают риск 87% - беру резервного\". ИИ дает 3 варианта, человек выбирает с учетом политики компании и контекста.\n\n9. От транзакций к совместным инновациям\nПоставщик не \"дайте дешевле\", а \"разработаем под вас SKU с маржей +20%\". Совместные RFP: закупки + R&D + вендор. Результат: эксклюзивные продукты, которых нет у конкурентов.\n\n10. От бумажных политик к встроенному комплаенсу\nПолитика \"не работать с офшорами\" живет не в PDF, а в системе: ИИ блочит поставщиков из санкционных списков при загрузке прайса. 44-ФЗ чек-лист встроен в Power Query - заявка не пройдет без галочки. (Credits to precoro)\n\nПункт 6 даже сделала в виде автоматического scoring поставщика не так давно. Наглядно и красиво. #закупки #снабжение #ИИ #ИИвснабжении #скоринг #поставщики","terms":["supplier-risk","analytics","ai","automation","governance"],"topics":["ai","data","function","supplier"],"url":"https://t.me/notdandeliongirl/72"},{"id":70,"date":"2026-03-05","title":"Вчера возник разговор «Заменит ли ИИ такую профессию, как аналитики?», то есть , кто смотрят за отклонениями данных на рынке и внутри компании, делают прогнозы выводы, оказывающие влияние на бизнес.","summary":"Вчера возник разговор «Заменит ли ИИ такую профессию, как аналитики?», то есть , кто смотрят за отклонениями данных на рынке и внутри компании, делают прогнозы выводы, оказывающие влияние на бизнес. При зрелом размышлении – это уже происходит.","summaryKind":"excerpt","text":"Вчера возник разговор «Заменит ли ИИ такую профессию, как аналитики?», то есть , кто смотрят за отклонениями данных на рынке и внутри компании, делают прогнозы выводы, оказывающие влияние на бизнес.  \nПри зрелом размышлении – это уже происходит. \nДжунов прекрасно заменяют простые ИИ-ассистенты и модели на задачи «возьми данные, сведи их, посмотри отклонения, выдай» (ChatGPT + Numerous.ai, к примеру) . Миддлов – частично тоже, если подключить связку ИИ-агентов на сборку информация, поиск в интернете и модели на анализ отклонений (например, ChatGpT +Thunderbit + Coupa Navi) . \nСеньоров – процентов на 20-25% (не больше, у сеньоров пока есть опыт и экспертиза, которые не передать машине). \nЧего нет (пока нет) у ИИ –политических контекстов, скрытых мотивов, KPI, поведенческих моделей, неявных ограничений. Человек при  этом остается дирижером разных моделей для того, чтобы навести порядок в данных, то есть задать логику построения БД и приведения ее в норму, использовать нужные ему модели в нужный момент времени и иметь время на размышления, не тратя время на сборку отчетов. \nКапитан ли я очевидность? Сейчас да, потому что есть еще достаточное количество людей, искренне верящих в то, что остались профессии с довольно легким вхождением и где достаточно знать просто Excel. В компаниях  с раздутыми бюджетами это, безусловно, еще будет, однако, я думаю, многие уже сейчас и в ближайшем будущем будут уходить от этого в сторону «дирижеров». И нежелание / отмахивание от всего того, что может дать ИИ в  итоге приведет к разбитым надеждам.\n #ИИвЗакупках #ChatGPTдляЗакупок #ProcurementAI #ExcelИИ #АвтоматизацияСнабжения #Thunderbit #РискиПоставщиков #ABCанализ #ЦифровизацияЗакупок #Sourcing #закупки","terms":["supplier-risk","ai","automation","governance"],"topics":["ai","data","function","supplier"],"url":"https://t.me/notdandeliongirl/70"},{"id":69,"date":"2026-03-04","title":"AI для мониторинга рисков поставщиков","summary":"Анна рассматривает AI-агентов как инструмент раннего выявления supplier risk: финансовых проблем, задержек, региональных ограничений и других микротрендов. Ключевое условие — качественная единая база данных.","summaryKind":"summary","text":"Читала статью позавчера - Blind Spots to Breakpoints: SpottingSupplier Risk with AI, Author: Aaron Mcmillan, публикация от2 марта 2026 года. Кратко: как компании используют ИИ-агентов для непрерывного мониторинга данных о поставщиках. Это позволяет заранее выявлять ранние признаки рисков (финансовые трудности, сбои в поставках) и предотвращать нарушения в цепочках поставок. Ключевое условие эффективности — единая и качественная база данных. \nЧто такое микротренды? Например, в регионе поставщика ввели новые налоги или ограничения. Или поставщик стал задерживать поставки. Или же у поставщика стали расти кредитные обязательства. Этих трендов может быть много – главное, указать верный круг факторов, могущих оказать влияние. \nЧего нет у  многих компаний в России (не приучены мы к жестким порядкам, имхо, если компания не была в контуре западных, ибо Ordnung macht Frei)\n1.     Единая база данных – вот тут многие (многие \u003c>все) компании страдают от ее отсутствия. Наличие СРМ не всегда спасает, тк базу насыщают сотрудники, а рядовым специалистам часто лень делать это качественно. То есть обязательный шаг – это качественное ведение БД.\n2.     Наличие СБ – это отдельный «бес», который может принять отрицательное решение даже при максимально положительном портрете поставщика\n3.     В  тот же пункт 2 – управление доступами и корпоративной безопасностью – часто СБ – это люди старой закалки, которые предпочитают пере«любить», при этом далеко не всегда уступают IT-безопасности. Опять же имхо, по итогам работы во многих компаниях. Да, решается, но со скрипом и долго. \nПри этом я считаю, что многим компаниям (не говорю о крупных. Там, скорее всего, это внедрено) однозначно необходимо начать оперативно использовать связку «ИИ-агентов «сборщик»+ «аналитик»+ «прогнозист» и человека» для принятия совместного решения о возможных рисках и их влиянию на результат. Да и не только рисков – начал расти по показателям какой-то поставщик, появился у него новый завод, сразу же триггер – «обрати внимание». Алаверды в сторону клиентов и подрядчиков. СПАРК и прочие сервисы, при всем моем уважении, не имеют доступа в ERP-системы и СРМ, не шерстят тренды рынка и так далее.","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/69"},{"id":65,"date":"2026-03-03","title":"Вчера читала исследование Российского союза промышленников и предпринимателей (РСПП) по итогам января 2026 года: 1.","summary":"Вчера читала исследование Российского союза промышленников и предпринимателей (РСПП) по итогам января 2026 года: 1. Рост закупочных цен.","summaryKind":"excerpt","text":"Вчера читала исследование Российского союза промышленников и предпринимателей (РСПП) по итогам января 2026 года:\n1. Рост закупочных цен. Две трети компаний (66%) зафиксировали рост цен закупки в январе. Для сравнения: в декабре об этом сообщала только половина респондентов. Тренд явно ускоряется.\n2. Логистика трещит по швам. Доля компаний, столкнувшихся с логистическими проблемами, выросла с 11,8% в декабре до 20,7% в январе. Практически вдвое! И отдельно - выросли сроки доставки (об этом сказали 12% против 7,1% месяцем ранее).\n3. Спрос разнонаправленный. У 56% компаний спрос на продукцию не изменился, у 12,7% вырос, а у 31,3% - упал. Рынки штормит.\n\nЧто с этим делать?\nВо-первых, закладывать в бюджетирование на 2026 год гораздо более высокий уровень неопределенности по ценам. Во-вторых, пересматривать логистические стратегии: искать альтернативные маршруты и увеличивать страховые запасы по критическим позициям. В-третьих, отслеживать поставщиков на предмет их финансовой устойчивости (логистические проблемы часто валят слабых игроков).\n\nХорошая новость: финансовое положение 68% компаний пока стабильно. Но 22% уже отметили ухудшение.","terms":["safety-stock","price-change"],"topics":["inventory","negotiation","price"],"url":"https://t.me/notdandeliongirl/65"},{"id":61,"date":"2026-03-02","title":"ИИ-агенты уже здесь: Project44 автоматизирует фрахт Пока мы обсуждаем теорию, рынок движется вперед.","summary":"ИИ-агенты уже здесь: Project44 автоматизирует фрахт Пока мы обсуждаем теорию, рынок движется вперед. На прошлой неделе платформа Project44 (мировой лидер в видимости цепочек поставок) анонсировала запуск AI Freight Procurement Agent.","summaryKind":"excerpt","text":"ИИ-агенты уже здесь: Project44 автоматизирует фрахт\n\nПока мы обсуждаем теорию, рынок движется вперед. На прошлой неделе платформа Project44 (мировой лидер в видимости цепочек поставок) анонсировала запуск AI Freight Procurement Agent.\n\nЧто за зверь?\nЭто ИИ-агент встроенный в их TMS (транспортную систему). Он больше не просто показывает вам данные, он делает:\n✅ Автономный выбор перевозчика (на основе цены, срока и надежности).\n✅ Бенчмаркинг ставок в реальном времени против рынка.\n✅ Автоматические мини-тендеры среди пула перевозчиков.\n\nРезультаты пилотов (данные от Project44):\nСнижение затрат на фрахт - 4,1%.\nСокращение цикла закупок - до 75%!\nУменьшение ручной работы - 70%.\n\nМысль вслух:\nЭто не просто очередной софт. Это переход от «цифровизации процесса» к «автономным закупкам». Система сама договаривается, сама выбирает, сама запускает торги. Человек ставит лишь правила.\n\nКонечно, в России пока не везде такой уровень зрелости данных, но тренд очевиден. Если вы работаете с импортом или логистикой - рекомендую присмотреться, как работают эти алгоритмы.\n\nКто уже пробовал что-то подобное на российских платформах? Есть ли достойные аналоги?\n\n#логистика #ProcurementTech #ИИ #TMS #Project44 #транспорт","terms":["ai"],"topics":["ai"],"url":"https://t.me/notdandeliongirl/61"},{"id":60,"date":"2026-03-01","title":"🧠 ИИ в закупках: Миланские профессоры vs Реальность Коллеги, хочу поделиться любопытным исследованием, на которое наткнулась на днях.","summary":"🧠 ИИ в закупках: Миланские профессоры vs Реальность Коллеги, хочу поделиться любопытным исследованием, на которое наткнулась на днях. Группа ученых во главе с профессором Antonella Maria Moretto из Политехнического университета Милана (один из топовых европейских центров по исследованию закупок) опубликовала в журнале Journal of Purchasing and Supply Management свежую работу за январь 2026 года.","summaryKind":"excerpt","text":"🧠 ИИ в закупках: Миланские профессоры vs Реальность\n\nКоллеги, хочу поделиться любопытным исследованием, на которое наткнулась на днях. Группа ученых во главе с профессором Antonella Maria Moretto из Политехнического университета Милана (один из топовых европейских центров по исследованию закупок) опубликовала в журнале Journal of Purchasing and Supply Management свежую работу за январь 2026 года.\n\nО чем она?\nАвторы провели ретроспективный анализ шести лет обучения специалистов по закупкам (Purchasing and Supply Management). Их главный вывод: мы слишком заигрались в харды (техники, классификаторы, цифры) и забываем про софты.\n\nКлючевая мысль:\nПрофессор Moretto и её команда предлагают фреймворк, который делит навыки закупщика на 4 блока:\n\n1. Технические (основа).\n2. Межличностные (умение договариваться).\n3. Внутренние и внешние (понимание связей внутри компании и рынка).\n4. Стратегические (видение бизнеса).\n\nИх исследование доказывает, что успешный CPO будущего - это не просто «спец по тендерам», а гибрид, который сочетает анализ данных (спасибо ИИ) с эмпатией и стратегией. Они напрямую пишут: «Университеты и компании должны объединиться, чтобы растить такие кадры через project-based learning».\n\nМое резюме:\nПока мы спорим, заменит ли нас ИИ, Миланский политех уже знает, что ИИ заменит рутину, но оставит нам «голову и переговоры». Статья вышла в январе 2026, так что тема более чем актуальна.\n\nКто уже внедряет у себя project-based learning для развития команды? Делитесь опытом в комментариях!\n\n#закупки #аналитика #PSM #управлениеперсоналом #CPO","terms":["negotiation","ai"],"topics":["ai","negotiation"],"url":"https://t.me/notdandeliongirl/60"},{"id":59,"date":"2026-02-20","title":"Мой вариант матрицы Кралича.","summary":"Мой вариант матрицы Кралича. вводные нужно менять во вкладке справочники.","summaryKind":"excerpt","text":"#юзфултип\nМой вариант матрицы Кралича. вводные нужно менять во вкладке справочники. градация объема закупок аналогично ставятся самостоятельно (во вкладке справочника самая правая колонка). если внесете свои данные, не забудьте во вкладке \"матрица\" перевыбрать из выпадающего списка. Ааа, ну и сделана вкладка с дополнительными методами оценки","terms":["mdm","category"],"topics":["data","function"],"url":"https://t.me/notdandeliongirl/59"},{"id":58,"date":"2026-02-19","title":"Думаю, сделать свой вариант матрицы Кралича как шаблон в Excel.","summary":"Думаю, сделать свой вариант матрицы Кралича как шаблон в Excel. Надо кому?","summaryKind":"excerpt","text":"Думаю, сделать свой вариант матрицы Кралича как шаблон в  Excel. Надо кому? Или от лукавого? И вообще, напишите, плиз, о чем стоит написать, пардон за тавтологию","terms":["category"],"topics":["function"],"url":"https://t.me/notdandeliongirl/58"},{"id":57,"date":"2026-02-19","title":"Что такое анализ рынка, зачем он нужен, какая дорожная карта, какой итог?","summary":"Что такое анализ рынка, зачем он нужен, какая дорожная карта, какой итог? Анализ рынка закупаемой продукции является частью закупочной стратегии управляемой категории, когда вы не только знаете, кто основные игроки, но и понимаете, какие факторы влияют на структуру ценообразования, какие макрофакторы влияют на бизнес в целом, какие риски и возможности есть.","summaryKind":"excerpt","text":"Что такое анализ рынка, зачем он нужен, какая дорожная карта, какой итог?\nАнализ рынка закупаемой продукции является частью закупочной стратегии управляемой категории, когда вы не только знаете, кто основные игроки, но и понимаете, какие факторы влияют на структуру ценообразования, какие макрофакторы влияют на бизнес в целом, какие риски и возможности есть. Без анализа рынка ваши переговоры с поставщиком будут просто переговорами о споте / долгосрок с закрытыми глазами и вытягиваться исключительно (на 90%) силой вашей харизмы - говорю сейчас о большинстве случаев. \nАнализ рынка стоит начать с вопросов - что за продукт я покупаю? Чем он особенный? Кто его производит? Где? Где агломераты присутствия? Заводы модернизированные или старые? Продукт состоит из отечественных или импортных компонентов? Какое процентное соотношение этих компонентов? Компоненты под санкциями или нет? На сколько продукт зависит от курсов валют? Маркетинговые исследования отрасли? Финсостояние поставщиков?\nГде искать ответы - открытый доступ в интернете, запрос в ИИ-чаты, разговоры с поставщиками, маркетинговые отчеты по отрасли 1-2 годовой давности (просто для информации), различные телеграмм-канал по отрасли, новости компаний.\nКакой итог получаете - фактически, drill down: состояние отрасли, состояние регионов, инвестиции государства, рынок сбыта, зависимость от факторов влияния, состояние поставщика, формирование цены. И на переговорах вы уже не будете просто просить скидку, ибо- стандартно - мы давно работаем, у нас есть потенциал, объемы и так далее - а на правах сведущего человека давать отпор аргументам поставщика.","terms":["negotiation","market","analytics","ai","category"],"topics":["ai","data","function","negotiation","price","supplier"],"url":"https://t.me/notdandeliongirl/57"},{"id":54,"date":"2026-01-13","title":"сегодня решила дать вам полезные инструменты, которыми пользуюсь или пользовалась сама.","summary":"сегодня решила дать вам полезные инструменты, которыми пользуюсь или пользовалась сама. ну вот бывает иногда, когда нужно заморочиться чем-то.","summaryKind":"excerpt","text":"#юзфултип\nсегодня решила дать вам полезные инструменты, которыми пользуюсь или пользовалась сама. ну вот бывает иногда, когда нужно заморочиться чем-то.\n1) как оценить верно поставщика по бальной системе с учетом того, что иногда надо считать минимум=хорошо, а иногда -максимум=хорошо? во вложении формула, которую спокойно можно перенести как в экселе, так и в любую другую ERP  систему или модуль. Фразы \"а у нас автоматом все считается\" идут нахер. читаем внимательно жирненьким\n2) несмотря на наличие платежных календарей и прочего, иногда надо выгрузить в эксель оплаты и прикинуть, чего и кому платить. во втором файле учитываются переносы оплат с выходных на пятницу перед выходными\n3) и, наконец, надо посчитать, какой товар принес в выручку какой вклад. или в закупку по цене.","terms":[],"topics":["function"],"url":"https://t.me/notdandeliongirl/54"},{"id":47,"date":"2025-12-17","title":"Как проанализировать, нужна ли оптимизация, стоит ли сокращать кого-то, точки улучшения или «инициатива отымела иницииатора»: Спросили меня как-то, а как бы оценила загруженность и потребность автоматизации одного большого отдела, в котором трудится 100 человек в 5 городах.","summary":"Как проанализировать, нужна ли оптимизация, стоит ли сокращать кого-то, точки улучшения или «инициатива отымела иницииатора»: Спросили меня как-то, а как бы оценила загруженность и потребность автоматизации одного большого отдела, в котором трудится 100 человек в 5 городах. Я предложила план, этапы, порядок действий, как делать анализ.","summaryKind":"excerpt","text":"Как проанализировать, нужна ли оптимизация, стоит ли сокращать кого-то, точки улучшения или «инициатива отымела иницииатора»:\nСпросили меня как-то, а как бы оценила загруженность и потребность автоматизации одного большого отдела, в котором трудится 100 человек в 5 городах. Я предложила план, этапы, порядок действий, как делать анализ. Расписала все и…. «Помоги сделать».\nПоэтому ловите дорожную карту, куда идти. Скажу, как обычно говорю - у каждого свой путь, но, возможно, что-то пригодится. \n1. Анализируем СКУД за месяц. То есть сколько времени человек фактически находился на работе и сколько вне ее на печеньки, покурить, прогулки\n2. Запрашиваем обязанности (кратко), комментарии по ним (более подробно), затрачиваемое время в доле в %.\n3. Сводим всех по п2 в общее. Что проверяем: сумма времени по каждому должна быть равна 100% (было и 96 и 160%); доля обязанностей по должностной и факт; понимание того, что нужно делать (работа в эксель - это дичь какая-то); сравниваем сотрудников одной должности между собой и межфилиально; определяем избыточность функций; бюрократизм; куда уходит время \n4. Накладываем конверсию деятельности в результат\n5. Вуаля. У вас есть план.","terms":["automation"],"topics":["ai","data"],"url":"https://t.me/notdandeliongirl/47"},{"id":44,"date":"2025-08-31","title":"ТСО, отсрочка и стоимость денег","summary":"Анна связывает расчет ТСО / ССВ с реальной стоимостью денег для компании. Иногда более высокая себестоимость может быть выгоднее, если снижает нагрузку на кредитование и cash flow.","summaryKind":"summary","text":"Какой оптимальный процент ставки для расчета ССВ или ТСО в Английском варианте? Для меня это 16%. То есть средняя ставка кредита минус 4%. Все, что выше- на грани и неинтересно.\nСейчас многим компаниям выгоднее уйти в чуть большую себестоимость, но меньше обслуживать кредиты. \nИ помните, считать, что поставщик вам алаверднет условия оплаты, которые вы согласовали клиенту, утопия. Нет,  можно побороться, можно высосать поставщика досуха, но вот нужно вам будет что-то, вам не сделают. Потому что есть контракт- его выполняют до запятой. А есть партнерство и благодарность.","terms":["tco","deferral"],"topics":["finance","negotiation","price"],"url":"https://t.me/notdandeliongirl/44"},{"id":41,"date":"2024-11-28","title":"Как просить скидку у поставщика","summary":"Анна показывает, что скидка может запрашиваться по-разному: через прямой запрос, через обоснованный анализ рынка или через долгосрочные отношения с поставщиком.","summaryKind":"summary","text":"Как попросить скидку? 1. Взять и попросить \n2. Провести анализ рынка, сравнить цены на аналогичные товары, привести все цены к одному базису, обосновать позицию поставщику, провести переторжки или редукционы 3. «Слушай, директор требует скидос, попроси у своего,а? Ну, сколько дадите»\nИ вы-таки не поверите, но вариант 3 я считаю вполне себе нормальным, НО!\nДля этого нужно выстраивать с поставщиком долгосрочные дружеские отношения. Вы должны знать про его семью, интересы, предпочтения. Когда звоните - вы говорите не только о работе, а спрашиваете его об отвлеченных вещах. И тогда многие вещи станут значительно проще","terms":["market"],"topics":["price","supplier"],"url":"https://t.me/notdandeliongirl/41"},{"id":40,"date":"2024-10-18","title":"Что сейчас одно из важных направлений в любой крупной компании?","summary":"Что сейчас одно из важных направлений в любой крупной компании? Это проекты по автоматизации.","summaryKind":"excerpt","text":"Что сейчас одно из важных направлений в любой крупной компании? Это проекты по автоматизации. Не потому, что должно. А потому, что это дает столько возможностей!\nНе надо бояться, что роботы вас заменят. Нужно интересоваться этим вопросом, развиваться. Учиться работать с ними, изучать ИИ. \nИнформации сейчас столько, что запомнить и прочитать все просто нереально. Необходимо уметь брать выжимку, обращаться за какими-то вопросами в чат гпт или гига чат. И бесконечно познавать новое","terms":["ai","automation"],"topics":["ai","data"],"url":"https://t.me/notdandeliongirl/40"},{"id":36,"date":"2024-07-27","title":"Зачем чистить справочник материалов","summary":"Пост объясняет, почему НСИ и справочник материалов напрямую связаны с деньгами, планированием, ДДС и качеством закупочной аналитики.","summaryKind":"summary","text":"Почему важно заниматься регулярной чисткой и поддержкой справочника материалов?\n1. Это деньги компании. Без правильного разделения и план-факторного анализа аналитика летит в пизду\n2. Это порядок планирования затрат, ДДС и самих закупок\n3. Это четкий учет\nС чего нужно начинать?\n1. Разделения закупок по ответственным менеджерам и привязка менеджер -SKU в системе\n2. Создание иерархии хотя бы до 2 уровня (уровень родитель и подгруппа)\n3. Привязка SKU- родитель-подгруппа в ЕРП-системе\n4. Проверка дублей - как полное совпадение, так и неполное совпадение. Далее более глубокий машинный и аналитический анализ\n\nКоличество SKU порядка 180 тыс реально обработать примерно за 3 недели (3,5 пункта). Глубокий анализ дублей требует более длительного времени","terms":["mdm"],"topics":["data"],"url":"https://t.me/notdandeliongirl/36"},{"id":35,"date":"2024-02-29","title":"Почему не работают универсальные «жесткие переговоры»","summary":"Анна критикует универсальные техники жестких переговоров: если поставщик монополист или квази-монополист, скидка может быть недоступна, и закупщик должен заранее понимать, какие реальные рычаги у него есть.","summaryKind":"summary","text":"Все чаще получаю на почту предложения от различных коучей и каких-то неведомых центров пройти обучение «искусству закупок» и «жестким переговорам». Начинаю читать и… «стратегия жестких переговоров. Предварительные переговоры». (да-да, предварительные ласки необходимы, конечно же). «Выявление реальных целей поставщика. Убеждающее воздействие» (это как?!)  «мягкое резюмирование, контроль за соблюдением достигнутых договоренностей» (мне все больше текст напоминает пикап) \nДаже где-то красиво звучит, но! Товарищи, если политика поставщика от первого лица говорит «нет отсрочки» - то хоть голым перед ним попляшите – не даст. \nЕсли поставщик монополист, квази-монополист  - хрен вам, а не скидка. Ну, вот так вот бывает. \nЕдинственные варианты получения лучших условий с моей точки зрения и опыта: \n1) Новинка на рынке. Очень нужно на него выйти и вы первая или одна из первых ласточек. Да, возможны лучшие условия – требуйте все, в том числе и нематериальные блага. Взамен обещайте давать отзывы другим клиентам поставщика \n2) У вас есть альтернатива – тут прям можно в кресле раскинуться и понаглеть, потому что вы можете встать и уйти и поставщик это знает \n3) В данный момент времени поставщик просел по продажам и именно сейчас ему нужно заткнуть вами дыру –можно раскинуться в кресле, но очень осторожно. Потому что акция эта разовая и уповать на нее как на единственный успех не стоит \n4) Вы пипец какой крупный клиент и имеете большую долю в портфеле поставщика или поставщик очень сильно хочет поиметь от вас эту долю – кто в душе не хотел бы попробовать БДСМ? Вот тут прям «умоляй меня» \n5) Собственник компании ваш лучший друг – комментарии излишни) \nКто бы что не говорил, какие бы аргументы в пользу своей охуенности мне не приводили – не верю я в чудеса. Потому что бизнес есть бизнес, а не «мягкое резюмирование» или «убеждающее воздействие». И именно поэтому – готовьтесь к переговорам. Собирайте историю ваших взаимоотношений, анализируйте рынок, ищите новых поставщиков. Будьте врачами с медкартой пациента на этих встречах. И тогда, возможно, когда вам известен диагноз заранее, результат не будет болезненен, а будет просто предсказуем","terms":["deferral","monopoly","negotiation"],"topics":["finance","negotiation","supplier"],"url":"https://t.me/notdandeliongirl/35"},{"id":34,"date":"2024-01-25","title":"Лояльный руководитель – сатана или юродивый?","summary":"Лояльный руководитель – сатана или юродивый? Чем больше я работала под чьим-то руководством, тем более понимала, что желание любого подчиненного - это чтобы руководитель был лояльным.","summaryKind":"excerpt","text":"Лояльный руководитель – сатана или юродивый? \nЧем больше я работала под чьим-то руководством, тем более понимала, что желание любого подчиненного  - это чтобы руководитель был лояльным. Лояльным к потребностям пойти в ЖЭК, врачу, банк, отпустить домой в случае поноса. Я сама так хотела, чтобы никто не имел мои мозги «почему ты отпрашиваешься», а просто отпускал, здраво оценивая мой профессионализм и своевременность выполнения всех задач.  \nЧем больше я работаю руководителем, тем больше понимаю, что важнее был адекватным, а не столь лояльным. Игры в лояльность в итоге заканчиваются сначала регулярными дисциплинарными нарушениями и наглостью, а потом в случае прикрытия лавочки – смертельными обидами.  \nОчень небольшой % сотрудников, к которым именно лояльное отношение – честно заработали его. Но их, как я уже сказала, слишком мало. Что думаете? Как у вас?","terms":["price-change"],"topics":["negotiation","price"],"url":"https://t.me/notdandeliongirl/34"},{"id":33,"date":"2023-12-13","title":"Почему я считаю покер работающим тренажером для улучшения переговорных навыков?","summary":"Почему я считаю покер работающим тренажером для улучшения переговорных навыков? Любые переговоры -это синтез аргументов и человеческого фактора.","summaryKind":"excerpt","text":"Почему я считаю покер работающим тренажером для улучшения переговорных навыков? \nЛюбые переговоры -это синтез аргументов и человеческого фактора. Мы все готовимся к переговорам хоть как-то (не беру в расчет спонтанные, они тоже бывают): заранее находим аргументы и контраргументы, делаем аналитику за прошлый период, находим какой-то негатив, которым, на крайний случай, кинем в поставщика для оказания давления. Никого не собираюсь учить, все, безусловно, специалисты.  \nНо часто, следуя своему профессиональному опыту / совету коучей / т.д. мы забываем, что переговоры проводим не с роботом, а с человеком / ами. У него может быть плохое настроение, золотуха, просто неприятие вашего лица. И все ваши золотые правила хорошего переговорщика полетят к чертям. Поэтому покер. И не покер с компьютером, а с живыми людьми. И не каждый день, а хотя бы раз попробовать. Покер развивает умение читать по лицам, находить тонкие оттенки от «господи, какая ерунда» до «а вот это уже лучше»; учит понимать, когда надо притормозить, когда надавить, когда блефануть. Вызывает желание поизучать психологию – потому что вот не со всеми поставщиками надо придерживаться одной переговорной стратегии и стиля общения. Обучает мгновенному просчету вариантов «если- то» и «что еще в рукаве». В конце-концов, тренирует память и когнитивное восприятие. \nИнтересно услышать ваши комментарии, что помогает тренировать вам переговорные навыки? Какой самый успешный опыт переговоров у вас был? И по традиции – мнение автора может не совпадать с мнением аудитории.","terms":["negotiation","poker"],"topics":["negotiation"],"url":"https://t.me/notdandeliongirl/33"},{"id":32,"date":"2023-10-24","title":"Вчера поняла, что есть проблемы с командной работой и коммуникацией.","summary":"Вчера поняла, что есть проблемы с командной работой и коммуникацией. Сегодня осмыслила, что нужно делать.","summaryKind":"excerpt","text":"Вчера поняла, что есть проблемы с командной работой и коммуникацией. Сегодня осмыслила, что нужно делать. Завтра начну. \nПостоянные улучшения, нежелание вариться в одном и том же, желание развиваться и что-то придумывать- вот двигатель вашего развития и развития вашего отдела/департамента/управления. \nУ вас есть право на месяц валяния дурака. Далее снова в бой придумывать новое. \nКстати, когда-то давно я для себя решила, что театр начинается с вешалки, а компания с закупок. Именно от нас- умных, опытных, волшебных нас- зависит успех компании. И хотя многие считают нас обслуживающим звеном- отчасти это так- именно благодаря компания имеет более высокую оборачиваемость капитала, лучшую себестоимость и продуктовую линейку.","terms":["turnover"],"topics":["inventory"],"url":"https://t.me/notdandeliongirl/32"},{"id":31,"date":"2023-10-18","title":"Сделала дашборд по операционной деятельности ОМТС- все же нет ничего лучше наглядности!","summary":"Сделала дашборд по операционной деятельности ОМТС- все же нет ничего лучше наглядности! Учитесь, господа.","summaryKind":"excerpt","text":"Сделала дашборд по операционной деятельности ОМТС- все же нет ничего лучше наглядности! Учитесь, господа. Не ради кого-то-  для себя. \nУмение строить дашборды- в экселе, в БИ- добавляет вам ценности как сотруднику и вы может претендовать на новые должности и новые зарплаты","terms":["analytics"],"topics":["data"],"url":"https://t.me/notdandeliongirl/31"},{"id":28,"date":"2023-09-13","title":"почему мои собеседования с кандидатами длятся максимум 20-30 минут?","summary":"почему мои собеседования с кандидатами длятся максимум 20-30 минут? 1) время.","summaryKind":"excerpt","text":"почему мои собеседования с кандидатами длятся максимум 20-30 минут?\n1) время. Мне жаль его тратить на \"воду\"\n2) мне незачем тратить время на вопросы про предыдущее место работы, опыт и так далее, так как:\n2.1. на этапе просмотра резюме я отсеиваю кандидатов без нужного мне опыта работы (именно если опыт работы вообще не предполагал закупки или это была исключительно исполнительная работа \"разместиться на ЭТП\" или работа по ФЗ)\n2.2. на этапе просмотра я отсеиваю тех, кто пишет обязанности из должностной инструкции (это сразу видно)\n2.3. на том же этапе отсеиваю откровенное вранье и запредельные результаты (есть нормы, статистические погрешности, конечно, но иногда люди пиздят так, что стыдно мне)\n3) на самом собеседовании я спрашиваю людей в режиме реальных кейсов, так как мне важно знать ход их мыслей, ибо остальному можно научить (противоречие с п.2.1? нет. Закупщика можно научить новому и это займет меньше времени, чем вообще не закупщика)\n4) если мне кандидат нравится - я могу задать пару личных вопросов из серии \"когда выйдет\" / \"как бы хотелось развиваться на рабочем месте\".\nвсе. этого вполне достаточно для принятия решения. \nМои стандартные вопросы:\nа) есть 3 поставщика на узкоспециализированном рынке. у всех трех +/- одинаковые условия. выбрать нужно одного и доказать руководителю, почему выбран именно этот поставщик. по этой причине проведите переговоры с поставщиком , который вам больше понравится на предмет получения лучших условий. Монолог или диалог. \nпроходят этот пункт немногие. что тут важно - быстро сориентироваться, хорошо болтать языком, находить аргументы. уметь переключаться и слышать условия задачи\nб) есть 3 поставщика. у 1 - 10 рублей цена и условия оплаты 100% предоплата. у 2 - 11 рублей и оплата 50/50 в течение 20 дней. у 3 поставщика - 12 рублей и 100% отсрочка в течение 60 дней. отбор только по этим двум условиям. Кого выберете и почему?\nтут понимание коммерческих моментов и умение логически мыслить\nв) есть запрос от службы \"купите насос, нужен будет единоразово\". Порядок действий, кратко, от получения заявки до поступления на склад.\nтут понимание закупочных процессов и умение их правильно организовывать, а также проведение коммерческих переговоров. \nДанная методика отбора не подводила меня еще ни разу)\nНо не забываем также и о человеческих факторах - речь, умение вести диалог, тупо этика поведения.\nКак-то так.","terms":["deferral","negotiation","governance"],"topics":["finance","function","negotiation"],"url":"https://t.me/notdandeliongirl/28"}]};
